import React, { useRef, useState, useMemo } from 'react';
import { MatchState, MatchPeriod } from '../types';
import { Play, Pause, Ban, Flag, ChevronLeft, ChevronRight, RotateCcw } from 'lucide-react';

interface ScoreBoardProps {
  match: MatchState;
  onToggleTimer: () => void;
  onTimeout: (team: 'home' | 'away') => void;
  onCancelTimeout: (team: 'home' | 'away') => void;
  onFinishMatch: () => void;
  onPeriodChange?: (direction: 'next' | 'prev') => void;
  timeoutTimer: number | null;
  breakTimer: number | null;
  isDarkMode?: boolean;
}

export const ScoreBoard: React.FC<ScoreBoardProps> = ({ 
  match, 
  onToggleTimer, 
  onTimeout, 
  onCancelTimeout,
  onFinishMatch,
  onPeriodChange,
  timeoutTimer, 
  breakTimer,
  isDarkMode = false
}) => {
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const isBreak = match.period === MatchPeriod.BREAK;
  const isExtraTime = match.period === MatchPeriod.OT1 || match.period === MatchPeriod.OT2;
  const timerRefHome = useRef<ReturnType<typeof setTimeout> | null>(null);
  const timerRefAway = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLongPress = useRef(false);
  const [pressing, setPressing] = useState<'home' | 'away' | null>(null);

  const homeCanTimeout = match.homeTeam.timeoutsUsed < 3 && match.homeTeam.timeoutsThisHalf < 2 && !isExtraTime;
  const awayCanTimeout = match.awayTeam.timeoutsUsed < 3 && match.awayTeam.timeoutsThisHalf < 2 && !isExtraTime;

  const canFinishMatch = useMemo(() => {
    if (match.isActive || match.isFinished) return false;
    let isDraw = match.period === MatchPeriod.PENALTIES 
      ? match.score.homePenalties === match.score.awayPenalties 
      : match.score.home === match.score.away;
    if (isDraw) return false;

    const halfDur = match.config.halfDuration;
    const otDur = match.config.otDuration;

    if (match.period === MatchPeriod.SECOND_HALF) return match.timer >= halfDur * 2;
    if (match.period === MatchPeriod.OT1) return match.timer >= otDur;
    if (match.period === MatchPeriod.OT2) return match.timer >= otDur;
    if (match.period === MatchPeriod.PENALTIES) {
       const hShots = match.penaltySequence.home.length;
       const aShots = match.penaltySequence.away.length;
       const maxShots = match.config.penaltyShots || 5;
       if (hShots < maxShots || aShots < maxShots) {
          const remainingH = maxShots - hShots; 
          const remainingA = maxShots - aShots;
          if (match.score.homePenalties > match.score.awayPenalties + remainingA || match.score.awayPenalties > match.score.homePenalties + remainingH) return true;
          return false;
       }
       return (hShots === aShots) && (match.score.homePenalties !== match.score.awayPenalties);
    }
    return false;
  }, [match]);

  const handlePointerDown = (team: 'home' | 'away') => {
    if (team === 'home' && !homeCanTimeout) return;
    if (team === 'away' && !awayCanTimeout) return;

    isLongPress.current = false;
    setPressing(team);
    const timer = setTimeout(() => {
      onCancelTimeout(team);
      isLongPress.current = true;
      setPressing(null);
    }, 800);
    if (team === 'home') timerRefHome.current = timer;
    else timerRefAway.current = timer;
  };

  const handlePointerUp = (team: 'home' | 'away') => {
    setPressing(null);
    if (team === 'home') { if (timerRefHome.current) clearTimeout(timerRefHome.current); } 
    else { if (timerRefAway.current) clearTimeout(timerRefAway.current); }

    if (!isLongPress.current) {
        if (team === 'home' && homeCanTimeout) onTimeout('home');
        if (team === 'away' && awayCanTimeout) onTimeout('away');
    }
  };

  const renderTimeoutDots = (used: number, thisHalf: number, team: 'home' | 'away') => (
    <div className={`flex gap-1.5 items-center justify-center bg-gray-100 dark:bg-slate-800 rounded-lg px-2 py-1 h-8 shadow-inner`}>
      {[1, 2, 3].map(i => (
        <div 
          key={i} 
          className={`w-3 h-3 rounded-full border-2 transition-all ${i <= used ? (team === 'home' ? 'bg-red-500 border-red-600' : 'bg-blue-500 border-blue-600') : 'bg-transparent border-slate-300 dark:border-slate-600'}`}
        />
      ))}
    </div>
  );

  return (
    <div className={`flex flex-col w-full rounded-[2.5rem] p-4 shadow-xl border relative overflow-hidden transition-colors duration-300 ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>

      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-slate-50 to-transparent dark:from-slate-800/50 pointer-events-none opacity-50" />

      {/* 1. Period Header */}
      <div className="relative z-10 flex items-center justify-center gap-6 mb-4">
          {onPeriodChange && (
            <button onClick={() => onPeriodChange('prev')} className={`p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${isDarkMode ? 'text-slate-400' : 'text-slate-500'}`}>
              <ChevronRight size={24} strokeWidth={3} />
            </button>
          )}
          <div className={`text-base sm:text-lg font-black uppercase tracking-wider ${match.period === MatchPeriod.PENALTIES ? 'text-purple-600' : (isDarkMode ? 'text-slate-200' : 'text-slate-700')}`}>
             {match.period}
          </div>
          {onPeriodChange && (
            <button onClick={() => onPeriodChange('next')} className={`p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${isDarkMode ? 'text-slate-400' : 'text-slate-500'}`}>
              <ChevronLeft size={24} strokeWidth={3} />
            </button>
          )}
      </div>

      {/* 2. Main Score Area */}
      <div className="flex items-start justify-between relative z-10 px-2 sm:px-6">

        {/* RIGHT SIDE (HOME TEAM in RTL) */}
        <div className="flex flex-col items-center gap-3 flex-1">
           <h3 className="font-black text-sm sm:text-lg truncate max-w-[120px] text-center" style={{ color: match.homeTeam.color }}>
             {match.homeTeam.name}
           </h3>

           <div 
             className="w-20 h-20 sm:w-28 sm:h-28 rounded-[2rem] flex items-center justify-center shadow-2xl transition-transform transform hover:scale-105"
             style={{ backgroundColor: match.homeTeam.color }}
           >
             <span className="text-5xl sm:text-6xl font-black text-white drop-shadow-md">
               {match.score.home}
             </span>
           </div>

           {/* Timeout Controls Home */}
           <div className="flex flex-col gap-1 mt-1 w-full max-w-[120px]">
              <button 
                disabled={!homeCanTimeout || isBreak || match.isFinished}
                onPointerDown={() => handlePointerDown('home')}
                onPointerUp={() => handlePointerUp('home')}
                onPointerLeave={() => { if(timerRefHome.current) clearTimeout(timerRefHome.current); setPressing(null); }}
                className={`w-full py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm transition-all border
                   ${!homeCanTimeout || isBreak || match.isFinished 
                      ? 'bg-slate-100 text-slate-400 border-slate-200 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-600 cursor-not-allowed' 
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-200 dark:border-slate-700'}
                   ${pressing === 'home' ? 'scale-95 bg-red-50 border-red-200 text-red-500' : ''}
                `}
              >
                {pressing === 'home' ? 'ELAGUER...' : 'TIME-OUT'}
              </button>
              {renderTimeoutDots(match.homeTeam.timeoutsUsed, match.homeTeam.timeoutsThisHalf, 'home')}
           </div>
        </div>

        {/* CENTER (TIMER) */}
        <div className="flex flex-col items-center justify-start pt-2 mx-2 sm:mx-4">
            <div className={`relative w-36 h-32 sm:w-44 sm:h-36 bg-slate-950 rounded-[2.5rem] flex flex-col items-center justify-center shadow-2xl border-4 ${match.isActive ? 'border-green-500/30' : 'border-slate-800'}`}>
                {/* Timer Text */}
                <div className={`text-4xl sm:text-5xl font-mono font-black tracking-wider mb-2 ${match.isFinished ? 'text-red-500' : isBreak ? 'text-green-400' : 'text-white'}`}>
                    {match.isFinished ? "00:00" : formatTime(match.timer)}
                </div>

                {/* Play/Pause Button Floating */}
                <button 
                  onClick={onToggleTimer}
                  disabled={match.isFinished}
                  className={`absolute -bottom-5 w-14 h-14 rounded-full flex items-center justify-center shadow-lg border-4 border-white dark:border-slate-900 transition-transform active:scale-90 
                    ${match.isFinished ? 'bg-slate-700 cursor-not-allowed' : match.isActive ? 'bg-red-500 hover:bg-red-600' : 'bg-blue-600 hover:bg-blue-500'}`}
                >
                  {match.isFinished ? <Flag size={20} className="text-white" /> : match.isActive ? <Pause size={24} fill="white" className="text-white" /> : <Play size={24} fill="white" className="ml-1 text-white" />}
                </button>
            </div>

            {/* Timeout Overlay Display */}
            {timeoutTimer !== null && (
               <div className="mt-8 bg-red-600 text-white px-4 py-1 rounded-full text-xs font-black animate-pulse shadow-lg">
                  T.O: {timeoutTimer}s
               </div>
            )}

            {/* Finish Button below timer */}
            {canFinishMatch && (
                <button 
                    onClick={onFinishMatch}
                    className="mt-8 flex items-center gap-1.5 px-4 py-1.5 bg-black text-white text-[10px] font-black rounded-full shadow-lg hover:bg-slate-800 transition-all animate-in zoom-in"
                >
                    <Flag size={12} />
                    <span>إنهاء</span>
                </button>
            )}
             {match.isFinished && (
                <div className="mt-8 text-[10px] font-black text-red-500 bg-red-500/10 px-3 py-1 rounded-full">
                    منتهية
                </div>
            )}
        </div>

        {/* LEFT SIDE (AWAY TEAM in RTL) */}
        <div className="flex flex-col items-center gap-3 flex-1">
           <h3 className="font-black text-sm sm:text-lg truncate max-w-[120px] text-center" style={{ color: match.awayTeam.color }}>
             {match.awayTeam.name}
           </h3>

           <div 
             className="w-20 h-20 sm:w-28 sm:h-28 rounded-[2rem] flex items-center justify-center shadow-2xl transition-transform transform hover:scale-105"
             style={{ backgroundColor: match.awayTeam.color }}
           >
             <span className="text-5xl sm:text-6xl font-black text-white drop-shadow-md">
               {match.score.away}
             </span>
           </div>

           {/* Timeout Controls Away */}
           <div className="flex flex-col gap-1 mt-1 w-full max-w-[120px]">
              <button 
                disabled={!awayCanTimeout || isBreak || match.isFinished}
                onPointerDown={() => handlePointerDown('away')}
                onPointerUp={() => handlePointerUp('away')}
                onPointerLeave={() => { if(timerRefAway.current) clearTimeout(timerRefAway.current); setPressing(null); }}
                className={`w-full py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm transition-all border
                   ${!awayCanTimeout || isBreak || match.isFinished 
                      ? 'bg-slate-100 text-slate-400 border-slate-200 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-600 cursor-not-allowed' 
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-200 dark:border-slate-700'}
                   ${pressing === 'away' ? 'scale-95 bg-red-50 border-red-200 text-red-500' : ''}
                `}
              >
                {pressing === 'away' ? 'ELAGUER...' : 'TIME-OUT'}
              </button>
              {renderTimeoutDots(match.awayTeam.timeoutsUsed, match.awayTeam.timeoutsThisHalf, 'away')}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Officials, MatchDetails, ScheduledMatch } from '../types.ts';
import { Palette, Link, Crown, Shield } from 'lucide-react';

interface PlayerInput {
  number: string;
  name: string;
  isCaptain: boolean;
  isGoalkeeper: boolean;
}

interface SetupFormProps {
  onStart: (
    h: string, hcoach: string, hast: string, hdoc: string, hplayers: PlayerInput[], hcolor: string,
    a: string, acoach: string, aast: string, adoc: string, aplayers: PlayerInput[], acolor: string,
    halfDur: number, otDur: number, off: Officials, det: MatchDetails
  ) => void;
  isDarkMode?: boolean;
  schedule?: ScheduledMatch[];
  initialMatch?: ScheduledMatch | null;
}

const PRESET_COLORS = [
  { name: 'Bleu Pro', hex: '#1d4ed8' },
  { name: 'Rouge Intense', hex: '#b91c1c' },
  { name: 'Vert Forêt', hex: '#15803d' },
  { name: 'Jaune Or', hex: '#eab308' },
  { name: 'Noir Pur', hex: '#0f172a' },
  { name: 'Orange Feu', hex: '#ea580c' },
  { name: 'Violet Royal', hex: '#7e22ce' },
  { name: 'Gris Béton', hex: '#4b5563' },
];

export const SetupForm: React.FC<SetupFormProps> = ({ onStart, isDarkMode = false, schedule = [], initialMatch = null }) => {
  const [home, setHome] = useState(initialMatch?.homeTeam || 'فريق A');
  const [homeCoach, setHomeCoach] = useState('المدرب A');
  const [homeAst, setHomeAst] = useState('');
  const [homeDoc, setHomeDoc] = useState('');
  const [homeColor, setHomeColor] = useState(PRESET_COLORS[0].hex);
  const [homeCount, setHomeCount] = useState(12);
  const [homePlayers, setHomePlayers] = useState<PlayerInput[]>([]);

  const [away, setAway] = useState(initialMatch?.awayTeam || 'فريق B');
  const [awayCoach, setAwayCoach] = useState('المدرب B');
  const [awayAst, setAwayAst] = useState('');
  const [awayDoc, setAwayDoc] = useState('');
  const [awayColor, setAwayColor] = useState(PRESET_COLORS[1].hex);
  const [awayCount, setAwayCount] = useState(12);
  const [awayPlayers, setAwayPlayers] = useState<PlayerInput[]>([]);

  const [halfDur, setHalfDur] = useState(20);
  const [otDur, setOtDur] = useState(5);
  const [activeTab, setActiveTab] = useState<'details' | 'teamA' | 'teamB' | 'officials'>('details');

  const [details, setDetails] = useState<MatchDetails>({
    direction: 'المديرية الإقليمية', aref: 'الأكاديمية الجهوية', 
    categorie: initialMatch?.category || 'U15 FILLES',
    ville: 'المدينة', 
    lieu: initialMatch?.lieu || 'القاعة المغطاة', 
    sexe: 'F', numRencontre: '01',
    etape: 'REGIONALE', 
    date: initialMatch?.date || new Date().toISOString().split('T')[0], 
    time: initialMatch?.time || '16:00',
    matchLink: ''
  });

  const [officials, setOfficials] = useState<Officials>({
    referee1: initialMatch?.officials.referee1 || 'الحكم 1', 
    referee2: initialMatch?.officials.referee2 || 'الحكم 2', 
    timer: initialMatch?.officials.timer || 'الميقاتي', 
    secretary: initialMatch?.officials.secretary || 'المسجل', 
    chefCentre: initialMatch?.officials.chefCentre || 'رئيس المركز'
  });

  useEffect(() => {
    setHomePlayers(prev => {
      const next = [...prev];
      if (next.length < homeCount) {
        for (let i = next.length; i < homeCount; i++) {
            next.push({ number: String(i + 1), name: `لاعب ${i + 1}`, isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, homeCount);
      }
      return next;
    });
  }, [homeCount]);

  useEffect(() => {
    setAwayPlayers(prev => {
      const next = [...prev];
      if (next.length < awayCount) {
        for (let i = next.length; i < awayCount; i++) {
            next.push({ number: String(i + 1), name: `لاعب ${i + 1}`, isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, awayCount);
      }
      return next;
    });
  }, [awayCount]);

  const inputStyle = `w-full p-2 border rounded-xl text-xs font-bold outline-none transition-all ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white focus:border-blue-500' : 'bg-slate-800 border-slate-700 text-white focus:border-blue-400'}`;
  const labelStyle = "block text-[9px] font-black text-slate-500 uppercase mb-1 mr-1";

  const renderColorPicker = (currentColor: string, onSelect: (color: string) => void) => (
    <div className="space-y-1 mt-2">
      <label className={labelStyle}>لون الفريق</label>
      <div className="flex flex-wrap gap-2">
        {PRESET_COLORS.map((c) => (
          <button
            key={c.hex}
            onClick={() => onSelect(c.hex)}
            className={`w-6 h-6 rounded-lg border-2 transition-all ${currentColor === c.hex ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
            style={{ backgroundColor: c.hex }}
            title={c.name}
          />
        ))}
        <div className={`relative w-6 h-6 rounded-lg overflow-hidden border-2 transition-all flex items-center justify-center ${!PRESET_COLORS.some(c => c.hex === currentColor) ? 'border-white scale-110 shadow-lg' : 'border-slate-500/30 opacity-60 hover:opacity-100'}`} style={{ backgroundColor: !PRESET_COLORS.some(c => c.hex === currentColor) ? currentColor : 'transparent' }}>
             {!PRESET_COLORS.some(c => c.hex === currentColor) ? null : <Palette size={14} className={isDarkMode ? "text-white" : "text-black"} />}
             <input
                type="color"
                value={currentColor}
                onChange={(e) => onSelect(e.target.value)}
                className="absolute inset-0 w-[200%] h-[200%] -translate-x-1/4 -translate-y-1/4 opacity-0 cursor-pointer"
                title="لون مخصص"
            />
        </div>
      </div>
    </div>
  );

  const handlePlayerNumberChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].number = val;
    setter(next);
  };

  const toggleCaptain = (
      idx: number,
      players: PlayerInput[],
      setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
      const next = players.map((p, i) => ({
          ...p,
          isCaptain: i === idx ? !p.isCaptain : false // Ensure only one captain
      }));
      setter(next);
  };

  // toggleGoalkeeper Removed per request

  const renderPlayerInputs = (players: PlayerInput[], setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>) => (
    <div className="space-y-1 overflow-y-auto pr-1 custom-scrollbar flex-1 pb-4">
      {players.map((p, idx) => (
        <div key={idx} className={`flex gap-2 items-center p-1.5 rounded-xl border ${isDarkMode ? 'bg-slate-800/40 border-slate-700/50' : 'bg-slate-800/40 border-slate-700/50'}`}>
          <input 
            type="text" 
            className={`w-10 p-1.5 border rounded-lg text-center text-xs font-black outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-blue-400' : 'bg-slate-900 border-slate-700 text-blue-400'}`} 
            value={p.number} 
            onChange={e => handlePlayerNumberChange(idx, e.target.value, players, setter)} 
          />
          <input 
            type="text" 
            className={`flex-1 p-1.5 border rounded-lg text-right text-xs font-bold outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white' : 'bg-slate-900 border-slate-700 text-white'}`} 
            value={p.name} 
            onChange={e => {
              const next = [...players];
              next[idx].name = e.target.value;
              setter(next);
            }} 
          />
          {/* Roles Toggles - ONLY CAPTAIN */}
          <button 
             onClick={() => toggleCaptain(idx, players, setter)}
             className={`p-1.5 rounded-lg transition-colors border ${p.isCaptain ? 'bg-yellow-500 text-white border-yellow-600' : (isDarkMode ? 'bg-slate-800 text-slate-600 border-slate-700 hover:text-yellow-500' : 'bg-slate-100 text-slate-400 border-slate-200 hover:text-yellow-500')}`}
             title="عميد الفريق"
          >
             <Crown size={14} fill={p.isCaptain ? "currentColor" : "none"} />
          </button>
        </div>
      ))}
    </div>
  );

  return (
    <div className={`rounded-3xl shadow-xl border flex flex-col h-full overflow-hidden ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-900 border-slate-800'}`}>
      {/* Pinned Header */}
      <div className="p-4 text-center flex-shrink-0 border-b border-slate-700/50">
        <h2 className="text-xl font-black text-white">إعداد المباراة</h2>
        <div className={`flex p-1 rounded-xl mt-3 ${isDarkMode ? 'bg-slate-900/50' : 'bg-slate-950/50'}`}>
          {(['details', 'teamA', 'teamB', 'officials'] as const).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
              {tab === 'details' ? 'عام' : tab === 'teamA' ? 'A' : tab === 'teamB' ? 'B' : 'الحكام'}
            </button>
          ))}
        </div>
      </div>

      {/* Scrollable Content Area */}
      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar flex flex-col">
        {activeTab === 'details' && (
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <label className={labelStyle}>الأكاديمية الجهوية (AREF)</label>
              <input className={inputStyle} value={details.aref} onChange={e => setDetails({...details, aref: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className={labelStyle}>المديرية الإقليمية</label>
              <input className={inputStyle} value={details.direction} onChange={e => setDetails({...details, direction: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>رقم اللقاء</label>
              <input className={inputStyle} value={details.numRencontre} onChange={e => setDetails({...details, numRencontre: e.target.value})} />
            </div>
             <div>
              <label className={labelStyle}>المرحلة (Etape)</label>
              <input className={inputStyle} value={details.etape} onChange={e => setDetails({...details, etape: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className={labelStyle}>الفئة</label>
              <input className={inputStyle} value={details.categorie} onChange={e => setDetails({...details, categorie: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>مدة الشوط (د)</label>
              <input type="number" className={inputStyle} value={halfDur} onChange={e => setHalfDur(parseInt(e.target.value) || 0)} />
            </div>
            <div>
              <label className={labelStyle}>الشوط الإضافي (د)</label>
              <input type="number" className={inputStyle} value={otDur} onChange={e => setOtDur(parseInt(e.target.value) || 0)} />
            </div>
            <div className="col-span-2">
              <label className={labelStyle}>مركز التباري</label>
              <input className={inputStyle} value={details.lieu} onChange={e => setDetails({...details, lieu: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>التاريخ</label>
              <input type="date" className={inputStyle} value={details.date} onChange={e => setDetails({...details, date: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>التوقيت</label>
