            categorie: m.details.categorie,
            ville: m.details.ville,
            lieu: m.details.lieu,
            sexe: m.details.sexe,
            num_rencontre: m.details.numRencontre,
            etape: m.details.etape,
            date_match: m.details.date,
            heure_match: m.details.time,
            period: m.period,
            report: m.report,
            match_link: m.details.matchLink || null
        });

        // 2. Sync Players
        const playersToSync = [
            ...m.homeTeam.players.map(p => ({
                id: p.id,
                match_id: m.id,
                name: p.name,
                number: p.number,
                team_side: 'home',
                total_goals: p.goals
            })),
            ...m.awayTeam.players.map(p => ({
                id: p.id,
                match_id: m.id,
                name: p.name,
                number: p.number,
                team_side: 'away',
                total_goals: p.goals
            }))
        ];

        if (playersToSync.length > 0) {
            await client.from('players').upsert(playersToSync);
        }

        // 3. Sync Events (Goals, Sanctions, Timeouts)
        // Ensure distinct values for sanction_type to avoid "White Card" effect
        const eventsToSync = m.events.map(e => {
            let dbSanctionType = null;
            if (e.type === 'SANCTION') {
                // Force explicit string values for DB
                switch (e.sanctionType) {
                    case SanctionType.YELLOW: dbSanctionType = 'YELLOW'; break;
                    case SanctionType.RED: dbSanctionType = 'RED'; break;
                    case SanctionType.BLUE: dbSanctionType = 'BLUE'; break;
                    case SanctionType.TWO_MINUTES: dbSanctionType = '2MIN'; break;
                    default: dbSanctionType = e.sanctionType;
                }
            }

            return {
                id: e.id,
                match_id: m.id,
                type: e.type,
                team_side: e.team,
                player_id: e.playerId || null,
                player_name: e.playerName || null,
                sanction_type: dbSanctionType, // Explicit value
                time_str: e.timeStr,
                timestamp: e.timestamp
            };
        });

        if (eventsToSync.length > 0) {
             await client.from('match_events').upsert(eventsToSync);
        }

        // 4. Sync Penalty Shootouts
        // Only run if we are in penalties or if we have penalty data to prevent unnecessary calls
        if (m.period === MatchPeriod.PENALTIES || m.penaltySequence.home.length > 0 || m.penaltySequence.away.length > 0) {
             const penaltiesToSync = [
                ...m.penaltySequence.home.map((s, i) => ({
                    match_id: m.id,
                    team_side: 'home',
                    player_number: s.playerNumber,
                    player_name: s.playerName,
                    is_goal: s.goal,
                    shot_order: i + 1
                })),
                ...m.penaltySequence.away.map((s, i) => ({
                    match_id: m.id,
                    team_side: 'away',
                    player_number: s.playerNumber,
                    player_name: s.playerName,
                    is_goal: s.goal,
                    shot_order: i + 1
                }))
            ];

            // Delete existing records for this match to prevent duplicates and handle removed shots
            // Then insert current state
            await client.from('penalty_shootouts').delete().eq('match_id', m.id);

            if (penaltiesToSync.length > 0) {
                await client.from('penalty_shootouts').insert(penaltiesToSync);
            }
        }

    } catch (e) {
        console.error("Relational Sync Error", e);
    }
  };

  const syncStateToSupabase = useCallback(async (currentMatch: MatchState | null) => {
    if (!supabase || !currentMatch) return;
    setSyncStatus('syncing');
    try {
      const { data: appData } = await supabase.from('app_data').select('matches').eq('id', 1).single();
      let allMatches = appData?.matches || [];
      const idx = allMatches.findIndex((m: any) => m.id === currentMatch.id);
      if (idx > -1) allMatches[idx] = currentMatch; else allMatches.push(currentMatch);
      await supabase.from('app_data').upsert({ id: 1, matches: allMatches, updated_at: new Date().toISOString() });
      await syncRelationalData(supabase, currentMatch);
      setSyncStatus('synced');
    } catch (err: any) { setSyncStatus('error'); }
  }, [supabase]);

  const saveScheduleToSupabase = async (newSchedule: ScheduledMatch[]) => {
      setSchedule(newSchedule);
      if (!supabase) return;
      try {
          await supabase.from('app_data').update({ schedule: newSchedule }).eq('id', 1);
          setSyncStatus('synced');
      } catch (err: any) { setSyncStatus('error'); }
  };

  const stableMatchState = useMemo(() => {
    if (!match) return null;
    const { timer, ...criticalData } = match;
    return JSON.stringify(criticalData);
  }, [match]);

  useEffect(() => {
    if (!stableMatchState || !supabase || !dbInitialized) return;
    const t = setTimeout(() => { if (matchRef.current) syncStateToSupabase(matchRef.current); }, 1000); 
    return () => clearTimeout(t);
  }, [stableMatchState, supabase, dbInitialized, syncStateToSupabase]);

  const deleteMatch = async (id: string) => {
