      if (match?.id === id) { setMatch(null); setView('setup_choice'); }
      setSyncStatus('synced');
    } catch (err: any) { setSyncStatus('error'); }
  };

  const saveHistory = (m: MatchState) => setHistory(prev => [JSON.parse(JSON.stringify(m)), ...prev].slice(0, 15));

  const startMatch = (
    h: string, hc: string, hast: string, hdoc: string, hplayers: any[], hcol: string,
    a: string, ac: string, aast: string, adoc: string, aplayers: any[], acol: string, 
