    const newMatch: MatchState = {
      id: generateId(), details: det,
      homeTeam: { 
        name: h, color: hcol, coach: { name: hc, sanctions: [] }, assistantCoach: homeAssistant, doctor: hdoc,
        players: mapPlayers(hplayers, 'home'), timeoutsUsed: 0, timeoutsThisHalf: 0 
      },
      awayTeam: { 
        name: a, color: acol, coach: { name: ac, sanctions: [] }, assistantCoach: awayAssistant, doctor: adoc,
        players: mapPlayers(aplayers, 'away'), timeoutsUsed: 0, timeoutsThisHalf: 0 
      },
      officials: off, timer: 0, isActive: false, isFinished: false, period: MatchPeriod.FIRST_HALF, report: '',
      score: { 
        home: 0, away: 0, 
        homeP1: 0, awayP1: 0, 
        homeFullTime: undefined, awayFullTime: undefined,
        homeOT: undefined, awayOT: undefined,
        homePenalties: 0, awayPenalties: 0 
      },
      penaltySequence: { home: [], away: [], currentTurn: 'home' },
      config: { halfDuration: hd * 60, otDuration: od * 60, penaltyShots: 5 },
