const ScoreTable = ({ match }: { match: MatchState }) => {
  // Determine scores to display
  // 1st Half
  const hP1 = match.score.homeP1 > 0 ? match.score.homeP1 : (match.period !== MatchPeriod.FIRST_HALF ? match.score.homeP1 : '-');
  const aP1 = match.score.awayP1 > 0 ? match.score.awayP1 : (match.period !== MatchPeriod.FIRST_HALF ? match.score.awayP1 : '-');

  // Full Time (60m)
  // If match is in 2nd half, use current score. If past 2nd half, use stored fulltime score.
  const hFT = match.score.homeFullTime !== undefined ? match.score.homeFullTime : (match.period === MatchPeriod.SECOND_HALF || match.period === MatchPeriod.FIRST_HALF ? match.score.home : '-');
  const aFT = match.score.awayFullTime !== undefined ? match.score.awayFullTime : (match.period === MatchPeriod.SECOND_HALF || match.period === MatchPeriod.FIRST_HALF ? match.score.away : '-');

  // Extra Time
  // If match went to penalties, use homeOT. If currently in any OT, use current score.
  const isInOT = [MatchPeriod.OT1_H1, MatchPeriod.OT1_H2, MatchPeriod.OT2_H1, MatchPeriod.OT2_H2].includes(match.period);
  const hOT = match.score.homeOT !== undefined ? match.score.homeOT : (isInOT ? match.score.home : '-');
  const aOT = match.score.awayOT !== undefined ? match.score.awayOT : (isInOT ? match.score.away : '-');

  return (
    <div className="mb-0.5">
      <table className="w-full border-2 border-black text-[8px] text-center table-fixed border-collapse bg-white" style={{ fontFamily: "'Cairo', sans-serif" }}>
        <thead>
          <tr className="h-4 text-white">
            <th rowSpan={2} className="border border-black w-28 bg-black print:bg-black text-center align-middle">الفرق</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">شوط 1</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">نهاية</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">إضافي</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">7م</th>
            <th colSpan={2} className="border border-black bg-blue-700 text-white w-14 print:bg-blue-700 text-center align-middle">المجموع</th>
          </tr>
          {/* Sub-header for A and B */}
          <tr className="h-4 text-black font-black bg-gray-50 print:bg-gray-50">
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
          </tr>
        </thead>
        <tbody>
          <tr className="h-6 font-black text-[10px] text-black">
            <td className="border border-black text-[8px] bg-yellow-100 print:bg-yellow-100 text-black text-center align-middle">النتيجة</td>
            {/* Half Time Score */}
            <td className="border border-black text-black text-center align-middle">{hP1}</td> 
            <td className="border border-black text-black text-center align-middle">{aP1}</td>

            {/* End of Regulation (60 min) */}
            <td className="border border-black text-black text-center align-middle">{hFT}</td> 
            <td className="border border-black text-black text-center align-middle">{aFT}</td>

            {/* Extra Time */}
            <td className="border border-black text-black text-center align-middle">{hOT}</td> 
            <td className="border border-black text-black text-center align-middle">{aOT}</td>

            {/* Penalties */}
            <td className="border border-black text-black text-center align-middle">{match.score.homePenalties > 0 || match.score.awayPenalties > 0 ? match.score.homePenalties : '-'}</td> 
            <td className="border border-black text-black text-center align-middle">{match.score.homePenalties > 0 || match.score.awayPenalties > 0 ? match.score.awayPenalties : '-'}</td>

            {/* Final Total */}
            <td className="border border-black bg-yellow-300 print:bg-yellow-300 text-xs text-black text-center align-middle">{match.score.home + match.score.homePenalties}</td>
            <td className="border border-black bg-yellow-300 print:bg-yellow-300 text-xs text-black text-center align-middle">{match.score.away + match.score.awayPenalties}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

interface TeamRosterProps {
    team: Team;
    letter: string;
    onSign: (role: 'captain' | 'coach') => void;
}

const TeamRoster = ({ team, letter, onSign }: TeamRosterProps) => {
  const hasSanction = (p: Player, type: SanctionType) => p.sanctions.some(s => s.type === type);

  // FIX: Render fixed number of rows (14) to ensure grid lines appear even for empty slots
  const MIN_ROWS = 14;
  const filledPlayers = [...team.players];
  // Fill with nulls
  while (filledPlayers.length < MIN_ROWS) {
      filledPlayers.push(null as any);
  }

  const rows = filledPlayers.map((p, i) => {
    return (
      <tr key={i} className="h-[22px] text-[9px] text-center leading-none hover:bg-yellow-50 text-black">
        <td className="border-r border-b border-black font-black w-6 bg-gray-50 print:bg-gray-50 text-black text-center align-middle">{p?.number || ''}</td>

        {/* NAME CELL WITH ROLES */}
        <td className="border-r border-b border-black px-1 text-center font-bold truncate text-black align-middle" style={{ fontFamily: "'Cairo', sans-serif" }}>
          {p ? (
              <>
                {p.name}
                {p.isCaptain && <span className="font-black mr-1 text-[8px]">(C)</span>}
                {p.isGoalkeeper && <span className="font-black mr-1 text-[8px]">(G)</span>}
              </>
          ) : ''}
        </td>

        {/* Goals - FULL BORDER TO FIX PDF GRID ISSUE */}
        <td className="border-l border-r border-b border-black font-bold w-10 bg-gray-50 print:bg-gray-50 text-black text-center align-middle">
            {p && p.goals > 0 ? p.goals : ''}
        </td>

        <td className="border-r border-b border-black w-5 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.YELLOW) ? 'X' : ''}</td>
        <td className="border-r border-b border-black w-8 text-[8px] font-bold text-black text-center align-middle">
           <div className="flex items-center justify-center gap-0.5">
             {p?.sanctions.filter(s => s.type === SanctionType.TWO_MINUTES).map((_, idx) => <span key={idx}>2'</span>)}
           </div>
        </td>
        <td className="border-r border-b border-black w-5 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.RED) ? 'X' : ''}</td>
        {/* BLUE CARD COLUMN */}
        <td className="border-b border-black w-5 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.BLUE) ? 'X' : ''}</td>
      </tr>
    );
  });

  const captain = team.players.find(p => p.isCaptain);

  return (
    <div className="flex-1 flex flex-col">
      {/* Team Header - INCREASED HEIGHT (h-9) */}
      <div className="flex items-center justify-between bg-blue-700 print:bg-blue-700 text-white border-2 border-black px-2 h-9 mb-0.5">
        <div className="font-black text-xs flex items-center gap-2 flex-1 min-w-0">
            <div className="w-5 h-5 rounded-full bg-white text-blue-800 flex items-center justify-center text-[10px] border border-blue-200 shadow-sm flex-shrink-0">{letter}</div>
            <span className="truncate max-w-[220px] text-white" style={{ fontFamily: "'Cairo', sans-serif" }}>{team.name}</span>
        </div>
        {/* Timeouts - INCREASED HEIGHT (h-6) & TEXT SIZE */}
        <div className="flex border border-black bg-white text-black text-[9px] h-6 shadow-sm items-center flex-shrink-0">
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-bold text-black h-full">و.م 1</div>
           <div className="w-5 border-r border-black flex items-center justify-center font-black text-black h-full">{team.timeoutsUsed >= 1 ? 'X' : ''}</div>
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-bold text-black h-full">و.م 2</div>
           <div className="w-5 border-r border-black flex items-center justify-center font-black text-black h-full">{team.timeoutsUsed >= 2 ? 'X' : ''}</div>
           {/* 3RD TIMEOUT */}
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-bold text-black h-full">و.م 3</div>
           <div className="w-5 flex items-center justify-center font-black text-black h-full">{team.timeoutsUsed >= 3 ? 'X' : ''}</div>
        </div>
      </div>

      <div className="flex-1 border-2 border-black bg-white">
        <table className="w-full border-collapse table-fixed" dir="rtl">
            <thead className="bg-blue-50 print:bg-blue-50 text-[7px] uppercase font-black text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>
            <tr className="h-5 border-b border-black">
                <th className="border-l border-black w-6 text-black text-center align-middle">رقم</th>
                <th className="border-l border-black text-black text-center align-middle">الاسم والنسب</th>
                {/* Goals Header - FULL BORDER */}
