               <span>{team.coach.name}</span>
                {/* Signature Overlay if exists */}
               {team.signatures?.coach && (
                   <img src={team.signatures.coach} alt="Coach Sig" className="absolute left-1 top-0 h-full w-auto opacity-80 mix-blend-multiply" />
               )}
               {/* Trigger Icon - Always visible on screen, hidden in print, ignored by html2pdf */}
               <div data-html2canvas-ignore="true" className="absolute inset-0 bg-blue-500/5 hover:bg-blue-500/10 transition-opacity print:hidden flex items-center justify-center">
                    <PenTool size={12} className="text-blue-600 opacity-50 hover:opacity-100" />
               </div>
           </div>
           <div className="w-5 border-l border-black h-full flex items-center justify-center font-black text-[9px] bg-yellow-100 print:bg-yellow-100">
               {team.coach.sanctions.some(s => s.type === SanctionType.YELLOW) ? 'X' : ''}
