      initialMatch ? [] : DEFAULT_TEAM_A_PLAYERS.map(p => ({ ...p, isCaptain: false, isGoalkeeper: false }))
  );

  const [away, setAway] = useState(initialMatch?.awayTeam || 'إعدادية بدر');
