  const [awayCount, setAwayCount] = useState(initialMatch ? 12 : 14);
  const [awayPlayers, setAwayPlayers] = useState<PlayerInput[]>(
      initialMatch ? [] : DEFAULT_TEAM_B_PLAYERS.map(p => ({ ...p, isCaptain: false, isGoalkeeper: false }))
  );

