  });

  useEffect(() => {
    setHomePlayers(prev => {
      const next = [...prev];
      if (next.length < homeCount) {
        for (let i = next.length; i < homeCount; i++) {
            next.push({ number: String(i + 1), name: `لاعب ${i + 1}`, isCaptain: false, isGoalkeeper: false });
