            categorie: m.details.categorie,
            ville: m.details.ville,
            lieu: m.details.lieu,
            sexe: m.details.sexe,
            num_rencontre: m.details.numRencontre,
            etape: m.details.etape,
            date_match: m.details.date,
            heure_match: m.details.time,
            period: m.period,
            report: m.report,
            match_link: m.details.matchLink || null
