  MatchPeriod.FIRST_HALF,
  MatchPeriod.SECOND_HALF,
  MatchPeriod.OT1_H1,
  MatchPeriod.OT1_H2,
  MatchPeriod.OT2_H1,
  MatchPeriod.OT2_H2,
  MatchPeriod.PENALTIES
];

const App: React.FC = () => {
