                 </p>
              </div>
              <textarea 
                className={`w-full h-32 p-4 rounded-2xl border-2 outline-none font-bold text-sm resize-none mb-4 ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`}
