const PRESET_COLORS = [
  { name: 'Bleu Pro', hex: '#1d4ed8' },
  { name: 'Rouge Intense', hex: '#b91c1c' },
  { name: 'Vert Forêt', hex: '#15803d' },
  { name: 'Jaune Or', hex: '#eab308' },
  { name: 'Noir Pur', hex: '#0f172a' },
  { name: 'Orange Feu', hex: '#ea580c' },
  { name: 'Violet Royal', hex: '#7e22ce' },
  { name: 'Gris Béton', hex: '#4b5563' },
];

export const SetupForm: React.FC<SetupFormProps> = ({ onStart, isDarkMode = false, schedule = [], initialMatch = null }) => {
  // Initialisation avec des valeurs par défaut extraites de la feuille de match
  const [home, setHome] = useState(initialMatch?.homeTeam || 'اعدادية وادزا');
  const [homeCoach, setHomeCoach] = useState('حسن بوقدير');
  const [homeAst, setHomeAst] = useState('عمر حماني');
  const [homeColor, setHomeColor] = useState(PRESET_COLORS[4].hex); // Noir
  const [homeCount, setHomeCount] = useState(14);
  const [homePlayers, setHomePlayers] = useState<PlayerInput[]>([
    { number: '3', name: 'رشيد المنصوري', isCaptain: false, isGoalkeeper: false },
    { number: '4', name: 'حمزة السعيدي', isCaptain: false, isGoalkeeper: false },
    { number: '7', name: 'يوسف البقالي', isCaptain: false, isGoalkeeper: false },
    { number: '9', name: 'ياسين الحضيكي', isCaptain: false, isGoalkeeper: false },
    { number: '14', name: 'سليمان الدبوزي', isCaptain: false, isGoalkeeper: false },
    { number: '18', name: 'نبيل الفاسي', isCaptain: false, isGoalkeeper: false },
    { number: '19', name: 'عدنان الزروالي', isCaptain: false, isGoalkeeper: false },
    { number: '21', name: 'عادل الصقلي', isCaptain: false, isGoalkeeper: false },
    { number: '25', name: 'أنس الرماح', isCaptain: false, isGoalkeeper: false },
    { number: '27', name: 'فؤاد الكتاني', isCaptain: false, isGoalkeeper: false },
    { number: '30', name: 'مصطفى البصري', isCaptain: false, isGoalkeeper: false },
    { number: '32', name: 'كمال بنموسى', isCaptain: false, isGoalkeeper: false },
    { number: '33', name: 'خالد التازي', isCaptain: false, isGoalkeeper: false },
    { number: '36', name: 'طارق الحراق', isCaptain: false, isGoalkeeper: false },
  ]);

  const [away, setAway] = useState(initialMatch?.awayTeam || 'إعدادية بدر');
  const [awayCoach, setAwayCoach] = useState('سعيد الفكرود');
  const [awayAst, setAwayAst] = useState('زكرياء شرقي');
  const [awayColor, setAwayColor] = useState(PRESET_COLORS[2].hex); // Vert
  const [awayCount, setAwayCount] = useState(14);
  const [awayPlayers, setAwayPlayers] = useState<PlayerInput[]>([
    { number: '3', name: 'وليد الطاهري', isCaptain: false, isGoalkeeper: false },
    { number: '5', name: 'عبد الإله الوردي', isCaptain: false, isGoalkeeper: false },
    { number: '6', name: 'رياض الشرقاوي', isCaptain: false, isGoalkeeper: false },
    { number: '8', name: 'عمر بوعزة', isCaptain: false, isGoalkeeper: false },
    { number: '11', name: 'هشام العلوي', isCaptain: false, isGoalkeeper: false },
    { number: '12', name: 'مراد بنصالح', isCaptain: false, isGoalkeeper: false },
    { number: '15', name: 'أشرف المرزوقي', isCaptain: false, isGoalkeeper: false },
    { number: '17', name: 'يوسف الناصري', isCaptain: false, isGoalkeeper: false },
    { number: '20', name: 'مروان الزموري', isCaptain: false, isGoalkeeper: false },
    { number: '22', name: 'أمين الشمسي', isCaptain: false, isGoalkeeper: false },
    { number: '23', name: 'نور الدين الأنصاري', isCaptain: false, isGoalkeeper: false },
    { number: '29', name: 'إسماعيل الخرافي', isCaptain: false, isGoalkeeper: false },
    { number: '31', name: 'سفيان العلمي', isCaptain: false, isGoalkeeper: false },
    { number: '34', name: 'سليم أمزيل', isCaptain: false, isGoalkeeper: false },
  ]);

  const [halfDur, setHalfDur] = useState(20); 
  const [otDur, setOtDur] = useState(5);
  const [suspensionDur, setSuspensionDur] = useState(2); // 2 minutes or 1 minute
  const [activeTab, setActiveTab] = useState<'details' | 'teamA' | 'teamB' | 'officials'>('details');

  const [details, setDetails] = useState<MatchDetails>({
    direction: 'تاوريرت', 
    aref: 'الشرق', 
    categorie: initialMatch?.category || 'ذكور U15 - البطولة المدرسية',
    ville: 'تاوريرت', 
    lieu: initialMatch?.lieu || 'القاعة المغطاة (تاوريرت)', 
    sexe: 'M', 
    numRencontre: '1',
    etape: '', 
    date: initialMatch?.date || '2026-01-15', 
    time: initialMatch?.time || '15:00',
    matchLink: ''
  });

  const [officials, setOfficials] = useState<Officials>({
    referee1: initialMatch?.officials.referee1 || 'رضوان الكوت', 
    referee2: initialMatch?.officials.referee2 || 'فريد بنقدور', 
    timer: initialMatch?.officials.timer || '', 
    secretary: initialMatch?.officials.secretary || '', 
    chefCentre: initialMatch?.officials.chefCentre || ''
  });

  // Ensure player lists update if counts change manually
  useEffect(() => {
    setHomePlayers(prev => {
      const next = [...prev];
      if (next.length < homeCount) {
        for (let i = next.length; i < homeCount; i++) {
            next.push({ number: '', name: '', isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, homeCount);
      }
      return next;
    });
  }, [homeCount]);

  useEffect(() => {
    setAwayPlayers(prev => {
      const next = [...prev];
      if (next.length < awayCount) {
        for (let i = next.length; i < awayCount; i++) {
            next.push({ number: '', name: '', isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, awayCount);
      }
      return next;
    });
  }, [awayCount]);

  const inputStyle = `w-full p-2 border rounded-xl text-xs font-bold outline-none transition-all ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white focus:border-blue-500' : 'bg-slate-800 border-slate-700 text-white focus:border-blue-400'}`;
  const labelStyle = "block text-[9px] font-black text-slate-500 uppercase mb-1 mr-1";

  const renderColorPicker = (currentColor: string, onSelect: (color: string) => void) => (
    <div className="space-y-1 mt-2">
      <label className={labelStyle}>لون الفريق (للخلفية في ورقة المباراة)</label>
      <div className="flex flex-wrap gap-2">
        {PRESET_COLORS.map((c) => (
          <button
            key={c.hex}
            onClick={() => onSelect(c.hex)}
            className={`w-6 h-6 rounded-lg border-2 transition-all ${currentColor === c.hex ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
            style={{ backgroundColor: c.hex }}
            title={c.name}
          />
        ))}
        <div className={`relative w-6 h-6 rounded-lg overflow-hidden border-2 transition-all flex items-center justify-center ${!PRESET_COLORS.some(c => c.hex === currentColor) ? 'border-white scale-110 shadow-lg' : 'border-slate-500/30 opacity-60 hover:opacity-100'}`} style={{ backgroundColor: !PRESET_COLORS.some(c => c.hex === currentColor) ? currentColor : 'transparent' }}>
             {!PRESET_COLORS.some(c => c.hex === currentColor) ? null : <Palette size={14} className={isDarkMode ? "text-white" : "text-black"} />}
             <input
                type="color"
                value={currentColor}
                onChange={(e) => onSelect(e.target.value)}
                className="absolute inset-0 w-[200%] h-[200%] -translate-x-1/4 -translate-y-1/4 opacity-0 cursor-pointer"
                title="لون مخصص"
            />
        </div>
      </div>
    </div>
  );

  const handlePlayerNumberChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].number = val;
    setter(next);
  };

  const toggleCaptain = (
      idx: number,
      players: PlayerInput[],
      setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
      const next = players.map((p, i) => ({
          ...p,
          isCaptain: i === idx ? !p.isCaptain : false // Ensure only one captain
      }));
      setter(next);
  };

  const renderPlayerInputs = (players: PlayerInput[], setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>) => (
    <div className="space-y-1 overflow-y-auto pr-1 custom-scrollbar flex-1 pb-4">
      {players.map((p, idx) => (
        <div key={idx} className={`flex gap-2 items-center p-1.5 rounded-xl border ${isDarkMode ? 'bg-slate-800/40 border-slate-700/50' : 'bg-slate-800/40 border-slate-700/50'}`}>
          <input 
            type="tel" 
            pattern="[0-9]*"
            placeholder="#"
            className={`w-10 p-1.5 border rounded-lg text-center text-xs font-black outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-blue-400' : 'bg-slate-900 border-slate-700 text-blue-400'}`} 
            value={p.number} 
            onChange={e => handlePlayerNumberChange(idx, e.target.value, players, setter)} 
          />
          <input 
            type="text" 
            placeholder="اسم اللاعب"
            className={`flex-1 p-1.5 border rounded-lg text-right text-xs font-bold outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white' : 'bg-slate-900 border-slate-700 text-white'}`} 
            value={p.name} 
            onChange={e => {
              const next = [...players];
              next[idx].name = e.target.value;
              setter(next);
            }} 
          />
          {/* Roles Toggles - ONLY CAPTAIN */}
          <button 
             onClick={() => toggleCaptain(idx, players, setter)}
             className={`p-1.5 rounded-lg transition-colors border ${p.isCaptain ? 'bg-yellow-500 text-white border-yellow-600' : (isDarkMode ? 'bg-slate-800 text-slate-600 border-slate-700 hover:text-yellow-500' : 'bg-slate-100 text-slate-400 border-slate-200 hover:text-yellow-500')}`}
             title="عميد الفريق"
          >
             <Crown size={14} fill={p.isCaptain ? "currentColor" : "none"} />
          </button>
        </div>
      ))}
    </div>
  );

  return (
    <div className={`rounded-3xl shadow-xl border flex flex-col h-full overflow-hidden ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-900 border-slate-800'}`}>
      {/* Pinned Header */}
      <div className="p-4 text-center flex-shrink-0 border-b border-slate-700/50">
        <h2 className="text-xl font-black text-white">إعداد المباراة</h2>
        <div className={`flex p-1 rounded-xl mt-3 ${isDarkMode ? 'bg-slate-900/50' : 'bg-slate-950/50'}`}>
          {(['details', 'teamA', 'teamB', 'officials'] as const).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
              {tab === 'details' ? 'عام' : tab === 'teamA' ? 'A' : tab === 'teamB' ? 'B' : 'الحكام'}
            </button>
          ))}
        </div>
      </div>

      {/* Scrollable Content Area */}
      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar flex flex-col">
        {activeTab === 'details' && (
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <label className={labelStyle}>الأكاديمية الجهوية (AREF)</label>
              <input className={inputStyle} value={details.aref} onChange={e => setDetails({...details, aref: e.target.value})} />
