    });
  };

  const handleDeletePlayer = (side: 'home' | 'away', id: string) => {
    setMatch(prev => {
      if (!prev) return null;
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      const updatedPlayers = prev[teamKey].players.filter(p => p.id !== id);
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: updatedPlayers
        }
      };
    });
  };

  const handleConfirmBlueCard = () => {
    if (!match || !pendingBlueSanction) return;

    const { target, time } = pendingBlueSanction;
    const teamKey = target.team === 'home' ? 'homeTeam' : 'awayTeam';
    const reportAppend = `\n[${formatMMSS(time)}] بطاقة زرقاء - ${target.team === 'home' ? match.homeTeam.name : match.awayTeam.name}: ${reportTempText}`;

    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev };
      newMatch.report = (newMatch.report || '') + reportAppend;

      const team = { ...newMatch[teamKey] };

      if (target.type === 'player' && target.id) {
         const pIdx = team.players.findIndex(p => p.id === target.id);
         if (pIdx > -1) {
             const player = { ...team.players[pIdx] };
             player.sanctions = [...player.sanctions, { type: SanctionType.BLUE, timestamp: time }];
             team.players[pIdx] = player;

             newMatch.events.unshift({
                id: generateId(),
                type: 'SANCTION',
                timestamp: time,
                timeStr: formatMMSS(time),
                team: target.team,
                playerId: player.id,
                playerName: player.name,
                sanctionType: SanctionType.BLUE
             });
         }
      } else if (target.type === 'coach') {
         team.coach = { ...team.coach, sanctions: [...team.coach.sanctions, { type: SanctionType.BLUE, timestamp: time }] };
         newMatch.events.unshift({
            id: generateId(),
            type: 'SANCTION',
            timestamp: time,
            timeStr: formatMMSS(time),
            team: target.team,
            playerId: 'COACH',
            playerName: team.coach.name,
            sanctionType: SanctionType.BLUE
         });
      } else if (target.type === 'assistant-coach') {
         if (team.assistantCoach) {
             team.assistantCoach = { ...team.assistantCoach, sanctions: [...team.assistantCoach.sanctions, { type: SanctionType.BLUE, timestamp: time }] };
             newMatch.events.unshift({
                id: generateId(),
                type: 'SANCTION',
                timestamp: time,
                timeStr: formatMMSS(time),
                team: target.team,
                playerId: 'ASSISTANT_COACH',
                playerName: team.assistantCoach.name,
                sanctionType: SanctionType.BLUE
             });
         }
      }
      newMatch[teamKey] = team;
      return newMatch;
    });

    setReportTempText('');
    setPendingBlueSanction(null);
    setShowBlueModal(false);
