import React, { useRef, useState } from 'react';
import { SanctionType, MatchState } from '../types.ts';
import { Zap, Crosshair } from 'lucide-react';

interface ActionPanelProps {
  match: MatchState; 
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onAction: (type: 'goal' | '7m' | SanctionType, inc?: boolean) => void;
  onUndo: () => void;
  hasHistory: boolean;
  isDarkMode: boolean;
  matchActive: boolean;
  isTimeoutActive: boolean;
  playerSuspended: boolean;
}

export const ActionPanel: React.FC<ActionPanelProps> = ({
  match,
  selectedTarget,
  onAction,
  onUndo,
  hasHistory,
  isDarkMode,
  matchActive,
  isTimeoutActive,
  playerSuspended
}) => {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLongPress = useRef(false);
  const [activePress, setActivePress] = useState<string | null>(null);

  const handlePointerDown = (type: 'goal' | '7m' | SanctionType) => {
    isLongPress.current = false;
    setActivePress(type);
    timerRef.current = setTimeout(() => {
      isLongPress.current = true;
      onAction(type, false); // Trigger undo (inc = false)
      if (navigator.vibrate) navigator.vibrate([30, 30]); // Double haptic for undo
      setActivePress(null);
    }, 700); // 700ms for long press
  };

  const handlePointerUp = (type: 'goal' | '7m' | SanctionType) => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }

    if (!isLongPress.current && activePress === type) {
      onAction(type, true); // Trigger normal action (inc = true)
    }
    setActivePress(null);
  };

  const handlePointerLeave = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    setActivePress(null);
  };

  if (!selectedTarget) {
    return (
      <div className={`flex items-center justify-center p-4 rounded-2xl border-2 border-dashed ${isDarkMode ? 'border-slate-800 text-slate-500' : 'border-slate-200 text-slate-400'}`}>
        <div className="flex items-center gap-2">
          <TargetIcon />
          <span className="text-xs font-bold">حدد لاعباً أو مؤطراً لتنفيذ إجراء</span>
        </div>
      </div>
    );
  }

  const isPlayer = selectedTarget.type === 'player';
  const team = selectedTarget.team === 'home' ? match.homeTeam : match.awayTeam;

  // --- RÈGLES OFFICIELLES HANDBALL ---

  let isDisqualified = false;
  let hasBlueCard = false;
  let hasRedCard = false;
  let hasYellowCard = false;
  let twoMinCount = 0;
  let disqualificationReason = "ضغطة مطولة للإلغاء";

  if (isPlayer) {
    const player = team.players.find(p => p.id === selectedTarget.id);
    if (player) {
        hasRedCard = player.sanctions.some(s => s.type === SanctionType.RED);
        hasBlueCard = player.sanctions.some(s => s.type === SanctionType.BLUE);
        hasYellowCard = player.sanctions.some(s => s.type === SanctionType.YELLOW);
        twoMinCount = player.sanctions.filter(s => s.type === SanctionType.TWO_MINUTES).length;

        if (hasRedCard || hasBlueCard) {
            isDisqualified = true;
            disqualificationReason = hasBlueCard ? "اللاعب لديه بطاقة زرقاء" : "اللاعب مستبعد (بطاقة حمراء)";
        }
    }
  } else if (selectedTarget.type === 'coach') {
      hasBlueCard = team.coach.sanctions.some(s => s.type === SanctionType.BLUE);
      hasRedCard = team.coach.sanctions.some(s => s.type === SanctionType.RED);
      hasYellowCard = team.coach.sanctions.some(s => s.type === SanctionType.YELLOW);
      if(hasRedCard || hasBlueCard) isDisqualified = true;

  } else if (selectedTarget.type === 'assistant-coach') {
      hasBlueCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.BLUE) || false;
      hasRedCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.RED) || false;
      hasYellowCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.YELLOW) || false;
      if(hasRedCard || hasBlueCard) isDisqualified = true;
  }

  // Règle Buts
  const canGoal = isPlayer && !isTimeoutActive && !playerSuspended && !isDisqualified && matchActive;

  let goalTitle = "ضغطة مطولة للإلغاء";
  if (isDisqualified) goalTitle = disqualificationReason;
  else if (playerSuspended) goalTitle = "اللاعب موقوف";
  else if (isTimeoutActive) goalTitle = "وقت مستقطع";
  else if (!matchActive) goalTitle = "الميقات متوقف (لا يمكن التسجيل)";

  // Règle Carton Jaune
  let canYellow = !isDisqualified;
  let yellowReason = isDisqualified ? disqualificationReason : "ضغطة مطولة للإلغاء";

  if (isPlayer && canYellow) {
      if (hasYellowCard) {
          canYellow = false;
          yellowReason = "لديه بطاقة صفراء مسبقاً";
      } else {
           const teamPlayersYellowCount = team.players.reduce((total, p) => 
              total + p.sanctions.filter(s => s.type === SanctionType.YELLOW).length, 0
           );
           if (teamPlayersYellowCount >= 3) {
              canYellow = false;
              yellowReason = "الحد الأقصى (3) للفريق مكتمل";
           }
      }
  } else if (!isPlayer) {
      if (hasYellowCard) {
          canYellow = false;
          yellowReason = "لديه بطاقة صفراء";
      }
  }

  // Règle 2 Minutes
  const canTwoMin = !isDisqualified && (!isPlayer || twoMinCount < 2);
  const twoMinReason = isDisqualified ? disqualificationReason : (isPlayer && twoMinCount >= 2 ? "الحد الأقصى (2) لدقيقتين" : "ضغطة مطولة للإلغاء");

  // Règle Rouge
  const canRed = !isDisqualified; 

  // Règle Carte Bleue : 
  // ACTIVÉE UNIQUEMENT SI DÉJÀ ROUGE (et pas encore bleue)
  const canBlue = hasRedCard && !hasBlueCard;
  // Enable button if action is possible OR if we need to undo a blue card
  const enableBlueButton = canBlue || hasBlueCard;

  const btnBaseClass = "flex flex-col items-center justify-center gap-1 p-2 rounded-2xl border-2 transition-all shadow-sm select-none touch-none active:scale-95";
  const disabledClass = "bg-slate-500/10 border-slate-500/20 text-slate-500 cursor-not-allowed opacity-50 shadow-none active:scale-100";

  const renderActionButton = (
    type: 'goal' | '7m' | SanctionType, 
    label: string, 
    icon: React.ReactNode, 
    activeColorClass: string,
    enabled: boolean,
    title?: string
  ) => {
    const isPressed = activePress === type;

    return (
      <button
        disabled={!enabled}
        onPointerDown={() => enabled && handlePointerDown(type)}
        onPointerUp={() => enabled && handlePointerUp(type)}
        onPointerLeave={handlePointerLeave}
        className={`${btnBaseClass} ${enabled ? activeColorClass : disabledClass} ${isPressed ? 'scale-90 brightness-110 shadow-inner' : ''}`}
        title={title}
      >
        {icon}
        <span className="text-[10px] font-black">{label}</span>
      </button>
    );
  };

  return (
    <div className="grid grid-cols-3 sm:grid-cols-6 gap-2 w-full">
      {/* Goal Action */}
      {renderActionButton(
        'goal', 
        'هدف', 
        <Zap size={20} fill={canGoal ? "currentColor" : "none"} />, 
        'bg-green-600 border-green-500 text-white',
        canGoal,
        goalTitle
      )}

      {/* 7m Shot Action */}
      {renderActionButton(
        '7m', 
        '7 أمتار', 
        <Crosshair size={20} />, 
        'bg-indigo-600 border-indigo-500 text-white',
        canGoal,
        goalTitle
      )}

      {/* Yellow Card Action */}
      {renderActionButton(
        SanctionType.YELLOW, 
        'بطاقة صفراء', 
        <div className="w-4 h-6 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm" />, 
        'bg-yellow-400 border-yellow-500 text-yellow-950',
        canYellow || hasYellowCard, 
        hasYellowCard ? "ضغطة مطولة لإلغاء البطاقة" : yellowReason
      )}

      {/* 2 Minutes Suspension Action */}
      {renderActionButton(
        SanctionType.TWO_MINUTES, 
        'دقيقتين', 
        <div className="text-lg font-black leading-none">2'</div>, 
        'bg-slate-900 border-slate-700 text-white',
        canTwoMin || twoMinCount > 0, 
        twoMinReason
      )}

      {/* Red Card Action - Rouj */}
      {renderActionButton(
        SanctionType.RED, 
        'بطاقة حمراء', 
        <div className="w-4 h-6 bg-red-600 rounded-sm border border-red-800 shadow-sm" />, 
        'bg-red-600 border-red-700 text-white',
        canRed || hasRedCard, 
        hasRedCard ? "ضغطة مطولة لإلغاء البطاقة" : (isDisqualified ? "اللاعب مستبعد بالفعل" : "ضغطة مطولة للإلغاء")
      )}

      {/* Blue Card (Report) Action */}
      {renderActionButton(
        SanctionType.BLUE, 
        'بطاقة زرقاء', 
        <div className="w-4 h-6 bg-blue-600 rounded-sm border border-blue-800 shadow-sm" />, 
        'bg-blue-600 border-blue-700 text-white',
        enableBlueButton, 
        hasBlueCard ? "ضغطة مطولة لإلغاء البطاقة" : (!hasRedCard ? "يجب منح بطاقة حمراء أولاً" : "تقرير وكتابة سبب البطاقة الزرقاء")
      )}
    </div>
  );
};

const TargetIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg>
);

import React, { useState } from 'react';
import { Team, SanctionType, Player } from '../types.ts';
import { Trash2, X, Save, AlertCircle, UserPlus, Shield, Crown, Edit2 } from 'lucide-react';

interface TeamControlProps {
  team: Team;
  side: 'home' | 'away';
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onSelect: (target: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string }) => void;
  isDarkMode: boolean;
  onUpdatePlayer: (side: 'home' | 'away', id: string, data: Partial<Player>) => void;
  onDeletePlayer: (side: 'home' | 'away', id: string) => void;
  onAddPlayer: (side: 'home' | 'away', number: string, name: string) => void;
  onUpdateStaff?: (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => void;
}

export const TeamControl: React.FC<TeamControlProps> = ({ team, side, selectedTarget, onSelect, isDarkMode, onUpdatePlayer, onDeletePlayer, onAddPlayer, onUpdateStaff }) => {
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editName, setEditName] = useState('');
  const [editNumber, setEditNumber] = useState('');
  const [editIsCaptain, setEditIsCaptain] = useState(false);
  const [editIsGoalkeeper, setEditIsGoalkeeper] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Staff Editing
  const [editingStaff, setEditingStaff] = useState<'coach' | 'assistant-coach' | null>(null);

  // New Player State
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newNumber, setNewNumber] = useState('');

  const isCoachSelected = selectedTarget?.type === 'coach' && selectedTarget.team === side;
  const isAssistantSelected = selectedTarget?.type === 'assistant-coach' && selectedTarget.team === side;

  if (!team) return null;

  const handleDoubleClickPlayer = (p: Player) => {
    setEditingPlayer(p);
    setEditName(p.name);
    setEditNumber(p.number);
    setEditIsCaptain(p.isCaptain || false);
    setEditIsGoalkeeper(p.isGoalkeeper || false);
    setShowDeleteConfirm(false);
  };

  const handleDoubleClickStaff = (type: 'coach' | 'assistant-coach') => {
      setEditingStaff(type);
      setEditName(type === 'coach' ? team.coach.name : (team.assistantCoach?.name || ''));
  };

  const saveEdit = () => {
    if (editingPlayer) {
      onUpdatePlayer(side, editingPlayer.id, { 
          name: editName, 
          number: editNumber,
          isCaptain: editIsCaptain,
          isGoalkeeper: editIsGoalkeeper
      });
      setEditingPlayer(null);
    } else if (editingStaff && onUpdateStaff) {
        onUpdateStaff(side, editingStaff, editName);
        setEditingStaff(null);
    }
  };

  const handleAddSubmit = () => {
    if (newNumber.trim() && newName.trim()) {
      onAddPlayer(side, newNumber, newName);
      setNewName('');
      setNewNumber('');
      setShowAddModal(false);
    }
  };

  const closeEdit = () => {
    setEditingPlayer(null);
    setEditingStaff(null);
    setShowDeleteConfirm(false);
  };

  return (
    <div className={`flex flex-col h-full max-h-[85vh] gap-2 p-2 sm:p-3 rounded-3xl border-2 transition-all ${selectedTarget?.team === side ? 'border-blue-500 shadow-xl' : isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="flex items-center justify-between mb-1 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-3 h-6 rounded-full shadow-inner" style={{ backgroundColor: team.color || '#ccc' }}></div>
          <h3 className="font-black text-sm sm:text-base uppercase tracking-tight truncate max-w-[100px] sm:max-w-none">{team.name || 'فريق'}</h3>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
          className={`p-1.5 rounded-lg transition-all hover:scale-110 active:scale-95 ${isDarkMode ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-600/30' : 'bg-blue-100 text-blue-600 hover:bg-blue-200'}`}
          title="إضافة لاعب جديد"
        >
          <UserPlus size={16} strokeWidth={3} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-player-scrollbar">
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 pb-2">
          {team.players?.map((p) => {
            const isSelected = selectedTarget?.type === 'player' && selectedTarget.id === p.id;
            const isRed = p.sanctions?.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
            const yellowSanc = p.sanctions?.filter(s => s.type === SanctionType.YELLOW) || [];
            const twoMinSancs = p.sanctions?.filter(s => s.type === SanctionType.TWO_MINUTES) || [];
            const active2Min = twoMinSancs.find(s => s.remainingTime && s.remainingTime > 0);

            return (
              <button
                key={p.id}
                onClick={() => onSelect({ type: 'player', team: side, id: p.id })}
                onDoubleClick={() => handleDoubleClickPlayer(p)}
                className={`
                  relative h-16 sm:h-20 rounded-2xl flex flex-col items-center justify-center transition-all duration-200 border-2 flex-shrink-0 select-none
                  ${isRed ? 'bg-red-950/20 border-red-900/50 grayscale opacity-70' : 
                    isSelected ? 'bg-blue-600 border-blue-400 scale-[1.02] shadow-xl text-white' : 
                    isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500 text-slate-100' : 'bg-slate-50 border-slate-200 hover:border-blue-300 text-slate-800'}
                `}
              >
                <span className="text-xl sm:text-2xl font-black leading-none">{p.number}</span>
                <span className={`text-[8px] sm:text-[9px] font-bold truncate w-full px-1 text-center mt-0.5 ${isSelected ? 'text-blue-100' : 'text-slate-500'}`}>{p.name}</span>

                {/* Role Indicators */}
                <div className="absolute top-1 right-1 flex flex-col gap-0.5">
                   {p.isCaptain && <Crown size={10} className="text-yellow-500 fill-yellow-500" />}
                   {p.isGoalkeeper && <Shield size={10} className="text-gray-400 fill-gray-400" />}
                </div>

                <div className="absolute top-1 left-1 flex flex-col gap-0.5">
                  {yellowSanc.map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm"></div>
                  ))}
                  {twoMinSancs.slice(0, 2).map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-slate-950 rounded-sm border border-slate-700 flex items-center justify-center text-[6px] sm:text-[7px] text-white font-black">2</div>
                  ))}
                  {isRed && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-red-600 rounded-sm border border-red-800 shadow-sm"></div>
                  )}
                </div>

                {active2Min && (
                  <div className="absolute -top-2 -right-1 bg-black text-white text-[8px] px-1 py-0.5 rounded-full font-mono font-bold border border-slate-700 animate-pulse z-10">
                    {Math.floor(active2Min.remainingTime! / 60)}:{(active2Min.remainingTime! % 60).toString().padStart(2, '0')}
                  </div>
                )}

                {p.goals > 0 && (
                  <div className={`absolute -bottom-1 -left-1 w-5 h-5 sm:w-6 sm:h-6 rounded-full flex items-center justify-center text-[9px] sm:text-[11px] font-black shadow-lg border-2 ${isSelected ? 'bg-white text-blue-600 border-blue-100' : 'bg-green-600 text-white border-green-700'}`}>
                    {p.goals}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-1 pt-2 border-t space-y-2 flex-shrink-0">
          <button 
            onClick={() => onSelect({ type: 'coach', team: side })}
            onDoubleClick={() => handleDoubleClickStaff('coach')}
            className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isCoachSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
          >
