export const MatchSheet: React.FC<{ match: MatchState; onUpdate: (m: MatchState) => void }> = ({ match, onUpdate }) => {
  useEffect(() => { ensureArabicFont(); }, []);

  const [signatureModal, setSignatureModal] = useState<{
      open: boolean;
      title: string;
      onSave: (data: string) => void;
  }>({ open: false, title: '', onSave: () => {} });

  // Simple text input modal (using window.prompt for simplicity as requested "with a button")
  // Or better, a small inline modal state
  const handleEditReservation = (team: 'home' | 'away') => {
      const currentText = team === 'home' ? match.homeTeam.reservations : match.awayTeam.reservations;
      const newText = window.prompt("أدخل التحفظات / الاحترازات للفريق:", currentText || "");
      if (newText !== null) {
          const newMatch = { ...match };
          if (team === 'home') newMatch.homeTeam.reservations = newText;
          else newMatch.awayTeam.reservations = newText;
          onUpdate(newMatch);
      }
  };

  const handlePrint = () => window.print();

  const handleDownload = async () => {
    await document.fonts.ready;
    generateMatchSheetPDF('match-sheet-content', match.homeTeam.name, match.awayTeam.name);
  };

  const openSignature = (title: string, onSave: (data: string) => void) => {
      setSignatureModal({ open: true, title, onSave });
  };

  const handleTeamSign = (team: 'home' | 'away', role: 'captain' | 'coach') => {
      const teamName = team === 'home' ? match.homeTeam.name : match.awayTeam.name;
      const roleName = role === 'captain' ? 'عميد الفريق' : 'المدرب';

      openSignature(`توقيع ${roleName} - ${teamName}`, (data) => {
          const newMatch = { ...match };
          const t = team === 'home' ? newMatch.homeTeam : newMatch.awayTeam;
          if (!t.signatures) t.signatures = {};
          t.signatures[role] = data;
          onUpdate(newMatch);
      });
  };

  const handleOfficialSign = (role: 'referee1' | 'referee2' | 'timer' | 'secretary') => {
      let roleName = '';
      if (role === 'referee1') roleName = 'الحكم 1';
      if (role === 'referee2') roleName = 'الحكم 2';
      if (role === 'timer') roleName = 'الميقاتي';
      if (role === 'secretary') roleName = 'المسجل';

      openSignature(`توقيع ${roleName}`, (data) => {
          const newMatch = { ...match };
          if (!newMatch.officials.signatures) newMatch.officials.signatures = {};
          newMatch.officials.signatures[role] = data;
          onUpdate(newMatch);
      });
  };

  const winnerName = match.score.home + match.score.homePenalties > match.score.away + match.score.awayPenalties
      ? match.homeTeam.name 
      : match.score.away + match.score.awayPenalties > match.score.home + match.score.homePenalties
      ? match.awayTeam.name 
      : "تعادل";

  return (
    <div className="bg-gray-200 min-h-screen p-4 font-sans text-black print:p-0 print:bg-white flex flex-col items-center">

      {/* Actions (Hidden in Print) */}
      <div className="w-[210mm] mb-4 flex justify-end gap-2 print:hidden">
        <button onClick={handleDownload} className="px-6 py-2 bg-red-600 text-white rounded-xl font-bold text-sm flex gap-2 items-center hover:bg-red-700 shadow-lg transition-colors">
           <Download size={18}/> PDF
        </button>
        <button onClick={handlePrint} className="px-6 py-2 bg-black text-white rounded-xl font-bold text-sm flex gap-2 items-center hover:bg-gray-800 shadow-lg transition-colors">
           <Printer size={18}/> Imprimer
        </button>
      </div>

      {/* A4 SHEET CONTAINER - 210mm x 297mm */}
      <div 
        id="match-sheet-content" 
        className="w-[210mm] min-h-[296mm] bg-white p-[5mm] shadow-2xl print:shadow-none print:w-[210mm] print:h-[297mm] box-border flex flex-col relative mx-auto overflow-hidden"
        style={{ fontFamily: "'Inter', sans-serif" }}
      >
        <SheetHeader details={match.details} />
        <MatchInfo details={match.details} />
        <ScoreTable match={match} />

        {/* Rosters A & B */}
        <div className="flex gap-1 mb-0.5 flex-1 h-auto">
           <TeamRoster 
              team={match.homeTeam} 
              letter="A" 
              teamSide="home"
              matchEvents={match.events}
              onSign={(role) => handleTeamSign('home', role)} 
              onEditReservation={() => handleEditReservation('home')}
           />
           <TeamRoster 
              team={match.awayTeam} 
              letter="B" 
              teamSide="away"
              matchEvents={match.events}
              onSign={(role) => handleTeamSign('away', role)} 
              onEditReservation={() => handleEditReservation('away')}
           />
        </div>

        {/* Goal Logs - inserted here */}
        <div className="flex gap-1 mb-0.5">
            <div className="flex-1">
                <GoalsLog team={match.homeTeam} events={match.events} side="home" />
            </div>
            <div className="flex-1">
                <GoalsLog team={match.awayTeam} events={match.events} side="away" />
            </div>
        </div>

        {/* Footer */}
        <div className="flex-shrink-0 mt-auto">
            <div className="border-2 border-black flex h-14 mb-0.5 bg-white">
                <div className="flex-1 border-r-2 border-black p-1 flex flex-col justify-between text-[7px] text-black">
                    <div>
                        <span className="font-black underline mb-0.5 block text-blue-800" style={{ fontFamily: "'Cairo', sans-serif" }}>المسؤولون:</span>
                        <div className="flex justify-between border-b border-dotted border-gray-400 mb-0.5 cursor-pointer group" onClick={() => handleOfficialSign('secretary')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>المسجل: {match.officials.secretary}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.secretary ? <img src={match.officials.signatures.secretary} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                        <div className="flex justify-between cursor-pointer group" onClick={() => handleOfficialSign('timer')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>الميقاتي: {match.officials.timer}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.timer ? <img src={match.officials.signatures.timer} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 border-r-2 border-black p-1 flex flex-col justify-between text-[7px] text-black">
                    <div>
                        <span className="font-black underline mb-0.5 block text-blue-800" style={{ fontFamily: "'Cairo', sans-serif" }}>الحكام:</span>
                        <div className="flex justify-between border-b border-dotted border-gray-400 mb-0.5 cursor-pointer group" onClick={() => handleOfficialSign('referee1')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>1. {match.officials.referee1}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.referee1 ? <img src={match.officials.signatures.referee1} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                        <div className="flex justify-between cursor-pointer group" onClick={() => handleOfficialSign('referee2')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>2. {match.officials.referee2}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.referee2 ? <img src={match.officials.signatures.referee2} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                    </div>
                </div>

                <div className="w-28 p-1 flex flex-col items-center justify-center bg-yellow-50 print:bg-yellow-50">
                    <div className="bg-black text-white px-2 py-0.5 font-black mb-1 text-[7px] rounded-sm shadow-sm" style={{ fontFamily: "'Cairo', sans-serif" }}>الفريق الفائز</div>
                    <div className="flex items-center justify-center w-full h-full text-black">
