                    <div>
                        <span className="font-black underline mb-0.5 block text-blue-800" style={{ fontFamily: "'Cairo', sans-serif" }}>المسؤولون:</span>
                        <div className="flex justify-between border-b border-dotted border-gray-400 mb-0.5 cursor-pointer group" onClick={() => handleOfficialSign('secretary')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>المسجل: {match.officials.secretary}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.secretary ? <img src={match.officials.signatures.secretary} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                        <div className="flex justify-between cursor-pointer group" onClick={() => handleOfficialSign('timer')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>الميقاتي: {match.officials.timer}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.timer ? <img src={match.officials.signatures.timer} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 border-r-2 border-black p-1 flex flex-col justify-between text-[7px] text-black">
                    <div>
                        <span className="font-black underline mb-0.5 block text-blue-800" style={{ fontFamily: "'Cairo', sans-serif" }}>الحكام:</span>
                        <div className="flex justify-between border-b border-dotted border-gray-400 mb-0.5 cursor-pointer group" onClick={() => handleOfficialSign('referee1')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>1. {match.officials.referee1}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.referee1 ? <img src={match.officials.signatures.referee1} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                        <div className="flex justify-between cursor-pointer group" onClick={() => handleOfficialSign('referee2')}>
                            <span className="truncate text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>2. {match.officials.referee2}</span> 
                            <span className="text-gray-400 italic relative w-10 text-center">
                                {match.officials.signatures?.referee2 ? <img src={match.officials.signatures.referee2} className="absolute top-1/2 -translate-y-1/2 left-0 h-4 mix-blend-multiply" alt="Sig" /> : '(Sign)'}
                                <PenTool data-html2canvas-ignore="true" size={10} className="absolute -right-3 top-0 text-blue-500 print:hidden opacity-50 group-hover:opacity-100" />
                            </span>
                        </div>
                    </div>
                </div>

                <div className="w-28 p-1 flex flex-col items-center justify-center bg-yellow-50 print:bg-yellow-50">
                    <div className="bg-black text-white px-2 py-0.5 font-black mb-1 text-[7px] rounded-sm shadow-sm" style={{ fontFamily: "'Cairo', sans-serif" }}>الفريق الفائز</div>
                    <div className="flex items-center justify-center w-full h-full text-black">
                        <span 
                            className="text-[10px] font-black text-center" 
                            style={{ fontFamily: "'Cairo', sans-serif", direction: 'rtl' }}
