            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">نهاية</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">إضافي 1</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">إضافي 2</th>
