            <td className="border border-black text-black text-center align-middle">{hFT}</td> 
            <td className="border border-black text-black text-center align-middle">{aFT}</td>

            {/* Extra Time 1 */}
            <td className="border border-black text-black text-center align-middle">{hOT}</td> 
            <td className="border border-black text-black text-center align-middle">{aOT}</td>

            {/* Extra Time 2 */}
            <td className="border border-black text-black text-center align-middle">{hOT2}</td> 
            <td className="border border-black text-black text-center align-middle">{aOT2}</td>

            {/* Penalties */}
            <td className="border border-black text-black text-center align-middle">{match.score.homePenalties > 0 || match.score.awayPenalties > 0 ? match.score.homePenalties : '-'}</td> 
            <td className="border border-black text-black text-center align-middle">{match.score.homePenalties > 0 || match.score.awayPenalties > 0 ? match.score.awayPenalties : '-'}</td>

            {/* Final Total */}
            <td className="border border-black bg-yellow-300 print:bg-yellow-300 text-sm text-black text-center align-middle">{match.score.home + match.score.homePenalties}</td>
            <td className="border border-black bg-yellow-300 print:bg-yellow-300 text-sm text-black text-center align-middle">{match.score.away + match.score.awayPenalties}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

interface TeamRosterProps {
    team: Team;
    letter: string;
    onSign: (role: 'captain' | 'coach') => void;
    matchEvents: MatchEvent[];
    teamSide: 'home' | 'away';
    onEditReservation: () => void;
}

const TeamRoster = ({ team, letter, onSign, matchEvents, teamSide, onEditReservation }: TeamRosterProps) => {
  const hasSanction = (p: Player, type: SanctionType) => p.sanctions.some(s => s.type === type);

  // FIX: Render fixed number of rows (14) to ensure grid lines appear even for empty slots
  const MIN_ROWS = 14;
  const filledPlayers = [...team.players];
  // Fill with nulls
  while (filledPlayers.length < MIN_ROWS) {
      filledPlayers.push(null as any);
  }

  // Get Timeout Times
  const timeouts = matchEvents
      .filter(e => e.type === 'TIMEOUT' && e.team === teamSide)
      .sort((a, b) => a.timestamp - b.timestamp);

  const getTimeoutTime = (index: number) => {
      if (timeouts[index]) return timeouts[index].timeStr;
      return '';
  };

  const rows = filledPlayers.map((p, i) => {
    return (
      <tr key={i} className="h-10 text-center leading-none text-black hover:bg-gray-50 transition-colors">
        {/* Number - Increased Size */}
        <td className="border-r border-b border-black font-black text-sm w-8 bg-gray-50 print:bg-gray-50 text-black text-center align-middle">
            {p?.number || ''}
        </td>

        {/* LICENCE COLUMN */}
        <td className="border-r border-b border-black w-16 font-mono text-[9px] font-bold text-slate-700 text-center align-middle truncate px-0.5">
            {p?.licence || ''}
        </td>

        {/* NAME CELL WITH ROLES - Increased Size */}
        <td className="border-r border-b border-black px-2 text-right font-bold text-[11px] truncate text-black align-middle" style={{ fontFamily: "'Cairo', sans-serif" }}>
          {p ? (
              <div className="flex items-center justify-between w-full">
                <span>{p.name}</span>
                <div className="flex gap-1">
                    {p.isCaptain && <span className="font-black text-[9px] bg-black text-white px-1 rounded-sm">C</span>}
                    {p.isGoalkeeper && <span className="font-black text-[9px] border border-black px-1 rounded-sm">G</span>}
                </div>
              </div>
          ) : ''}
        </td>

        {/* Goals - FULL BORDER TO FIX PDF GRID ISSUE */}
        <td className="border-l border-r border-b border-black font-black text-xs w-10 bg-gray-50 print:bg-gray-50 text-black text-center align-middle">
            {p && p.goals > 0 ? p.goals : ''}
        </td>

        <td className="border-r border-b border-black w-6 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.YELLOW) ? 'X' : ''}</td>
        <td className="border-r border-b border-black w-10 text-[9px] font-bold text-black text-center align-middle">
           <div className="flex items-center justify-center gap-0.5">
             {p?.sanctions.filter(s => s.type === SanctionType.TWO_MINUTES).map((_, idx) => <span key={idx} className="bg-black text-white px-0.5 rounded-[1px]">2'</span>)}
           </div>
        </td>
        <td className="border-r border-b border-black w-6 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.RED) ? 'X' : ''}</td>
        {/* BLUE CARD COLUMN */}
        <td className="border-b border-black w-6 font-black text-black text-center align-middle">{p && hasSanction(p, SanctionType.BLUE) ? 'X' : ''}</td>
      </tr>
    );
  });

  return (
    <div className="flex-1 flex flex-col h-full">
      {/* Team Header - Background Color applied */}
      <div 
        className="flex items-center justify-between border-2 border-black px-2 h-10 mb-0.5 print:h-10"
        style={{ backgroundColor: team.color }}
      >
        <div className="font-black text-base flex items-center gap-2 flex-1 min-w-0">
            <div className="w-6 h-6 rounded-full bg-white text-black flex items-center justify-center text-xs border-2 border-black shadow-sm flex-shrink-0 font-bold">{letter}</div>
            <span className="truncate max-w-[220px] text-white mix-blend-difference drop-shadow-md" style={{ fontFamily: "'Cairo', sans-serif" }}>{team.name}</span>
        </div>
        {/* Timeouts - Show actual time */}
        <div className="flex border border-black bg-white text-black text-[9px] h-7 shadow-sm items-center flex-shrink-0 rounded-sm overflow-hidden">
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-black text-black h-full">و.م 1</div>
           <div className="w-10 border-r border-black flex items-center justify-center font-bold text-blue-800 h-full text-[10px]">{getTimeoutTime(0)}</div>
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-black text-black h-full">و.م 2</div>
           <div className="w-10 border-r border-black flex items-center justify-center font-bold text-blue-800 h-full text-[10px]">{getTimeoutTime(1)}</div>
           {/* 3RD TIMEOUT */}
           <div className="px-1.5 border-r border-black flex items-center bg-gray-100 font-black text-black h-full">و.م 3</div>
           <div className="w-10 flex items-center justify-center font-bold text-blue-800 h-full text-[10px]">{getTimeoutTime(2)}</div>
        </div>
      </div>

      <div className="flex-1 border-2 border-black bg-white">
        <table className="w-full border-collapse table-fixed h-full" dir="rtl">
            <thead className="bg-gray-100 print:bg-gray-100 text-[9px] uppercase font-black text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>
            <tr className="h-8 border-b-2 border-black">
                <th className="border-l border-black w-8 text-black text-center align-middle">رقم</th>
                <th className="border-l border-black w-16 text-black text-center align-middle">ر. مسار</th>
                <th className="border-l border-black text-black text-center align-middle text-right px-4">الاسم والنسب</th>
                {/* Goals Header - FULL BORDER */}
                <th className="border-l border-r border-black w-10 text-black text-center align-middle">أهداف</th>
                <th className="border-l border-black w-6 bg-yellow-200 print:bg-yellow-200 text-black text-center align-middle">ص</th>
                <th className="border-l border-black w-10 text-black text-center align-middle">2د</th>
                <th className="border-l border-black w-6 bg-red-200 print:bg-red-200 text-black text-center align-middle">ح</th>
                {/* BLUE CARD HEADER */}
                <th className="w-6 bg-blue-200 print:bg-blue-200 text-black text-center align-middle">ز</th>
            </tr>
            </thead>
            <tbody>
            {rows}
            </tbody>
        </table>
      </div>

      {/* TEAM RESERVATIONS BLOCK */}
      <div 
        className="mt-0.5 border-2 border-black bg-white text-black flex items-stretch group cursor-pointer relative" 
        style={{ height: '45px' }} 
        dir="rtl" 
        onClick={onEditReservation}
      >
         <div className="w-20 bg-gray-100 print:bg-gray-100 border-l-2 border-black flex items-center justify-center font-black text-[9px] text-black" style={{ fontFamily: "'Cairo', sans-serif" }}>
             تحفظات
         </div>
         <div className="flex-1 px-2 py-1 font-mono text-[9px] whitespace-pre-wrap leading-tight overflow-hidden">
            {team.reservations || 'لا توجد'}
         </div>
         <div data-html2canvas-ignore="true" className="absolute right-0 top-0 bottom-0 w-8 flex items-center justify-center bg-blue-500/5 hover:bg-blue-500/10 transition-opacity print:hidden">
            <Edit2 size={12} className="text-blue-600 opacity-50 hover:opacity-100" />
         </div>
      </div>

      {/* ISOLATED COACH BOX */}
      <div 
        className="mt-0.5 border-2 border-black bg-white text-black h-10 flex items-center group cursor-pointer" 
        dir="rtl"
        onClick={() => onSign('coach')}
      >
           <div className="w-20 bg-blue-50 print:bg-blue-50 border-l-2 border-black h-full flex items-center justify-center font-black text-[9px] text-blue-900 underline" style={{ fontFamily: "'Cairo', sans-serif" }}>
               المدرب
           </div>
           <div className="flex-1 px-2 font-bold text-[10px] truncate border-l-2 border-black text-center flex items-center justify-center gap-2 relative" style={{ fontFamily: "'Cairo', sans-serif" }}>
               <span>{team.coach.name}</span>
                {/* Signature Overlay if exists */}
               {team.signatures?.coach && (
                   <img src={team.signatures.coach} alt="Coach Sig" className="absolute left-1 top-0 h-full w-auto opacity-80 mix-blend-multiply" />
               )}
               {/* Trigger Icon - Always visible on screen, hidden in print, ignored by html2canvas */}
               <div data-html2canvas-ignore="true" className="absolute inset-0 bg-blue-500/5 hover:bg-blue-500/10 transition-opacity print:hidden flex items-center justify-center">
                    <PenTool size={14} className="text-blue-600 opacity-50 hover:opacity-100" />
               </div>
           </div>
           <div className="w-6 border-l border-black h-full flex items-center justify-center font-black text-xs bg-yellow-100 print:bg-yellow-100">
               {team.coach.sanctions.some(s => s.type === SanctionType.YELLOW) ? 'X' : ''}
           </div>
           <div className="w-10 border-l border-black h-full flex items-center justify-center text-xs font-bold">
               {team.coach.sanctions.some(s => s.type === SanctionType.TWO_MINUTES) ? "2'" : ''}
           </div>
           <div className="w-6 border-l border-black h-full flex items-center justify-center font-black text-xs bg-red-100 print:bg-red-100">
               {team.coach.sanctions.some(s => s.type === SanctionType.RED) ? 'X' : ''}
           </div>
           {/* BLUE CARD COACH */}
           <div className="w-6 h-full flex items-center justify-center font-black text-xs bg-blue-100 print:bg-blue-100">
               {team.coach.sanctions.some(s => s.type === SanctionType.BLUE) ? 'X' : ''}
           </div>
      </div>

      {/* ASSISTANT COACH BOX */}
      <div className="mt-0.5 border-2 border-black bg-white text-black h-8 flex items-center" dir="rtl">
           <div className="w-20 bg-blue-50 print:bg-blue-50 border-l-2 border-black h-full flex items-center justify-center font-black text-[9px] text-slate-800" style={{ fontFamily: "'Cairo', sans-serif" }}>
               م. مدرب
           </div>
