        <button onClick={handlePrint} className="px-6 py-2 bg-black text-white rounded-xl font-bold text-sm flex gap-2 items-center hover:bg-gray-800 shadow-lg transition-colors">
           <Printer size={18}/> Imprimer
        </button>
      </div>

      {/* A4 SHEET CONTAINER - 210mm x 297mm */}
      <div 
        id="match-sheet-content" 
        className="w-[210mm] min-h-[296mm] bg-white p-[5mm] shadow-2xl print:shadow-none print:w-[210mm] print:h-[297mm] box-border flex flex-col relative mx-auto overflow-hidden"
        style={{ fontFamily: "'Inter', sans-serif" }}
      >
        <SheetHeader details={match.details} />
        <MatchInfo details={match.details} />
        <ScoreTable match={match} />

        {/* Rosters A & B */}
