            className={`w-6 h-6 rounded-lg border-2 transition-all ${currentColor === c.hex ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
            style={{ backgroundColor: c.hex }}
            title={c.name}
          />
        ))}
        <div className={`relative w-6 h-6 rounded-lg overflow-hidden border-2 transition-all flex items-center justify-center ${!PRESET_COLORS.some(c => c.hex === currentColor) ? 'border-white scale-110 shadow-lg' : 'border-slate-500/30 opacity-60 hover:opacity-100'}`} style={{ backgroundColor: !PRESET_COLORS.some(c => c.hex === currentColor) ? currentColor : 'transparent' }}>
             {!PRESET_COLORS.some(c => c.hex === currentColor) ? null : <Palette size={14} className={isDarkMode ? "text-white" : "text-black"} />}
             <input
                type="color"
                value={currentColor}
                onChange={(e) => onSelect(e.target.value)}
                className="absolute inset-0 w-[200%] h-[200%] -translate-x-1/4 -translate-y-1/4 opacity-0 cursor-pointer"
                title="لون مخصص"
            />
        </div>
      </div>
    </div>
  );

  const handlePlayerNumberChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].number = val;
    setter(next);
  };

  const handlePlayerLicenceChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].licence = val;
    setter(next);
  };

  const toggleCaptain = (
      idx: number,
      players: PlayerInput[],
      setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
      const next = players.map((p, i) => ({
          ...p,
          isCaptain: i === idx ? !p.isCaptain : false // Ensure only one captain
      }));
      setter(next);
  };

  const renderPlayerInputs = (players: PlayerInput[], setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>) => (
    <div className="space-y-1 overflow-y-auto pr-1 custom-scrollbar flex-1 pb-4">
      {players.map((p, idx) => (
        <div key={idx} className={`flex gap-2 items-center p-1.5 rounded-xl border ${isDarkMode ? 'bg-slate-800/40 border-slate-700/50' : 'bg-slate-800/40 border-slate-700/50'}`}>
          <input 
            type="tel" 
            pattern="[0-9]*"
            placeholder="#"
            className={`w-10 p-1.5 border rounded-lg text-center text-xs font-black outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-blue-400' : 'bg-slate-900 border-slate-700 text-blue-400'}`} 
            value={p.number} 
            onChange={e => handlePlayerNumberChange(idx, e.target.value, players, setter)} 
          />
          <input 
            type="text" 
            placeholder="رقم مسار / Licence"
            className={`w-24 p-1.5 border rounded-lg text-center text-[10px] font-bold outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-amber-400' : 'bg-slate-900 border-slate-700 text-amber-400'}`} 
            value={p.licence} 
            onChange={e => handlePlayerLicenceChange(idx, e.target.value, players, setter)} 
          />
          <input 
            type="text" 
            placeholder="اسم اللاعب"
            className={`flex-1 p-1.5 border rounded-lg text-right text-xs font-bold outline-none ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white' : 'bg-slate-900 border-slate-700 text-white'}`} 
            value={p.name} 
            onChange={e => {
              const next = [...players];
              next[idx].name = e.target.value;
              setter(next);
            }} 
          />
          {/* Roles Toggles - ONLY CAPTAIN */}
          <button 
             onClick={() => toggleCaptain(idx, players, setter)}
             className={`p-1.5 rounded-lg transition-colors border ${p.isCaptain ? 'bg-yellow-500 text-white border-yellow-600' : (isDarkMode ? 'bg-slate-800 text-slate-600 border-slate-700 hover:text-yellow-500' : 'bg-slate-100 text-slate-400 border-slate-200 hover:text-yellow-500')}`}
             title="عميد الفريق"
          >
             <Crown size={14} fill={p.isCaptain ? "currentColor" : "none"} />
          </button>
        </div>
      ))}
    </div>
  );

  return (
    <div className={`rounded-3xl shadow-xl border flex flex-col h-full overflow-hidden ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-900 border-slate-800'}`}>
      {/* Pinned Header */}
      <div className="p-4 text-center flex-shrink-0 border-b border-slate-700/50">
        <h2 className="text-xl font-black text-white">إعداد المباراة</h2>
        <div className={`flex p-1 rounded-xl mt-3 ${isDarkMode ? 'bg-slate-900/50' : 'bg-slate-950/50'}`}>
          {(['details', 'teamA', 'teamB', 'officials'] as const).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg transition-all ${activeTab === tab ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>
              {tab === 'details' ? 'عام' : tab === 'teamA' ? 'A' : tab === 'teamB' ? 'B' : 'الحكام'}
            </button>
          ))}
        </div>
      </div>

      {/* Scrollable Content Area */}
      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar flex flex-col">
        {activeTab === 'details' && (
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <label className={labelStyle}>الأكاديمية الجهوية (AREF)</label>
              <input className={inputStyle} value={details.aref} onChange={e => setDetails({...details, aref: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className={labelStyle}>المديرية الإقليمية</label>
              <input className={inputStyle} value={details.direction} onChange={e => setDetails({...details, direction: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>رقم اللقاء</label>
              <input type="tel" className={inputStyle} value={details.numRencontre} onChange={e => setDetails({...details, numRencontre: e.target.value})} />
            </div>
             <div>
              <label className={labelStyle}>المرحلة (Etape)</label>
              <input className={inputStyle} value={details.etape} onChange={e => setDetails({...details, etape: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className={labelStyle}>الفئة</label>
              <input className={inputStyle} value={details.categorie} onChange={e => setDetails({...details, categorie: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>مدة الشوط (د)</label>
              <input type="tel" pattern="[0-9]*" className={inputStyle} value={halfDur} onChange={e => setHalfDur(parseInt(e.target.value) || 0)} />
            </div>
            <div>
              <label className={labelStyle}>الشوط الإضافي (د)</label>
              <input type="tel" pattern="[0-9]*" className={inputStyle} value={otDur} onChange={e => setOtDur(parseInt(e.target.value) || 0)} />
            </div>

            {/* CONFIGURATION DUREE EXCLUSION */}
            <div className="col-span-2">
               <label className={labelStyle}>زمن المخالفة (الإقصاء المؤقت)</label>
               <div className="flex bg-slate-100 dark:bg-slate-900 rounded-xl p-1">
                  <button 
                    onClick={() => setSuspensionDur(1)}
                    className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${suspensionDur === 1 ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500'}`}
                  >
                    1 دقيقة
                  </button>
                  <button 
                    onClick={() => setSuspensionDur(2)}
                    className={`flex-1 py-2 text-xs font-black rounded-lg transition-all ${suspensionDur === 2 ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500'}`}
                  >
                    2 دقائق (Standard)
                  </button>
               </div>
            </div>

            <div className="col-span-2">
              <label className={labelStyle}>مركز التباري</label>
              <input className={inputStyle} value={details.lieu} onChange={e => setDetails({...details, lieu: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>التاريخ</label>
              <input type="date" className={inputStyle} value={details.date} onChange={e => setDetails({...details, date: e.target.value})} />
            </div>
            <div>
              <label className={labelStyle}>التوقيت</label>
              <input type="time" className={inputStyle} value={details.time} onChange={e => setDetails({...details, time: e.target.value})} />
            </div>
            <div className="col-span-2 mt-2">
              <label className={labelStyle}>رابط المقابلة (Live Stream/Video)</label>
              <div className="relative">
                <Link size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500" />
                <input className={`${inputStyle} pr-8`} value={details.matchLink || ''} onChange={e => setDetails({...details, matchLink: e.target.value})} placeholder="https://..." dir="ltr" />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'teamA' && (
          <div className="flex flex-col h-full gap-3">
            <div className={`p-3 rounded-2xl border flex-shrink-0 ${isDarkMode ? 'bg-blue-900/10 border-blue-900/40' : 'bg-blue-900/10 border-blue-500/20'}`}>
              <div className="grid grid-cols-2 gap-2 mb-2">
                 <div className="col-span-2"><input className={inputStyle} value={home} onChange={e => setHome(e.target.value)} placeholder="اسم الفريق" /></div>
                 <input className={inputStyle} value={homeCoach} onChange={e => setHomeCoach(e.target.value)} placeholder="المدرب الرئيسي" />
                 <input className={inputStyle} value={homeAst} onChange={e => setHomeAst(e.target.value)} placeholder="مساعد المدرب" />
              </div>
              <div className="flex items-center justify-between">
                <span className={labelStyle}>العدد: {homeCount}</span>
                <div className="flex items-center gap-2">
                  <button onClick={() => setHomeCount(Math.max(1, homeCount - 1))} className={`w-6 h-6 rounded flex items-center justify-center text-white text-xs ${isDarkMode ? 'bg-slate-700' : 'bg-slate-800'}`}>-</button>
                  <button onClick={() => setHomeCount(Math.min(20, homeCount + 1))} className={`w-6 h-6 rounded flex items-center justify-center text-white text-xs ${isDarkMode ? 'bg-slate-700' : 'bg-slate-800'}`}>+</button>
                </div>
              </div>
              {renderColorPicker(homeColor, setHomeColor)}
            </div>
            {renderPlayerInputs(homePlayers, setHomePlayers)}
          </div>
        )}

        {activeTab === 'teamB' && (
          <div className="flex flex-col h-full gap-3">
             <div className={`p-3 rounded-2xl border flex-shrink-0 ${isDarkMode ? 'bg-red-900/10 border-red-900/40' : 'bg-red-900/10 border-red-500/20'}`}>
              <div className="grid grid-cols-2 gap-2 mb-2">
                 <div className="col-span-2"><input className={inputStyle} value={away} onChange={e => setAway(e.target.value)} placeholder="اسم الفريق" /></div>
                 <input className={inputStyle} value={awayCoach} onChange={e => setAwayCoach(e.target.value)} placeholder="المدرب الرئيسي" />
                 <input className={inputStyle} value={awayAst} onChange={e => setAwayAst(e.target.value)} placeholder="مساعد المدرب" />
              </div>
              <div className="flex items-center justify-between">
                <span className={labelStyle}>العدد: {awayCount}</span>
                <div className="flex items-center gap-2">
                  <button onClick={() => setAwayCount(Math.max(1, awayCount - 1))} className={`w-6 h-6 rounded flex items-center justify-center text-white text-xs ${isDarkMode ? 'bg-slate-700' : 'bg-slate-800'}`}>-</button>
                  <button onClick={() => setAwayCount(Math.min(20, awayCount + 1))} className={`w-6 h-6 rounded flex items-center justify-center text-white text-xs ${isDarkMode ? 'bg-slate-700' : 'bg-slate-800'}`}>+</button>
                </div>
              </div>
              {renderColorPicker(awayColor, setAwayColor)}
            </div>
            {renderPlayerInputs(awayPlayers, setAwayPlayers)}
          </div>
        )}

        {activeTab === 'officials' && (
          <div className="space-y-3 pt-2">
            <input className={inputStyle} value={officials.referee1} onChange={e => setOfficials({...officials, referee1: e.target.value})} placeholder="الحكم 1" />
            <input className={inputStyle} value={officials.referee2} onChange={e => setOfficials({...officials, referee2: e.target.value})} placeholder="الحكم 2" />
            <input className={inputStyle} value={officials.timer} onChange={e => setOfficials({...officials, timer: e.target.value})} placeholder="الميقاتي" />
            <input className={inputStyle} value={officials.secretary} onChange={e => setOfficials({...officials, secretary: e.target.value})} placeholder="المسجل" />
          </div>
        )}
      </div>

      {/* Pinned Footer */}
      <div className={`p-4 flex-shrink-0 border-t border-slate-700/50 ${isDarkMode ? 'bg-slate-900/80' : 'bg-slate-950/80'}`}>
        <button 
          onClick={handleStart}
          className="w-full py-3 bg-blue-600 text-white font-black rounded-xl shadow-xl shadow-blue-900/40 text-sm hover:bg-blue-500 transition-colors"
        >
          حفظ وتوجه للملعب
        </button>
      </div>
      <style>{`.custom-scrollbar::-webkit-scrollbar { width: 4px; } .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; border-radius: 10px; }`}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { Team, SanctionType, Player } from '../types.ts';
import { Trash2, X, Save, AlertCircle, UserPlus, Shield, Crown, Edit2 } from 'lucide-react';

interface TeamControlProps {
  team: Team;
  side: 'home' | 'away';
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onSelect: (target: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string }) => void;
  isDarkMode: boolean;
  onUpdatePlayer: (side: 'home' | 'away', id: string, data: Partial<Player>) => void;
  onDeletePlayer: (side: 'home' | 'away', id: string) => void;
  onAddPlayer: (side: 'home' | 'away', number: string, name: string) => void;
  onUpdateStaff?: (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => void;
}

export const TeamControl: React.FC<TeamControlProps> = ({ team, side, selectedTarget, onSelect, isDarkMode, onUpdatePlayer, onDeletePlayer, onAddPlayer, onUpdateStaff }) => {
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editName, setEditName] = useState('');
  const [editNumber, setEditNumber] = useState('');
  const [editLicence, setEditLicence] = useState('');
  const [editIsCaptain, setEditIsCaptain] = useState(false);
  const [editIsGoalkeeper, setEditIsGoalkeeper] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Staff Editing
  const [editingStaff, setEditingStaff] = useState<'coach' | 'assistant-coach' | null>(null);

  // New Player State
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newNumber, setNewNumber] = useState('');

  const isCoachSelected = selectedTarget?.type === 'coach' && selectedTarget.team === side;
  const isAssistantSelected = selectedTarget?.type === 'assistant-coach' && selectedTarget.team === side;

  if (!team) return null;

  const handleDoubleClickPlayer = (p: Player) => {
    setEditingPlayer(p);
    setEditName(p.name);
    setEditNumber(p.number);
    setEditLicence(p.licence || '');
    setEditIsCaptain(p.isCaptain || false);
    setEditIsGoalkeeper(p.isGoalkeeper || false);
    setShowDeleteConfirm(false);
  };

  const handleDoubleClickStaff = (type: 'coach' | 'assistant-coach') => {
      setEditingStaff(type);
      setEditName(type === 'coach' ? team.coach.name : (team.assistantCoach?.name || ''));
  };

  const saveEdit = () => {
    if (editingPlayer) {
      // Check for duplicate number (excluding current player)
      const duplicate = team.players.some(p => p.number === editNumber && p.id !== editingPlayer.id);
      if (duplicate) {
          alert(`الرقم ${editNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onUpdatePlayer(side, editingPlayer.id, { 
          name: editName, 
          number: editNumber,
          licence: editLicence,
          isCaptain: editIsCaptain,
          isGoalkeeper: editIsGoalkeeper
      });
      setEditingPlayer(null);
    } else if (editingStaff && onUpdateStaff) {
        onUpdateStaff(side, editingStaff, editName);
        setEditingStaff(null);
    }
  };

  const handleAddSubmit = () => {
    if (newNumber.trim() && newName.trim()) {
      // Check for duplicate number
      const duplicate = team.players.some(p => p.number === newNumber);
      if (duplicate) {
          alert(`الرقم ${newNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onAddPlayer(side, newNumber, newName);
      setNewName('');
      setNewNumber('');
      setShowAddModal(false);
    }
  };

  const closeEdit = () => {
    setEditingPlayer(null);
    setEditingStaff(null);
    setShowDeleteConfirm(false);
  };

  return (
    <div className={`flex flex-col h-full max-h-[85vh] gap-2 p-2 sm:p-3 rounded-3xl border-2 transition-all ${selectedTarget?.team === side ? 'border-blue-500 shadow-xl' : isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="flex items-center justify-between mb-1 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-3 h-6 rounded-full shadow-inner" style={{ backgroundColor: team.color || '#ccc' }}></div>
          <h3 className="font-black text-sm sm:text-base uppercase tracking-tight truncate max-w-[100px] sm:max-w-none">{team.name || 'فريق'}</h3>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
          className={`p-1.5 rounded-lg transition-all hover:scale-110 active:scale-95 ${isDarkMode ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-600/30' : 'bg-blue-100 text-blue-600 hover:bg-blue-200'}`}
          title="إضافة لاعب جديد"
        >
          <UserPlus size={16} strokeWidth={3} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-player-scrollbar">
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 pb-2">
          {team.players?.map((p) => {
            const isSelected = selectedTarget?.type === 'player' && selectedTarget.id === p.id;
            const isRed = p.sanctions?.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
            const yellowSanc = p.sanctions?.filter(s => s.type === SanctionType.YELLOW) || [];
            const twoMinSancs = p.sanctions?.filter(s => s.type === SanctionType.TWO_MINUTES) || [];
            const active2Min = twoMinSancs.find(s => s.remainingTime && s.remainingTime > 0);

            return (
              <button
                key={p.id}
                onClick={() => onSelect({ type: 'player', team: side, id: p.id })}
                onDoubleClick={() => handleDoubleClickPlayer(p)}
                className={`
                  relative h-16 sm:h-20 rounded-2xl flex flex-col items-center justify-center transition-all duration-200 border-2 flex-shrink-0 select-none
                  ${isRed ? 'bg-red-950/20 border-red-900/50 grayscale opacity-70' : 
                    isSelected ? 'bg-blue-600 border-blue-400 scale-[1.02] shadow-xl text-white' : 
                    isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500 text-slate-100' : 'bg-slate-50 border-slate-200 hover:border-blue-300 text-slate-800'}
                `}
              >
                <span className="text-xl sm:text-2xl font-black leading-none">{p.number}</span>
                <span className={`text-[8px] sm:text-[9px] font-bold truncate w-full px-1 text-center mt-0.5 ${isSelected ? 'text-blue-100' : 'text-slate-500'}`}>{p.name}</span>

                {/* Role Indicators */}
                <div className="absolute top-1 right-1 flex flex-col gap-0.5">
                   {p.isCaptain && <Crown size={10} className="text-yellow-500 fill-yellow-500" />}
                   {p.isGoalkeeper && <Shield size={10} className="text-gray-400 fill-gray-400" />}
                </div>

                <div className="absolute top-1 left-1 flex flex-col gap-0.5">
                  {yellowSanc.map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm"></div>
                  ))}
                  {twoMinSancs.slice(0, 2).map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-slate-950 rounded-sm border border-slate-700 flex items-center justify-center text-[6px] sm:text-[7px] text-white font-black">
                        {/* Display duration or count */}
                        {active2Min && active2Min === twoMinSancs[i] ? '1' : ''}
                    </div>
                  ))}
                  {isRed && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-red-600 rounded-sm border border-red-800 shadow-sm"></div>
                  )}
                </div>

                {active2Min && (
                  <div className="absolute -top-2 -right-1 bg-black text-white text-[8px] px-1 py-0.5 rounded-full font-mono font-bold border border-slate-700 animate-pulse z-10">
                    {Math.floor(active2Min.remainingTime! / 60)}:{(active2Min.remainingTime! % 60).toString().padStart(2, '0')}
                  </div>
                )}

                {p.goals > 0 && (
                  <div className={`absolute -bottom-1 -left-1 w-5 h-5 sm:w-6 sm:h-6 rounded-full flex items-center justify-center text-[9px] sm:text-[11px] font-black shadow-lg border-2 ${isSelected ? 'bg-white text-blue-600 border-blue-100' : 'bg-green-600 text-white border-green-700'}`}>
                    {p.goals}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-1 pt-2 border-t space-y-2 flex-shrink-0">
          <button 
            onClick={() => onSelect({ type: 'coach', team: side })}
            onDoubleClick={() => handleDoubleClickStaff('coach')}
            className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isCoachSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
          >
            <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isCoachSelected ? 'text-blue-500' : 'text-slate-500'}`}>المؤطر: {team.coach?.name || '---'}</div>
            <div className="flex gap-1">
              {team.coach?.sanctions?.map((s, i) => (
                <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                    {/* Placeholder */}
                </div>
              ))}
            </div>
          </button>

          {team.assistantCoach && (
            <button 
                onClick={() => onSelect({ type: 'assistant-coach', team: side })}
                onDoubleClick={() => handleDoubleClickStaff('assistant-coach')}
