const generateId = () => Math.random().toString(36).substring(2, 15) + Date.now().toString(36);

const sortPlayersByNumber = (players: Player[]): Player[] => {
  return [...players].sort((a, b) => {
    const numA = parseInt(a.number, 10) || 0;
    const numB = parseInt(b.number, 10) || 0;
    return numA - numB;
  });
};

const formatMMSS = (seconds: number) => {
  if (typeof seconds !== 'number' || isNaN(seconds)) return "00:00";
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

const PERIOD_ORDER = [
  MatchPeriod.FIRST_HALF,
  MatchPeriod.SECOND_HALF,
  MatchPeriod.OT1_H1,
  MatchPeriod.OT1_H2,
  MatchPeriod.OT2_H1,
  MatchPeriod.OT2_H2,
  MatchPeriod.PENALTIES
];

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'setup_choice' | 'match' | 'sheet' | 'archive' | 'admin_schedule'>('setup_choice');
  const [match, setMatch] = useState<MatchState | null>(null);
  const [history, setHistory] = useState<MatchState[]>([]); // Historique local de la session (undo/redo)

  // Archive State (Persistent LocalStorage)
  const [archive, setArchive] = useState<MatchState[]>(() => {
    try {
      const stored = localStorage.getItem('handball_archive');
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      console.error("Failed to load archive", e);
      return [];
    }
  });

  const [selectedTarget, setSelectedTarget] = useState<{ type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => window.matchMedia('(prefers-color-scheme: dark)').matches);
  const [timeoutTimer, setTimeoutTimer] = useState<number | null>(null);
  const [timerSpeed, setTimerSpeed] = useState(1);

  // New State for Schedule (Local Only)
  const [schedule, setSchedule] = useState<ScheduledMatch[]>([]);
  const [preSelectedScheduledMatch, setPreSelectedScheduledMatch] = useState<ScheduledMatch | null>(null);

  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginPass, setLoginPass] = useState('');

  // Center Password Verification
  const [showCenterPasswordModal, setShowCenterPasswordModal] = useState(false);
  const [centerLoginPass, setCenterLoginPass] = useState('');
  const [pendingScheduledMatch, setPendingScheduledMatch] = useState<ScheduledMatch | null>(null);

  // Penalty Setup Modal
  const [showPenaltySetup, setShowPenaltySetup] = useState(false);
  const [penaltyConfig, setPenaltyConfig] = useState<{ shots: number, starter: 'home' | 'away' | null }>({ shots: 5, starter: null });

  const matchRef = useRef<MatchState | null>(null);
  useEffect(() => { matchRef.current = match; }, [match]);

  // Persist Archive when it changes
  useEffect(() => {
    try {
      localStorage.setItem('handball_archive', JSON.stringify(archive));
    } catch (e) {
      console.error("Failed to save archive", e);
    }
  }, [archive]);

  const saveScheduleToLocal = (newSchedule: ScheduledMatch[]) => {
      setSchedule(newSchedule);
      // Optionnel : Sauvegarder dans localStorage si besoin
  };

  const deleteFromArchive = (id: string) => {
      setArchive(prev => prev.filter(m => m.id !== id));
      if (match?.id === id) {
          setMatch(null);
          setView('setup_choice');
      }
  };

  const handleFinishMatch = () => {
    if (!match) return;
    const finishedMatch = { ...match, isFinished: true, isActive: false };
    setMatch(finishedMatch);

    // Save to archive (update if exists, add if new)
    setArchive(prev => {
        const exists = prev.some(m => m.id === finishedMatch.id);
        if (exists) {
            return prev.map(m => m.id === finishedMatch.id ? finishedMatch : m);
        }
        return [finishedMatch, ...prev];
    });
  };

  const startMatch = (
    h: string, hc: string, hast: string, hplayers: any[], hcol: string,
    a: string, ac: string, aast: string, aplayers: any[], acol: string, 
    hd: number, od: number, suspensionDur: number, off: any, det: any
  ) => {
    const mapPlayers = (players: any[], prefix: string): Player[] => {
      const mapped = players.map((p, i) => ({ 
        id: `${prefix}-${generateId()}-${i}`, 
        number: p.number, 
        licence: p.licence || '',
        name: p.name, 
        goals: 0, 
        sanctions: [], 
        isCaptain: p.isCaptain || false, 
        isGoalkeeper: p.isGoalkeeper || false
      }));
      return sortPlayersByNumber(mapped);
    };

    // Initialize Assistant Coach as a Staff object
    const homeAssistant: Staff = { name: hast, sanctions: [] };
    const awayAssistant: Staff = { name: aast, sanctions: [] };

    const newMatch: MatchState = {
      id: generateId(), details: det,
      homeTeam: { 
        name: h, color: hcol, coach: { name: hc, sanctions: [] }, assistantCoach: homeAssistant,
        players: mapPlayers(hplayers, 'home'), timeoutsUsed: 0, timeoutsThisHalf: 0, reservations: ''
      },
      awayTeam: { 
        name: a, color: acol, coach: { name: ac, sanctions: [] }, assistantCoach: awayAssistant,
        players: mapPlayers(aplayers, 'away'), timeoutsUsed: 0, timeoutsThisHalf: 0, reservations: ''
      },
      officials: off, timer: 0, isActive: false, isFinished: false, period: MatchPeriod.FIRST_HALF, report: '',
      score: { 
        home: 0, away: 0, 
        homeP1: 0, awayP1: 0, 
        homeFullTime: undefined, awayFullTime: undefined,
        homeOT: undefined, awayOT: undefined,
        homeOT2: undefined, awayOT2: undefined,
        homePenalties: 0, awayPenalties: 0 
      },
      penaltySequence: { home: [], away: [], currentTurn: 'home' },
      config: { halfDuration: hd * 60, otDuration: od * 60, penaltyShots: 5, suspensionDuration: suspensionDur * 60 },
      events: [] 
    };
    setMatch(newMatch);
    setHistory([]);
    setView('match');
  };

  const handleNewMatchChoice = (matchChoice?: ScheduledMatch) => {
    if (matchChoice) {
      if (matchChoice.centerPassword) {
        setPendingScheduledMatch(matchChoice);
        setCenterLoginPass('');
        setShowCenterPasswordModal(true);
      } else {
        setPreSelectedScheduledMatch(matchChoice);
        setView('setup');
      }
    } else {
      setPreSelectedScheduledMatch(null);
      setView('setup');
    }
  };

  const handleCenterLogin = () => {
    if (pendingScheduledMatch && centerLoginPass === pendingScheduledMatch.centerPassword) {
      setPreSelectedScheduledMatch(pendingScheduledMatch);
      setShowCenterPasswordModal(false);
      setPendingScheduledMatch(null);
      setView('setup');
    } else {
      alert("القن السري للمركز غير صحيح");
    }
  };

  const handleLogin = () => {
    if (loginPass === '3lachbghitih@') {
      localStorage.setItem('admin_authenticated', 'true');
      setView('admin_schedule');
      setShowLoginModal(false);
      setLoginPass('');
    } else {
      alert("بيانات الدخول غير صحيحة");
    }
  };

  const handleSettingsClick = () => {
    if (localStorage.getItem('admin_authenticated') === 'true') {
      setView('admin_schedule');
    } else {
      setShowLoginModal(true);
    }
  };

  const handleAddPlayer = (side: 'home' | 'away', number: string, name: string) => {
    setMatch(prev => {
      if (!prev) return null;
      const newPlayer: Player = {
        id: `${side}-${generateId()}`,
        number,
        licence: '', // Default empty license for quick added players
        name,
        goals: 0,
        sanctions: [],
        isCaptain: false,
        isGoalkeeper: false
      };
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: sortPlayersByNumber([...prev[teamKey].players, newPlayer])
        }
      };
    });
  };

  const handleUpdatePlayer = (side: 'home' | 'away', id: string, data: Partial<Player>) => {
    setMatch(prev => {
      if (!prev) return null;
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      const updatedPlayers = prev[teamKey].players.map(p => 
        p.id === id ? { ...p, ...data } : p
      );
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: sortPlayersByNumber(updatedPlayers)
        }
      };
    });
  };

  // Function to update coach or assistant details directly from TeamControl
  const handleUpdateStaff = (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => {
    setMatch(prev => {
        if (!prev) return null;
        const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
        const team = { ...prev[teamKey] };
        if (type === 'coach') {
            team.coach = { ...team.coach, name: name };
        } else if (type === 'assistant-coach' && team.assistantCoach) {
            team.assistantCoach = { ...team.assistantCoach, name: name };
        }
        return { ...prev, [teamKey]: team };
    });
  };

  const handleDeletePlayer = (side: 'home' | 'away', id: string) => {
    setMatch(prev => {
      if (!prev) return null;
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      const updatedPlayers = prev[teamKey].players.filter(p => p.id !== id);
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: updatedPlayers
        }
      };
    });
  };

  const handleTimeout = (team: 'home' | 'away') => {
    if (!match) return;
    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev, isActive: false };
      const teamKey = team === 'home' ? 'homeTeam' : 'awayTeam';

      newMatch[teamKey] = {
        ...newMatch[teamKey],
        timeoutsUsed: newMatch[teamKey].timeoutsUsed + 1,
        timeoutsThisHalf: newMatch[teamKey].timeoutsThisHalf + 1
      };

      newMatch.events.unshift({
          id: generateId(),
          type: 'TIMEOUT',
          timestamp: prev.timer,
          timeStr: formatMMSS(prev.timer),
          team: team
      });

      return newMatch;
    });
    setTimeoutTimer(60);
  };

  const handleCancelTimeout = (team: 'home' | 'away') => {
    if (!match) return;
    setMatch(prev => {
        if (!prev) return null;
        const teamKey = team === 'home' ? 'homeTeam' : 'awayTeam';
        if (prev[teamKey].timeoutsUsed === 0) return prev;

        // Decrement counts
        const newTeam = { ...prev[teamKey] };
        newTeam.timeoutsUsed = Math.max(0, newTeam.timeoutsUsed - 1);
        if (newTeam.timeoutsThisHalf > 0) newTeam.timeoutsThisHalf -= 1;

        // Remove last timeout event for this team
        const newEvents = [...prev.events];
        const evtIdx = newEvents.findIndex(e => e.type === 'TIMEOUT' && e.team === team);
        if (evtIdx > -1) newEvents.splice(evtIdx, 1);

        return { ...prev, [teamKey]: newTeam, events: newEvents };
    });
    setTimeoutTimer(null); // Also cancel timer
  };

  const handlePeriodChange = (direction: 'next' | 'prev') => {
    setMatch(prev => {
      if (!prev) return null;
      const currentIndex = PERIOD_ORDER.indexOf(prev.period);
      let newIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;

      // Bounds check
      if (newIndex < 0) newIndex = 0;
      if (newIndex >= PERIOD_ORDER.length) newIndex = PERIOD_ORDER.length - 1;

      if (newIndex === currentIndex) return prev;

      const newPeriod = PERIOD_ORDER[newIndex];

      // RESET TIMEOUTS FOR THE NEW PERIOD if we are moving to a new half or OT
      let updateHome = { ...prev.homeTeam };
      let updateAway = { ...prev.awayTeam };
      let updatedScore = { ...prev.score };

      // SNAPSHOT HALFTIME SCORE
      if (prev.period === MatchPeriod.FIRST_HALF && newPeriod !== MatchPeriod.FIRST_HALF) {
          updatedScore.homeP1 = prev.score.home;
          updatedScore.awayP1 = prev.score.away;
      }

      // SNAPSHOT FULL TIME (60min) SCORE
      if (prev.period === MatchPeriod.SECOND_HALF && newPeriod !== MatchPeriod.SECOND_HALF && newPeriod !== MatchPeriod.FIRST_HALF) {
          updatedScore.homeFullTime = prev.score.home;
          updatedScore.awayFullTime = prev.score.away;
      }

      // SNAPSHOT OT SCORE (End of OT1 or OT2)
      if (prev.period === MatchPeriod.OT1_H2 && newPeriod !== MatchPeriod.OT1_H2 && newPeriod !== MatchPeriod.OT1_H1) {
           // Can snapshot here if needed
      }

      // SNAPSHOT OT2 SCORE (End of OT2)
      if (prev.period === MatchPeriod.OT2_H2 && newPeriod === MatchPeriod.PENALTIES) {
          updatedScore.homeOT = prev.score.home; // OT Score usually includes OT1 + OT2 total
          updatedScore.awayOT = prev.score.away;
          updatedScore.homeOT2 = prev.score.home; // Store specific end of OT2 score if distinct tracking needed
          updatedScore.awayOT2 = prev.score.away;
      }

      // Reset timeouts for new periods except between OT halves
      if (
          (prev.period === MatchPeriod.FIRST_HALF && newPeriod === MatchPeriod.SECOND_HALF) ||
          (prev.period === MatchPeriod.SECOND_HALF && newPeriod === MatchPeriod.OT1_H1) ||
          (prev.period === MatchPeriod.OT1_H2 && newPeriod === MatchPeriod.OT2_H1)
      ) {
          updateHome.timeoutsThisHalf = 0;
          updateAway.timeoutsThisHalf = 0;
      }

      return {
          ...prev,
          period: newPeriod,
          isActive: false, 
          homeTeam: updateHome,
          awayTeam: updateAway,
          score: updatedScore
      };
    });
  };

  // Wrapper for period change to intercept Penalties
  const onPeriodChangeRequest = (direction: 'next' | 'prev') => {
      if (!match) return;

      const currentIndex = PERIOD_ORDER.indexOf(match.period);
      let newIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;
      if (newIndex >= 0 && newIndex < PERIOD_ORDER.length) {
          const newPeriod = PERIOD_ORDER[newIndex];
          if (newPeriod === MatchPeriod.PENALTIES) {
              setPenaltyConfig({ shots: 5, starter: null });
              setShowPenaltySetup(true);
              return; // Stop here, modal will handle the rest
          }
      }
      handlePeriodChange(direction);
  };

  const confirmPenaltySetup = () => {
      if (!match || !penaltyConfig.starter) return;

      setMatch(prev => {
          if (!prev) return null;
          // Apply standard period change logic + penalty config
          let updatedScore = { ...prev.score };

          // Assuming we came from OT2 or 2nd Half or OT1
          if (prev.period !== MatchPeriod.FIRST_HALF && prev.period !== MatchPeriod.PENALTIES) {
             // If we are coming from overtime, snapshot that
             if (prev.period === MatchPeriod.OT1_H2 || prev.period === MatchPeriod.OT2_H2) {
                 updatedScore.homeOT = prev.score.home;
                 updatedScore.awayOT = prev.score.away;
                 if (prev.period === MatchPeriod.OT2_H2) {
                      updatedScore.homeOT2 = prev.score.home;
                      updatedScore.awayOT2 = prev.score.away;
                 }
             } else if (prev.period === MatchPeriod.SECOND_HALF) {
                 updatedScore.homeFullTime = prev.score.home;
                 updatedScore.awayFullTime = prev.score.away;
             }
          }

          return {
              ...prev,
              period: MatchPeriod.PENALTIES,
              isActive: false,
              score: updatedScore,
              penaltySequence: {
                  ...prev.penaltySequence,
                  currentTurn: penaltyConfig.starter!
              },
              config: {
                  ...prev.config,
                  penaltyShots: penaltyConfig.shots
              }
          };
      });
      setShowPenaltySetup(false);
  };

  const handlePenaltyShot = (team: 'home' | 'away', playerId: string, isGoal: boolean) => {
    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev };

      // Update Penalty Sequence
      const shot = {
        playerId,
        playerName: newMatch[team === 'home' ? 'homeTeam' : 'awayTeam'].players.find(p => p.id === playerId)?.name || '',
        playerNumber: newMatch[team === 'home' ? 'homeTeam' : 'awayTeam'].players.find(p => p.id === playerId)?.number || '',
        goal: isGoal
      };

      newMatch.penaltySequence = {
        ...newMatch.penaltySequence,
        [team]: [...newMatch.penaltySequence[team], shot],
        currentTurn: team === 'home' ? 'away' : 'home' // Toggle Turn
      };

      // Update Score if Goal
      if (isGoal) {
        if (team === 'home') newMatch.score.homePenalties += 1;
        else newMatch.score.awayPenalties += 1;
      }

      return newMatch;
    });
  };

  const handleAction = useCallback((type: 'goal' | '7m' | SanctionType, inc: boolean = true) => {
    if (!match || !selectedTarget) return;

    // Direct Blue Card Application (No modal here anymore, handled in sheet)
    // Blue card handling logic remains the same inside setMatch

    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev };
      const teamSide = selectedTarget.team;
      const teamKey = teamSide === 'home' ? 'homeTeam' : 'awayTeam';
      const team = { ...newMatch[teamKey] };
      const eventTime = newMatch.timer;

      // Prevent adding goal if match is not active (Timer stopped)
      // Allow 'inc = false' to enable undo/correction even if timer is stopped
      if ((type === 'goal' || type === '7m') && inc && !newMatch.isActive) {
          return prev;
      }

      if (selectedTarget.type === 'player' && selectedTarget.id) {
         const pIdx = team.players.findIndex(p => p.id === selectedTarget.id);
         if (pIdx === -1) return prev;

         const player = { ...team.players[pIdx] };

         // Check if player is disqualified (Red or Blue)
         // Only allow interaction if we are "undoing" (inc === false) the specific sanction they have.
         const isDisqualified = player.sanctions.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
         if (inc && isDisqualified) {
           return prev;
         }

         if (type === 'goal' || type === '7m') {
             if (inc) {
                 player.goals += 1;
                 newMatch.score[teamSide === 'home' ? 'home' : 'away'] += 1;

                 newMatch.events.unshift({
                    id: generateId(),
                    type: 'GOAL',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: player.id,
                    playerName: player.name,
                    goalType: type === '7m' ? '7M' : 'NORMAL'
                 });
             } else {
                 if (player.goals > 0) {
                     player.goals -= 1;
                     newMatch.score[teamSide === 'home' ? 'home' : 'away'] -= 1;
                     const evtIdx = newMatch.events.findIndex(e => e.type === 'GOAL' && e.playerId === player.id);
                     if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                 }
             }
         } else {
             if (inc) {
                 if (type === SanctionType.YELLOW) {
                     if (player.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                     const teamYellowCount = team.players.reduce((acc, p) => acc + p.sanctions.filter(s => s.type === SanctionType.YELLOW).length, 0);
                     if (teamYellowCount >= 3) return prev;
                 }
                 const s: any = { type, timestamp: eventTime };
                 // USE CONFIGURABLE SUSPENSION DURATION
                 if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                 player.sanctions = [...player.sanctions, s];

                 newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: player.id,
                    playerName: player.name,
                    sanctionType: type as SanctionType // Store exact enum value
                 });
             } else {
                 const sIdx = player.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                 if (sIdx > -1) {
                     const newSanctions = [...player.sanctions];
                     newSanctions.splice(sIdx, 1);
                     player.sanctions = newSanctions;
                     const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === player.id && e.sanctionType === type);
                     if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                 }
             }
         }
         team.players = [...team.players];
         team.players[pIdx] = player;
      } 
      else if (selectedTarget.type === 'coach') {
          if (type !== 'goal' && type !== '7m') {
              if (inc) {
                  if (type === SanctionType.YELLOW) {
                      if (team.coach.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                  }
                  const s: any = { type: type as SanctionType, timestamp: eventTime };
                  // USE CONFIGURABLE SUSPENSION DURATION
                  if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                  team.coach = { ...team.coach, sanctions: [...team.coach.sanctions, s] };
                  newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: 'COACH',
                    playerName: team.coach.name,
                    sanctionType: type as SanctionType
                 });
              } else {
                  const sIdx = team.coach.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                  if (sIdx > -1) {
                      const newSanctions = [...team.coach.sanctions];
                      newSanctions.splice(sIdx, 1);
                      team.coach = { ...team.coach, sanctions: newSanctions };
                      const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === 'COACH' && e.team === teamSide && e.sanctionType === type);
                      if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                  }
              }
          }
      }
      else if (selectedTarget.type === 'assistant-coach' && team.assistantCoach) {
          if (type !== 'goal' && type !== '7m') {
              if (inc) {
                  if (type === SanctionType.YELLOW) {
                      if (team.assistantCoach.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                  }
                  const s: any = { type: type as SanctionType, timestamp: eventTime };
                  // USE CONFIGURABLE SUSPENSION DURATION
                  if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                  team.assistantCoach = { ...team.assistantCoach, sanctions: [...team.assistantCoach.sanctions, s] };
                  newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: 'ASSISTANT_COACH',
                    playerName: team.assistantCoach.name,
                    sanctionType: type as SanctionType
                 });
              } else {
                  const sIdx = team.assistantCoach.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                  if (sIdx > -1) {
                      const newSanctions = [...team.assistantCoach.sanctions];
                      newSanctions.splice(sIdx, 1);
                      team.assistantCoach = { ...team.assistantCoach, sanctions: newSanctions };
                      const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === 'ASSISTANT_COACH' && e.team === teamSide && e.sanctionType === type);
                      if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                  }
              }
          }
      }

      newMatch[teamKey] = team;
      return newMatch;
    });
  }, [match, selectedTarget]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (match?.isActive) {
        setMatch(prev => {
          if (!prev) return null;
          let nextTimer = prev.timer + 1;
          let nextActive = true;
          const { halfDuration, otDuration } = prev.config;

          if (prev.period === MatchPeriod.FIRST_HALF && nextTimer >= halfDuration) nextActive = false;
          else if (prev.period === MatchPeriod.SECOND_HALF && nextTimer >= halfDuration * 2) nextActive = false;

          // OT1 
          else if (prev.period === MatchPeriod.OT1_H1 && nextTimer >= (halfDuration * 2) + otDuration) nextActive = false;
          else if (prev.period === MatchPeriod.OT1_H2 && nextTimer >= (halfDuration * 2) + (otDuration * 2)) nextActive = false;

          // OT2
          else if (prev.period === MatchPeriod.OT2_H1 && nextTimer >= (halfDuration * 2) + (otDuration * 2) + otDuration) nextActive = false;
          else if (prev.period === MatchPeriod.OT2_H2 && nextTimer >= (halfDuration * 2) + (otDuration * 2) + (otDuration * 2)) nextActive = false;

          const updateS = (t: Team) => ({
            ...t, 
            players: t.players.map(p => {
                // Find the first active 2-minute suspension.
                // Logic: 2-minute suspensions must be served sequentially.
                // We find the first one that has remainingTime > 0 and decrement it.
                // Subsequent ones will wait until the first is done.
                const firstActiveIndex = p.sanctions.findIndex(s => s.type === SanctionType.TWO_MINUTES && s.remainingTime !== undefined && s.remainingTime > 0);

                if (firstActiveIndex === -1) return p;

                return {
                    ...p,
                    sanctions: p.sanctions.map((s, idx) => {
                        if (idx === firstActiveIndex && s.remainingTime) {
                            return { ...s, remainingTime: s.remainingTime - 1 };
                        }
                        return s;
                    })
                };
            }),
            coach: { ...t.coach, sanctions: t.coach.sanctions.map(s => (s.type === SanctionType.TWO_MINUTES && s.remainingTime && s.remainingTime > 0) ? { ...s, remainingTime: s.remainingTime - 1 } : s) },
            assistantCoach: t.assistantCoach ? { ...t.assistantCoach, sanctions: t.assistantCoach.sanctions.map(s => (s.type === SanctionType.TWO_MINUTES && s.remainingTime && s.remainingTime > 0) ? { ...s, remainingTime: s.remainingTime - 1 } : s) } : undefined
          });

          return { ...prev, timer: nextTimer, isActive: nextActive, homeTeam: updateS(prev.homeTeam), awayTeam: updateS(prev.awayTeam) };
        });
      }
      if (timeoutTimer !== null) { if (timeoutTimer > 0) setTimeoutTimer(p => p !== null ? p - 1 : null); else setTimeoutTimer(null); }
    }, 1000 / timerSpeed);
    return () => clearInterval(timer);
  }, [match?.isActive, timeoutTimer, timerSpeed]);

  return (
    <div className={`min-h-screen flex flex-col font-sans transition-colors duration-300 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`} dir="rtl">
      <header className={`${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-b p-3 sticky top-0 z-[110] flex justify-between items-center shadow-md`}>
        <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView('setup_choice')}>
          <Trophy className="text-blue-500" size={24} />
          <h1 className="text-sm font-black uppercase tracking-tighter hidden sm:block">HandManager PRO</h1>
        </div>

        <div className="flex gap-4 items-center">
          <div className="flex gap-1">
            <button onClick={() => setTimerSpeed(prev => prev === 1 ? 10 : 1)} className={`p-2 rounded-xl hover:bg-slate-500/10 transition-colors flex items-center gap-1 font-black text-xs ${timerSpeed > 1 ? 'text-amber-500 bg-amber-500/10' : 'text-slate-400'}`}><Zap size={16} /><span>{timerSpeed}x</span></button>
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 rounded-xl hover:bg-slate-500/10 transition-colors">{isDarkMode ? <Sun size={20} /> : <Moon size={20} />}</button>
            <button onClick={() => setView('archive')} className={`p-2 rounded-xl hover:bg-slate-500/10 transition-colors ${view === 'archive' ? 'bg-blue-500/10 text-blue-500' : ''}`}><History size={20} /></button>
            <button onClick={() => setView('setup_choice')} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-black text-xs transition-all ${view === 'setup' || view === 'setup_choice' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300'}`}><Plus size={16} strokeWidth={3} /><span className="hidden sm:inline">مباراة جديدة</span></button>
            <button onClick={handleSettingsClick} className="p-2 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition-colors"><SettingsIcon size={20} /></button>
            {match && <button onClick={() => setView('match')} className={`p-2 rounded-xl hover:bg-slate-500/10 transition-colors ${view === 'match' ? 'bg-blue-500/10 text-blue-500' : 'text-blue-500'}`}><Play size={20} /></button>}
            {match && <button onClick={() => setView('sheet')} className={`p-2 rounded-xl hover:bg-slate-500/10 transition-colors ${view === 'sheet' ? 'bg-green-500/10 text-green-500' : 'text-green-500'}`}><ClipboardList size={20} /></button>}
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col overflow-hidden">
        {view === 'setup_choice' && <div className="p-4 max-w-2xl mx-auto w-full h-full overflow-y-auto"><SetupChoice schedule={schedule} onChoice={handleNewMatchChoice} isDarkMode={isDarkMode} /></div>}
        {view === 'setup' && <div className="p-4 max-w-lg mx-auto w-full overflow-y-auto h-full"><SetupForm onStart={startMatch} isDarkMode={isDarkMode} schedule={schedule} initialMatch={preSelectedScheduledMatch} /></div>}
        {view === 'admin_schedule' && <div className="p-4 max-w-4xl mx-auto w-full h-full overflow-hidden"><ScheduleManager schedule={schedule} onSave={saveScheduleToLocal} onClose={() => setView('setup_choice')} isDarkMode={isDarkMode} /></div>}
        {view === 'match' && match && <div className="flex flex-col h-full relative overflow-hidden">
            <div className={`flex-shrink-0 z-[100] border-b shadow-xl ${isDarkMode ? 'bg-slate-900/95 border-slate-800' : 'bg-white/95 border-slate-200'} backdrop-blur-md`}>
              <div className="p-2 max-w-7xl mx-auto flex flex-col gap-2">
                <ScoreBoard 
                    match={match} 
                    onToggleTimer={() => setMatch(m => m ? {...m, isActive: !m.isActive} : null)} 
                    onTimeout={handleTimeout} 
                    onCancelTimeout={handleCancelTimeout} 
                    onFinishMatch={handleFinishMatch} 
                    onPeriodChange={onPeriodChangeRequest}
                    timeoutTimer={timeoutTimer} 
                    breakTimer={null} 
                    isDarkMode={isDarkMode} 
                />
                {match.period !== MatchPeriod.PENALTIES && (
                   <ActionPanel 
                       match={match} 
                       selectedTarget={selectedTarget} 
                       onAction={handleAction} 
                       onUndo={() => {}} 
                       hasHistory={history.length > 0} 
                       isDarkMode={isDarkMode} 
                       matchActive={match.isActive} 
                       isTimeoutActive={timeoutTimer !== null} 
                       playerSuspended={false} 
                       suspensionDuration={match.config.suspensionDuration}
                   />
                )}
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-2 sm:p-4 scroll-smooth">
              {match.period === MatchPeriod.PENALTIES ? (
                <PenaltyShootout match={match} onShot={handlePenaltyShot} isDarkMode={isDarkMode} />
              ) : (
                <div className={`w-full grid grid-cols-2 gap-2 sm:gap-4 h-full`}>
                    {/* SWAPPED ORDER FOR VISUAL ALIGNMENT WITH SCOREBOARD IN RTL */}
                    <TeamControl team={match.homeTeam} side="home" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                    <TeamControl team={match.awayTeam} side="away" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                </div>
              )}
            </div>
          </div>}
        {view === 'sheet' && match && <div className="p-4 h-full overflow-y-auto"><MatchSheet match={match} onUpdate={setMatch} /></div>}
        {view === 'archive' && <div className="p-4 h-full overflow-y-auto"><ArchiveList matches={archive} isDarkMode={isDarkMode} onSelect={(m) => { setMatch(m); setView('match'); }} onDelete={deleteFromArchive} /></div>}

        {/* Footer Credit */}
        <div className={`py-2 text-center text-[10px] font-bold ${isDarkMode ? 'bg-slate-900 text-slate-500 border-t border-slate-800' : 'bg-white text-slate-400 border-t border-slate-200'}`}>
           تمت برمجة وتطوير التطبيق من طرف السيد أمين سنوسي، والسيد عمر حماني. مديرية تاوريرت
        </div>
      </main>

      {/* Penalty Setup Modal */}
      {/* ... Penalty Setup Modal content ... */}
      {showPenaltySetup && match && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
           <div className={`w-full max-w-md rounded-[2.5rem] border-2 shadow-2xl p-6 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="text-center mb-6">
                 <div className="w-16 h-16 bg-purple-600 rounded-full flex items-center justify-center text-white mb-2 shadow-lg shadow-purple-600/30 mx-auto">
                    <Trophy size={32} />
                 </div>
                 <h3 className="text-xl font-black">إعداد رميات 7 أمتار</h3>
                 <p className="text-xs text-slate-500 font-bold mt-1">يجب تحديد عدد الرميات والقرعة قبل البدء</p>
              </div>

              {/* Number of Shots */}
              <div className="mb-6">
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-2 text-center">عدد الرميات (لكل فريق)</label>
                  <div className="flex items-center justify-center gap-4">
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: Math.max(1, prev.shots - 1) }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">-</button>
                      <div className="text-3xl font-black w-16 text-center">{penaltyConfig.shots}</div>
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: prev.shots + 1 }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">+</button>
                  </div>
              </div>

              {/* Coin Toss / Starter Selection */}
              <div className="mb-8">
                   <label className="text-[10px] font-black text-slate-500 uppercase block mb-3 text-center flex items-center justify-center gap-1"><Coins size={12}/> القرعة: من سيبدأ الرمي؟</label>
                   <div className="grid grid-cols-2 gap-3">
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'home' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'home' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.homeTeam.color }} />
                           {match.homeTeam.name}
                       </button>
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'away' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'away' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.awayTeam.color }} />
                           {match.awayTeam.name}
                       </button>
                   </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                 <button onClick={confirmPenaltySetup} disabled={!penaltyConfig.starter} className="py-3 bg-purple-600 text-white font-black rounded-xl shadow-lg hover:bg-purple-500 disabled:opacity-50 transition-colors">بدء الرميات</button>
                 <button onClick={() => setShowPenaltySetup(false)} className={`py-3 font-black rounded-xl border-2 transition-colors ${isDarkMode ? 'border-slate-700 hover:bg-slate-800' : 'border-slate-200 hover:bg-slate-50'}`}>إلغاء</button>
              </div>
           </div>
        </div>
      )}

      {/* Admin Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => setShowLoginModal(false)} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-blue-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">الدخول للإعدادات</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">يرجى إدخال القن السري للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري</label><input type="password" autoFocus value={loginPass} onChange={e => setLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleLogin} className="w-full py-3 bg-blue-600 text-white font-black rounded-xl shadow-lg shadow-blue-600/20 hover:bg-blue-500 transition-colors mt-2">دخول</button>
            </div>
          </div>
        </div>
      )}

      {/* Center Password Verification Modal */}
      {showCenterPasswordModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => { setShowCenterPasswordModal(false); setPendingScheduledMatch(null); }} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-amber-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-amber-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">تحقق من المركز</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">المقابلة في: {pendingScheduledMatch?.lieu}</p>
               <p className="text-[10px] text-amber-500 font-bold mt-1">يرجى إدخال القن السري للمركز للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري للمركز</label><input type="password" autoFocus value={centerLoginPass} onChange={e => setCenterLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleCenterLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleCenterLogin} className="w-full py-3 bg-amber-600 text-white font-black rounded-xl shadow-lg shadow-amber-600/20 hover:bg-amber-500 transition-colors mt-2">تأكيد الدخول</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
export default App;

import React, { useRef, useState } from 'react';
import { SanctionType, MatchState } from '../types.ts';
import { Zap, Crosshair, AlertCircle } from 'lucide-react';

interface ActionPanelProps {
  match: MatchState; 
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onAction: (type: 'goal' | '7m' | SanctionType, inc?: boolean) => void;
  onUndo: () => void;
  hasHistory: boolean;
  isDarkMode: boolean;
  matchActive: boolean;
  isTimeoutActive: boolean;
  playerSuspended: boolean;
  suspensionDuration?: number; // 60 or 120
}

export const ActionPanel: React.FC<ActionPanelProps> = ({
  match,
  selectedTarget,
  onAction,
  onUndo,
  hasHistory,
  isDarkMode,
  matchActive,
  isTimeoutActive,
  playerSuspended,
  suspensionDuration = 120 // default 2 minutes
}) => {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLongPress = useRef(false);
  const [activePress, setActivePress] = useState<string | null>(null);

  // State for 2-minute confirmation
  const [showTwoMinConfirm, setShowTwoMinConfirm] = useState(false);
  // State for 3rd suspension warning
  const [showThirdSuspensionWarning, setShowThirdSuspensionWarning] = useState(false);

  const handlePointerDown = (type: 'goal' | '7m' | SanctionType) => {
    isLongPress.current = false;
    setActivePress(type);
    timerRef.current = setTimeout(() => {
      isLongPress.current = true;
      onAction(type, false); // Trigger undo (inc = false)
      if (navigator.vibrate) navigator.vibrate([30, 30]); // Double haptic for undo
      setActivePress(null);
    }, 700); // 700ms for long press
  };

  const handlePointerUp = (type: 'goal' | '7m' | SanctionType) => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }

    if (!isLongPress.current && activePress === type) {
       // Special handling for 2-minute suspension
       if (type === SanctionType.TWO_MINUTES) {
           // Check if it's the 3rd suspension
           if (isPlayer && twoMinCount >= 2) {
               setShowThirdSuspensionWarning(true);
           } else {
               setShowTwoMinConfirm(true);
           }
       } else {
           onAction(type, true); // Trigger normal action (inc = true)
       }
    }
    setActivePress(null);
  };

  const handlePointerLeave = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    setActivePress(null);
  };

  const confirmTwoMin = () => {
      onAction(SanctionType.TWO_MINUTES, true);
      setShowTwoMinConfirm(false);
  };

  if (!selectedTarget) {
    return (
      <div className={`flex items-center justify-center p-4 rounded-2xl border-2 border-dashed ${isDarkMode ? 'border-slate-800 text-slate-500' : 'border-slate-200 text-slate-400'}`}>
        <div className="flex items-center gap-2">
          <TargetIcon />
          <span className="text-xs font-bold">حدد لاعباً أو مؤطراً لتنفيذ إجراء</span>
        </div>
      </div>
    );
  }

  const isPlayer = selectedTarget.type === 'player';
  const team = selectedTarget.team === 'home' ? match.homeTeam : match.awayTeam;

  // --- RÈGLES OFFICIELLES HANDBALL ---

  let isDisqualified = false;
  let hasBlueCard = false;
  let hasRedCard = false;
  let hasYellowCard = false;
  let twoMinCount = 0;
  let disqualificationReason = "ضغطة مطولة للإلغاء";

  if (isPlayer) {
    const player = team.players.find(p => p.id === selectedTarget.id);
    if (player) {
        hasRedCard = player.sanctions.some(s => s.type === SanctionType.RED);
        hasBlueCard = player.sanctions.some(s => s.type === SanctionType.BLUE);
        hasYellowCard = player.sanctions.some(s => s.type === SanctionType.YELLOW);
        twoMinCount = player.sanctions.filter(s => s.type === SanctionType.TWO_MINUTES).length;

        if (hasRedCard || hasBlueCard) {
            isDisqualified = true;
            disqualificationReason = hasBlueCard ? "اللاعب لديه بطاقة زرقاء" : "اللاعب مستبعد (بطاقة حمراء)";
        }
    }
  } else if (selectedTarget.type === 'coach') {
      hasBlueCard = team.coach.sanctions.some(s => s.type === SanctionType.BLUE);
      hasRedCard = team.coach.sanctions.some(s => s.type === SanctionType.RED);
      hasYellowCard = team.coach.sanctions.some(s => s.type === SanctionType.YELLOW);
      if(hasRedCard || hasBlueCard) isDisqualified = true;

  } else if (selectedTarget.type === 'assistant-coach') {
      hasBlueCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.BLUE) || false;
      hasRedCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.RED) || false;
      hasYellowCard = team.assistantCoach?.sanctions.some(s => s.type === SanctionType.YELLOW) || false;
      if(hasRedCard || hasBlueCard) isDisqualified = true;
  }

  // Règle Buts
  const canGoal = isPlayer && !isTimeoutActive && !playerSuspended && !isDisqualified && matchActive;

  let goalTitle = "ضغطة مطولة للإلغاء";
  if (isDisqualified) goalTitle = disqualificationReason;
  else if (playerSuspended) goalTitle = "اللاعب موقوف";
  else if (isTimeoutActive) goalTitle = "وقت مستقطع";
  else if (!matchActive) goalTitle = "الميقات متوقف (لا يمكن التسجيل)";

  // Règle Carton Jaune
  let canYellow = !isDisqualified;
  let yellowReason = isDisqualified ? disqualificationReason : "ضغطة مطولة للإلغاء";

  if (isPlayer && canYellow) {
      if (hasYellowCard) {
          canYellow = false;
          yellowReason = "لديه بطاقة صفراء مسبقاً";
      } else {
           const teamPlayersYellowCount = team.players.reduce((total, p) => 
              total + p.sanctions.filter(s => s.type === SanctionType.YELLOW).length, 0
           );
           if (teamPlayersYellowCount >= 3) {
              canYellow = false;
              yellowReason = "الحد الأقصى (3) للفريق مكتمل";
           }
      }
  } else if (!isPlayer) {
      if (hasYellowCard) {
          canYellow = false;
          yellowReason = "لديه بطاقة صفراء";
      }
  }

  // Règle 2 Minutes
  // Permettre le clic même si twoMinCount >= 2 pour afficher l'alerte
  const canTwoMin = !isDisqualified; 
  const twoMinReason = isDisqualified ? disqualificationReason : "ضغطة مطولة للإلغاء";

  // Règle Rouge
  const canRed = !isDisqualified; 

  // Règle Carte Bleue : 
  // ACTIVÉE UNIQUEMENT SI DÉJÀ ROUGE (et pas encore bleue)
  const canBlue = hasRedCard && !hasBlueCard;
  // Enable button if action is possible OR if we need to undo a blue card
  const enableBlueButton = canBlue || hasBlueCard;

  const btnBaseClass = "flex flex-col items-center justify-center gap-1 p-2 rounded-2xl border-2 transition-all shadow-sm select-none touch-none active:scale-95";
  const disabledClass = "bg-slate-500/10 border-slate-500/20 text-slate-500 cursor-not-allowed opacity-50 shadow-none active:scale-100";

  const renderActionButton = (
    type: 'goal' | '7m' | SanctionType, 
    label: string, 
    icon: React.ReactNode, 
    activeColorClass: string,
    enabled: boolean,
    title?: string
  ) => {
    const isPressed = activePress === type;

    return (
      <button
        disabled={!enabled}
        onPointerDown={() => enabled && handlePointerDown(type)}
        onPointerUp={() => enabled && handlePointerUp(type)}
        onPointerLeave={handlePointerLeave}
        className={`${btnBaseClass} ${enabled ? activeColorClass : disabledClass} ${isPressed ? 'scale-90 brightness-110 shadow-inner' : ''}`}
        title={title}
      >
        {icon}
        <span className="text-[10px] font-black">{label}</span>
      </button>
    );
  };

  const suspensionLabel = suspensionDuration === 60 ? "1'" : "2'";
  const suspensionText = suspensionDuration === 60 ? "دقيقة واحدة" : "دقيقتين";

  return (
    <>
    <div className="grid grid-cols-3 sm:grid-cols-6 gap-2 w-full">
      {/* Goal Action */}
      {renderActionButton(
        'goal', 
        'هدف', 
        <Zap size={20} fill={canGoal ? "currentColor" : "none"} />, 
        'bg-green-600 border-green-500 text-white',
        canGoal,
        goalTitle
      )}

      {/* 7m Shot Action */}
      {renderActionButton(
        '7m', 
        '7 أمتار', 
        <Crosshair size={20} />, 
        'bg-indigo-600 border-indigo-500 text-white',
        canGoal,
        goalTitle
      )}

      {/* Yellow Card Action */}
      {renderActionButton(
        SanctionType.YELLOW, 
        'بطاقة صفراء', 
        <div className="w-4 h-6 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm" />, 
        'bg-yellow-400 border-yellow-500 text-yellow-950',
        canYellow || hasYellowCard, 
        hasYellowCard ? "ضغطة مطولة لإلغاء البطاقة" : yellowReason
      )}

      {/* 2 Minutes Suspension Action (or 1 minute) */}
      {renderActionButton(
        SanctionType.TWO_MINUTES, 
        suspensionText, 
        <div className="text-lg font-black leading-none">{suspensionLabel}</div>, 
        'bg-slate-900 border-slate-700 text-white',
        canTwoMin, 
        twoMinReason
      )}

      {/* Red Card Action - Rouj */}
      {renderActionButton(
        SanctionType.RED, 
        'بطاقة حمراء', 
        <div className="w-4 h-6 bg-red-600 rounded-sm border border-red-800 shadow-sm" />, 
        'bg-red-600 border-red-700 text-white',
        canRed || hasRedCard, 
        hasRedCard ? "ضغطة مطولة لإلغاء البطاقة" : (isDisqualified ? "اللاعب مستبعد بالفعل" : "ضغطة مطولة للإلغاء")
      )}

      {/* Blue Card (Report) Action */}
      {renderActionButton(
        SanctionType.BLUE, 
        'بطاقة زرقاء', 
        <div className="w-4 h-6 bg-blue-600 rounded-sm border border-blue-800 shadow-sm" />, 
        'bg-blue-600 border-blue-700 text-white',
        enableBlueButton, 
        hasBlueCard ? "ضغطة مطولة لإلغاء البطاقة" : (!hasRedCard ? "يجب منح بطاقة حمراء أولاً" : "كتابة التقرير في ورقة المباراة")
      )}
    </div>

    {/* Confirmation Modal for 2 Minutes */}
    {showTwoMinConfirm && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm p-6 rounded-[2rem] border-2 shadow-2xl relative animate-in zoom-in duration-200 ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-100 text-slate-900'}`}>
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center text-white mb-2 shadow-lg border-2 border-slate-700">
                    <span className="text-3xl font-black">{suspensionLabel}</span>
                 </div>
                 <h3 className="text-xl font-black">تأكيد الإقصاء المؤقت</h3>
                 <p className="text-xs text-slate-500 font-bold mt-1 px-4">
                    هل أنت متأكد من منح {suspensionText} لهذا {isPlayer ? 'اللاعب' : 'المؤطر'}؟
                 </p>
                 {isPlayer && (
                   <p className="text-[10px] text-amber-500 font-bold mt-2 bg-amber-500/10 px-2 py-1 rounded">
                     سيتم إيقافه عن اللعب لمدة {suspensionDuration / 60} دقيقة
                   </p>
                 )}
             </div>
             <div className="grid grid-cols-2 gap-3">
                 <button onClick={confirmTwoMin} className="py-3 bg-blue-600 text-white font-black rounded-xl shadow-lg hover:bg-blue-500 transition-colors">تأكيد</button>
                 <button onClick={() => setShowTwoMinConfirm(false)} className={`py-3 font-black rounded-xl border-2 transition-colors ${isDarkMode ? 'border-slate-700 hover:bg-slate-800' : 'border-slate-200 hover:bg-slate-50'}`}>إلغاء</button>
             </div>
          </div>
        </div>
    )}

    {/* Warning Modal for 3rd Suspension */}
    {showThirdSuspensionWarning && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200" dir="rtl">
          <div className="w-full max-w-sm p-6 rounded-[2rem] border-2 border-red-500 shadow-2xl bg-red-950 text-white relative animate-in zoom-in duration-200">
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-20 h-20 bg-red-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-red-600/40 animate-pulse">
                    <AlertCircle size={40} strokeWidth={3} />
                 </div>
                 <h3 className="text-2xl font-black mb-2">تنبيه هام!</h3>
                 <p className="text-sm text-red-200 font-bold px-2 leading-relaxed">
                    لا يمكن منح إيقاف ثالث لهذا اللاعب.
                    <br/>
                    <span className="text-white bg-red-500/20 px-2 py-1 rounded mt-2 inline-block">يتوجب عليك إعطاء البطاقة الحمراء</span>
                 </p>
             </div>
             <button onClick={() => setShowThirdSuspensionWarning(false)} className="w-full py-4 bg-white text-red-700 font-black rounded-xl hover:bg-red-50 transition-colors shadow-lg">حسناً، فهمت</button>
          </div>
        </div>
    )}
    </>
  );
};

