export const MatchSheet: React.FC<{ match: MatchState; onUpdate: (m: MatchState) => void }> = ({ match, onUpdate }) => {
  useEffect(() => { ensureArabicFont(); }, []);

  const [signatureModal, setSignatureModal] = useState<{
      open: boolean;
      title: string;
      onSave: (data: string) => void;
  }>({ open: false, title: '', onSave: () => {} });

  // State for Reservation Modal
  const [reservationModal, setReservationModal] = useState<{
      open: boolean;
      team: 'home' | 'away' | null;
      text: string;
  }>({ open: false, team: null, text: '' });

  // State for Report Modal
  const [reportModal, setReportModal] = useState<{
      open: boolean;
      text: string;
  }>({ open: false, text: '' });

