      openSignature(`توقيع ${roleName} - ${teamName}`, (data) => {
          const newMatch = { ...match };
          const t = team === 'home' ? newMatch.homeTeam : newMatch.awayTeam;
          if (!t.signatures) t.signatures = {};
          t.signatures[role] = data;
          onUpdate(newMatch);
