                  <button onClick={() => setAwayCount(Math.min(14, awayCount + 1))} className={`w-6 h-6 rounded flex items-center justify-center text-white text-xs ${isDarkMode ? 'bg-slate-700' : 'bg-slate-800'}`}>+</button>
                </div>
