                <div className={`w-full grid grid-cols-2 gap-2 sm:gap-4 h-full`}>
                    {/* SWAPPED ORDER FOR VISUAL ALIGNMENT WITH SCOREBOARD IN RTL */}
                    <TeamControl team={match.homeTeam} side="home" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                    <TeamControl team={match.awayTeam} side="away" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                </div>
              )}
            </div>
          </div>}
        {view === 'sheet' && match && <div className="p-4 h-full overflow-y-auto"><MatchSheet match={match} onUpdate={setMatch} /></div>}
        {view === 'archive' && <div className="p-4 h-full overflow-y-auto"><ArchiveList matches={archive} isDarkMode={isDarkMode} onSelect={(m) => { setMatch(m); setView('match'); }} onDelete={deleteFromArchive} /></div>}

        {/* Footer Credit */}
        <div className={`py-2 text-center text-[10px] font-bold ${isDarkMode ? 'bg-slate-900 text-slate-500 border-t border-slate-800' : 'bg-white text-slate-400 border-t border-slate-200'}`}>
           تمت برمجة وتطوير التطبيق من طرف السيد أمين سنوسي، والسيد عمر حماني. مديرية تاوريرت
        </div>
      </main>

      {/* Penalty Setup Modal */}
      {/* ... Penalty Setup Modal content ... */}
      {showPenaltySetup && match && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
           <div className={`w-full max-w-md rounded-[2.5rem] border-2 shadow-2xl p-6 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="text-center mb-6">
                 <div className="w-16 h-16 bg-purple-600 rounded-full flex items-center justify-center text-white mb-2 shadow-lg shadow-purple-600/30 mx-auto">
                    <Trophy size={32} />
                 </div>
                 <h3 className="text-xl font-black">إعداد رميات 7 أمتار</h3>
                 <p className="text-xs text-slate-500 font-bold mt-1">يجب تحديد عدد الرميات والقرعة قبل البدء</p>
              </div>

              {/* Number of Shots */}
              <div className="mb-6">
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-2 text-center">عدد الرميات (لكل فريق)</label>
                  <div className="flex items-center justify-center gap-4">
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: Math.max(1, prev.shots - 1) }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">-</button>
                      <div className="text-3xl font-black w-16 text-center">{penaltyConfig.shots}</div>
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: prev.shots + 1 }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">+</button>
                  </div>
              </div>

              {/* Coin Toss / Starter Selection */}
              <div className="mb-8">
                   <label className="text-[10px] font-black text-slate-500 uppercase block mb-3 text-center flex items-center justify-center gap-1"><Coins size={12}/> القرعة: من سيبدأ الرمي؟</label>
                   <div className="grid grid-cols-2 gap-3">
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'home' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'home' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.homeTeam.color }} />
                           {match.homeTeam.name}
                       </button>
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'away' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'away' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.awayTeam.color }} />
                           {match.awayTeam.name}
                       </button>
                   </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                 <button onClick={confirmPenaltySetup} disabled={!penaltyConfig.starter} className="py-3 bg-purple-600 text-white font-black rounded-xl shadow-lg hover:bg-purple-500 disabled:opacity-50 transition-colors">بدء الرميات</button>
                 <button onClick={() => setShowPenaltySetup(false)} className={`py-3 font-black rounded-xl border-2 transition-colors ${isDarkMode ? 'border-slate-700 hover:bg-slate-800' : 'border-slate-200 hover:bg-slate-50'}`}>إلغاء</button>
              </div>
           </div>
        </div>
      )}

      {/* Admin Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => setShowLoginModal(false)} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-blue-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">الدخول للإعدادات</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">يرجى إدخال القن السري للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري</label><input type="password" autoFocus value={loginPass} onChange={e => setLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleLogin} className="w-full py-3 bg-blue-600 text-white font-black rounded-xl shadow-lg shadow-blue-600/20 hover:bg-blue-500 transition-colors mt-2">دخول</button>
            </div>
          </div>
        </div>
      )}

      {/* Center Password Verification Modal */}
      {showCenterPasswordModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => { setShowCenterPasswordModal(false); setPendingScheduledMatch(null); }} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-amber-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-amber-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">تحقق من المركز</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">المقابلة في: {pendingScheduledMatch?.lieu}</p>
               <p className="text-[10px] text-amber-500 font-bold mt-1">يرجى إدخال القن السري للمركز للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري للمركز</label><input type="password" autoFocus value={centerLoginPass} onChange={e => setCenterLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleCenterLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleCenterLogin} className="w-full py-3 bg-amber-600 text-white font-black rounded-xl shadow-lg shadow-amber-600/20 hover:bg-amber-500 transition-colors mt-2">تأكيد الدخول</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
export default App;

import React, { useState, useEffect } from 'react';
import { Officials, MatchDetails, ScheduledMatch } from '../types.ts';
import { Palette, Link, Crown, Shield } from 'lucide-react';

interface PlayerInput {
  number: string;
  name: string;
  licence: string; // New field
  isCaptain: boolean;
  isGoalkeeper: boolean;
}

interface SetupFormProps {
  onStart: (
    h: string, hcoach: string, hast: string, hplayers: PlayerInput[], hcolor: string,
    a: string, acoach: string, aast: string, aplayers: PlayerInput[], acolor: string,
    halfDur: number, otDur: number, suspensionDur: number, off: Officials, det: MatchDetails
  ) => void;
  isDarkMode?: boolean;
  schedule?: ScheduledMatch[];
  initialMatch?: ScheduledMatch | null;
  // Props for restoring state when going back to settings
  initialHomePlayers?: PlayerInput[];
  initialAwayPlayers?: PlayerInput[];
  initialHomeCoach?: string;
  initialAwayCoach?: string;
  initialHomeAst?: string;
  initialAwayAst?: string;
  initialHomeColor?: string;
  initialAwayColor?: string;
}

const PRESET_COLORS = [
  { name: 'Bleu Pro', hex: '#1d4ed8' },
  { name: 'Rouge Intense', hex: '#b91c1c' },
  { name: 'Vert Forêt', hex: '#15803d' },
  { name: 'Jaune Or', hex: '#eab308' },
  { name: 'Noir Pur', hex: '#0f172a' },
  { name: 'Orange Feu', hex: '#ea580c' },
  { name: 'Violet Royal', hex: '#7e22ce' },
  { name: 'Gris Béton', hex: '#4b5563' },
];

export const SetupForm: React.FC<SetupFormProps> = ({ 
  onStart, 
  isDarkMode = false, 
  schedule = [], 
  initialMatch = null,
  initialHomePlayers,
  initialAwayPlayers,
  initialHomeCoach,
  initialAwayCoach,
  initialHomeAst,
  initialAwayAst,
  initialHomeColor,
  initialAwayColor
}) => {
  // Initialisation avec des valeurs par défaut extraites de la feuille de match ou des props de restauration
  const [home, setHome] = useState(initialMatch?.homeTeam || 'اعدادية وادزا');
  const [homeCoach, setHomeCoach] = useState(initialHomeCoach || 'حسن بوقدير');
  const [homeAst, setHomeAst] = useState(initialHomeAst || 'عمر حماني');
  const [homeColor, setHomeColor] = useState(initialHomeColor || PRESET_COLORS[4].hex); // Noir
  const [homeCount, setHomeCount] = useState(initialHomePlayers ? initialHomePlayers.length : 14);
  const [homePlayers, setHomePlayers] = useState<PlayerInput[]>(initialHomePlayers || [
    { number: '3', name: 'رشيد المنصوري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '4', name: 'حمزة السعيدي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '7', name: 'يوسف البقالي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '9', name: 'ياسين الحضيكي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '14', name: 'سليمان الدبوزي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '18', name: 'نبيل الفاسي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '19', name: 'عدنان الزروالي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '21', name: 'عادل الصقلي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '25', name: 'أنس الرماح', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '27', name: 'فؤاد الكتاني', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '30', name: 'مصطفى البصري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '32', name: 'كمال بنموسى', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '33', name: 'خالد التازي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '36', name: 'طارق الحراق', licence: '', isCaptain: false, isGoalkeeper: false },
  ]);

  const [away, setAway] = useState(initialMatch?.awayTeam || 'إعدادية بدر');
  const [awayCoach, setAwayCoach] = useState(initialAwayCoach || 'سعيد الفكرود');
  const [awayAst, setAwayAst] = useState(initialAwayAst || 'زكرياء شرقي');
  const [awayColor, setAwayColor] = useState(initialAwayColor || PRESET_COLORS[2].hex); // Vert
  const [awayCount, setAwayCount] = useState(initialAwayPlayers ? initialAwayPlayers.length : 14);
  const [awayPlayers, setAwayPlayers] = useState<PlayerInput[]>(initialAwayPlayers || [
    { number: '3', name: 'وليد الطاهري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '5', name: 'عبد الإله الوردي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '6', name: 'رياض الشرقاوي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '8', name: 'عمر بوعزة', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '11', name: 'هشام العلوي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '12', name: 'مراد بنصالح', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '15', name: 'أشرف المرزوقي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '17', name: 'يوسف الناصري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '20', name: 'مروان الزموري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '22', name: 'أمين الشمسي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '23', name: 'نور الدين الأنصاري', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '29', name: 'إسماعيل الخرافي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '31', name: 'سفيان العلمي', licence: '', isCaptain: false, isGoalkeeper: false },
    { number: '34', name: 'سليم أمزيل', licence: '', isCaptain: false, isGoalkeeper: false },
  ]);

  const [halfDur, setHalfDur] = useState(20); 
  const [otDur, setOtDur] = useState(5);
  const [suspensionDur, setSuspensionDur] = useState(2); // 2 minutes or 1 minute
  const [activeTab, setActiveTab] = useState<'details' | 'teamA' | 'teamB' | 'officials'>('details');

  const [details, setDetails] = useState<MatchDetails>({
    direction: 'تاوريرت', 
    aref: 'الشرق', 
    categorie: initialMatch?.category || 'ذكور U15 - البطولة المدرسية',
    ville: 'تاوريرت', 
    lieu: initialMatch?.lieu || 'القاعة المغطاة (تاوريرت)', 
    sexe: 'M', 
    numRencontre: '1',
    etape: '', 
    date: initialMatch?.date || '2026-01-15', 
    time: initialMatch?.time || '15:00',
    matchLink: ''
  });

  const [officials, setOfficials] = useState<Officials>({
    referee1: initialMatch?.officials.referee1 || 'رضوان الكوت', 
    referee2: initialMatch?.officials.referee2 || 'فريد بنقدور', 
    timer: initialMatch?.officials.timer || '', 
    secretary: initialMatch?.officials.secretary || '', 
    chefCentre: initialMatch?.officials.chefCentre || ''
  });

  // Ensure player lists update if counts change manually
  useEffect(() => {
    setHomePlayers(prev => {
      const next = [...prev];
      if (next.length < homeCount) {
        for (let i = next.length; i < homeCount; i++) {
            next.push({ number: '', name: '', licence: '', isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, homeCount);
      }
      return next;
    });
  }, [homeCount]);

  useEffect(() => {
    setAwayPlayers(prev => {
      const next = [...prev];
      if (next.length < awayCount) {
        for (let i = next.length; i < awayCount; i++) {
            next.push({ number: '', name: '', licence: '', isCaptain: false, isGoalkeeper: false });
        }
      } else {
        return next.slice(0, awayCount);
      }
      return next;
    });
  }, [awayCount]);

  const validateNumbers = (players: PlayerInput[], teamName: string) => {
    const numbers = new Set<string>();
    const filledPlayers = players.filter(p => p.number.trim() !== '');

    // Check minimum players
    if (filledPlayers.length < 5) {
        alert(`تنبيه: عدد اللاعبين المسجلين في فريق ${teamName} أقل من الحد الأدنى (5). المرجو إضافة لاعبين.`);
        return false;
    }

    for (const p of filledPlayers) {
      if (numbers.has(p.number)) {
        alert(`خطأ: الرقم ${p.number} مكرر في فريق ${teamName}. \n\nيجب تغيير رقم القميص لأحد اللاعبين.`);
        return false;
      }
      numbers.add(p.number);
    }
    return true;
  };

  const handleStart = () => {
    if (!validateNumbers(homePlayers, home)) return;
    if (!validateNumbers(awayPlayers, away)) return;
    onStart(home, homeCoach, homeAst, homePlayers, homeColor, away, awayCoach, awayAst, awayPlayers, awayColor, halfDur, otDur, suspensionDur, officials, details);
  };

  const inputStyle = `w-full p-2 border rounded-xl text-xs font-bold outline-none transition-all ${isDarkMode ? 'bg-slate-900 border-slate-700 text-white focus:border-blue-500' : 'bg-slate-800 border-slate-700 text-white focus:border-blue-400'}`;
  const labelStyle = "block text-[9px] font-black text-slate-500 uppercase mb-1 mr-1";

  const renderColorPicker = (currentColor: string, onSelect: (color: string) => void) => (
    <div className="space-y-1 mt-2">
      <label className={labelStyle}>لون الفريق (للخلفية في ورقة المباراة)</label>
      <div className="flex flex-wrap gap-2">
        {PRESET_COLORS.map((c) => (
          <button
            key={c.hex}
            onClick={() => onSelect(c.hex)}
            className={`w-6 h-6 rounded-lg border-2 transition-all ${currentColor === c.hex ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-60 hover:opacity-100'}`}
            style={{ backgroundColor: c.hex }}
            title={c.name}
          />
        ))}
        <div className={`relative w-6 h-6 rounded-lg overflow-hidden border-2 transition-all flex items-center justify-center ${!PRESET_COLORS.some(c => c.hex === currentColor) ? 'border-white scale-110 shadow-lg' : 'border-slate-500/30 opacity-60 hover:opacity-100'}`} style={{ backgroundColor: !PRESET_COLORS.some(c => c.hex === currentColor) ? currentColor : 'transparent' }}>
             {!PRESET_COLORS.some(c => c.hex === currentColor) ? null : <Palette size={14} className={isDarkMode ? "text-white" : "text-black"} />}
             <input
                type="color"
                value={currentColor}
                onChange={(e) => onSelect(e.target.value)}
                className="absolute inset-0 w-[200%] h-[200%] -translate-x-1/4 -translate-y-1/4 opacity-0 cursor-pointer"
                title="لون مخصص"
            />
        </div>
      </div>
    </div>
  );

  const handlePlayerNumberChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].number = val;
    setter(next);
  };

  const handlePlayerLicenceChange = (
    idx: number, 
    val: string, 
    players: PlayerInput[], 
    setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
    const next = [...players];
    next[idx].licence = val;
    setter(next);
  };

  const toggleCaptain = (
      idx: number,
      players: PlayerInput[],
      setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>
  ) => {
      const next = players.map((p, i) => ({
          ...p,
          isCaptain: i === idx ? !p.isCaptain : false // Ensure only one captain
      }));
      setter(next);
  };

  const renderPlayerInputs = (players: PlayerInput[], setter: React.Dispatch<React.SetStateAction<PlayerInput[]>>) => {
    // Determine duplicates
    const counts: {[key: string]: number} = {};
