            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">نهاية</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">إضافي 1</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">إضافي 2</th>
            <th colSpan={2} className="border border-black bg-black print:bg-black text-center align-middle">7م</th>
            <th colSpan={2} className="border border-black bg-blue-700 text-white w-14 print:bg-blue-700 text-center align-middle font-black">المجموع</th>
          </tr>
          {/* Sub-header for A and B */}
          <tr className="h-5 text-black font-black bg-gray-100 print:bg-gray-100">
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
            <th className="border border-black text-center align-middle">A</th>
            <th className="border border-black text-center align-middle">B</th>
          </tr>
        </thead>
        <tbody>
          <tr className="h-8 font-black text-xs text-black">
