                    autoFocus
                    className="w-full h-48 p-4 rounded-xl border-2 border-slate-200 outline-none text-lg font-bold resize-none bg-slate-50 focus:bg-white focus:border-blue-500 transition-colors"
                    placeholder="اكتب التقرير هنا..."
