                      {/* Global Controls */}
                      <button onClick={() => { setView('setup_choice'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <Plus size={18} /> مباراة جديدة
                      </button>
                      <button onClick={() => { setView('archive'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
