                      </button>
                      <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
