               <TeamRoster team={match.awayTeam} letter="B" teamSide="away" matchEvents={match.events} onSign={(role) => handleTeamSign('away', role)} onEditReservation={() => handleEditReservation('away')} suspensionDuration={match.config.suspensionDuration} />
