import React, { useRef, useState, useMemo } from 'react';
import { MatchState, MatchPeriod, SanctionType } from '../types';
import { Play, Pause, Ban, Flag, ChevronLeft, ChevronRight, RotateCcw, Timer } from 'lucide-react';

interface ScoreBoardProps {
  match: MatchState;
  onToggleTimer: () => void;
  onTimeout: (team: 'home' | 'away') => void;
  onCancelTimeout: (team: 'home' | 'away') => void;
  onFinishMatch: () => void;
  onPeriodChange?: (direction: 'next' | 'prev') => void;
  timeoutTimer: number | null;
  breakTimer: number | null;
  isDarkMode?: boolean;
}

export const ScoreBoard: React.FC<ScoreBoardProps> = ({ 
  match, 
  onToggleTimer, 
  onTimeout, 
  onCancelTimeout,
  onFinishMatch,
  onPeriodChange,
  timeoutTimer, 
  breakTimer,
  isDarkMode = false
}) => {
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const isBreak = match.period === MatchPeriod.BREAK;
  const isExtraTime = match.period.includes('إضافي');
  const timerRefHome = useRef<ReturnType<typeof setTimeout> | null>(null);
  const timerRefAway = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isLongPress = useRef(false);
  const [pressing, setPressing] = useState<'home' | 'away' | null>(null);

  const homeCanTimeout = match.homeTeam.timeoutsUsed < 3 && match.homeTeam.timeoutsThisHalf < 2 && !isExtraTime;
  const awayCanTimeout = match.awayTeam.timeoutsUsed < 3 && match.awayTeam.timeoutsThisHalf < 2 && !isExtraTime;

  const homeCanCancel = match.homeTeam.timeoutsUsed > 0;
  const awayCanCancel = match.awayTeam.timeoutsUsed > 0;

  // Calculate players ending suspension soon (<= 20s)
  const endingSuspensions = useMemo(() => {
    const list: { side: 'home' | 'away', number: string, remaining: number, color: string }[] = [];

    // Check Home Team
    match.homeTeam.players.forEach(p => {
        const s = p.sanctions.find(s => s.type === SanctionType.TWO_MINUTES && s.remainingTime !== undefined && s.remainingTime > 0 && s.remainingTime <= 20);
        if (s) {
            list.push({ side: 'home', number: p.number, remaining: s.remainingTime!, color: match.homeTeam.color });
        }
    });

    // Check Away Team
    match.awayTeam.players.forEach(p => {
        const s = p.sanctions.find(s => s.type === SanctionType.TWO_MINUTES && s.remainingTime !== undefined && s.remainingTime > 0 && s.remainingTime <= 20);
        if (s) {
            list.push({ side: 'away', number: p.number, remaining: s.remainingTime!, color: match.awayTeam.color });
        }
    });

    return list;
  }, [match.homeTeam.players, match.awayTeam.players, match.timer]); // Re-calc on timer tick implicitly via players update

  const canFinishMatch = useMemo(() => {
    if (match.isActive || match.isFinished) return false;
    let isDraw = match.period === MatchPeriod.PENALTIES 
      ? match.score.homePenalties === match.score.awayPenalties 
      : match.score.home === match.score.away;
    if (isDraw) return false;

    const halfDur = match.config.halfDuration;
    const otDur = match.config.otDuration;

    if (match.period === MatchPeriod.SECOND_HALF) return match.timer >= halfDur * 2;
    // We can only finish the match after the SECOND half of an overtime if there is a winner
    if (match.period === MatchPeriod.OT1_H2) return match.timer >= (halfDur * 2) + (otDur * 2);
    if (match.period === MatchPeriod.OT2_H2) return match.timer >= (halfDur * 2) + (otDur * 2) + (otDur * 2);

    if (match.period === MatchPeriod.PENALTIES) {
       const hShots = match.penaltySequence.home.length;
       const aShots = match.penaltySequence.away.length;
       const maxShots = match.config.penaltyShots || 5;
       if (hShots < maxShots || aShots < maxShots) {
          const remainingH = maxShots - hShots; 
          const remainingA = maxShots - aShots;
          if (match.score.homePenalties > match.score.awayPenalties + remainingA || match.score.awayPenalties > match.score.homePenalties + remainingH) return true;
          return false;
       }
       return (hShots === aShots) && (match.score.homePenalties !== match.score.awayPenalties);
    }
    return false;
  }, [match]);

  const handlePointerDown = (team: 'home' | 'away') => {
    // Only allow press if can timeout OR can cancel
    if (team === 'home' && !homeCanTimeout && !homeCanCancel) return;
    if (team === 'away' && !awayCanTimeout && !awayCanCancel) return;

    isLongPress.current = false;
    setPressing(team);
    const timer = setTimeout(() => {
      onCancelTimeout(team);
      isLongPress.current = true;
      setPressing(null);
    }, 800);
    if (team === 'home') timerRefHome.current = timer;
    else timerRefAway.current = timer;
  };

  const handlePointerUp = (team: 'home' | 'away') => {
    setPressing(null);
    if (team === 'home') { if (timerRefHome.current) clearTimeout(timerRefHome.current); } 
    else { if (timerRefAway.current) clearTimeout(timerRefAway.current); }

    if (!isLongPress.current) {
        if (team === 'home' && homeCanTimeout) onTimeout('home');
        if (team === 'away' && awayCanTimeout) onTimeout('away');
    }
  };

  const renderTimeoutDots = (used: number, thisHalf: number, team: 'home' | 'away') => (
    <div className={`flex gap-1.5 items-center justify-center bg-gray-100 dark:bg-slate-800 rounded-lg px-2 py-1 h-8 shadow-inner`}>
      {[1, 2, 3].map(i => (
        <div 
          key={i} 
          className={`w-3 h-3 rounded-full border-2 transition-all ${i <= used ? (team === 'home' ? 'bg-red-500 border-red-600' : 'bg-blue-500 border-blue-600') : 'bg-transparent border-slate-300 dark:border-slate-600'}`}
        />
      ))}
    </div>
  );

  return (
    <div className={`flex flex-col w-full rounded-[2.5rem] p-4 shadow-xl border relative overflow-hidden transition-colors duration-300 ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>

      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-slate-50 to-transparent dark:from-slate-800/50 pointer-events-none opacity-50" />

      {/* SUSPENSION ALERTS (Ending Soon) */}
      {endingSuspensions.length > 0 && (
         <div className="absolute top-0 left-0 w-full z-50 flex justify-center gap-2 p-1 bg-transparent pointer-events-none">
            {endingSuspensions.map((item, idx) => (
                <div key={`${item.side}-${item.number}-${idx}`} className="animate-pulse bg-amber-400 text-black font-black px-4 py-1.5 rounded-b-xl shadow-lg border-x-2 border-b-2 border-amber-600 flex items-center gap-2 pointer-events-auto transform transition-transform hover:scale-105">
                   <div className="flex flex-col items-center leading-none">
                       <span className="text-[8px] uppercase">دخول</span>
                       <Timer size={10} />
                   </div>
                   <span className="text-xl bg-white px-1.5 rounded-md border border-black min-w-[30px] text-center" style={{ color: item.color }}>{item.number}</span>
                   <span className="font-mono text-sm bg-black text-white px-1.5 rounded py-0.5">{item.remaining}s</span>
                </div>
            ))}
         </div>
      )}

      {/* 1. Period Header */}
      <div className="relative z-10 flex items-center justify-center gap-6 mb-4 mt-2">
          {onPeriodChange && (
            <button onClick={() => onPeriodChange('prev')} className={`p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${isDarkMode ? 'text-slate-400' : 'text-slate-500'}`}>
              <ChevronRight size={24} strokeWidth={3} />
            </button>
          )}
          <div className={`text-base sm:text-lg font-black uppercase tracking-wider ${match.period === MatchPeriod.PENALTIES ? 'text-purple-600' : (isDarkMode ? 'text-slate-200' : 'text-slate-700')}`}>
             {match.period}
          </div>
          {onPeriodChange && (
            <button onClick={() => onPeriodChange('next')} className={`p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${isDarkMode ? 'text-slate-400' : 'text-slate-500'}`}>
              <ChevronLeft size={24} strokeWidth={3} />
            </button>
          )}
      </div>

      {/* 2. Main Score Area */}
      <div className="flex items-start justify-between relative z-10 px-2 sm:px-6">

        {/* RIGHT SIDE (HOME TEAM in RTL) */}
        <div className="flex flex-col items-center gap-3 flex-1">
           <h3 className="font-black text-sm sm:text-lg truncate max-w-[120px] text-center" style={{ color: match.homeTeam.color }}>
             {match.homeTeam.name}
           </h3>

           <div 
             className="w-20 h-20 sm:w-28 sm:h-28 rounded-[2rem] flex items-center justify-center shadow-2xl transition-transform transform hover:scale-105"
             style={{ backgroundColor: match.homeTeam.color }}
           >
             <span className="text-5xl sm:text-6xl font-black text-white drop-shadow-md">
               {match.score.home}
             </span>
           </div>

           {/* Timeout Controls Home */}
           <div className="flex flex-col gap-1 mt-1 w-full max-w-[120px]">
              <button 
                disabled={(!homeCanTimeout && !homeCanCancel) || isBreak || match.isFinished}
                onPointerDown={() => handlePointerDown('home')}
                onPointerUp={() => handlePointerUp('home')}
                onPointerLeave={() => { if(timerRefHome.current) clearTimeout(timerRefHome.current); setPressing(null); }}
                className={`w-full py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm transition-all border
                   ${(!homeCanTimeout && !homeCanCancel) || isBreak || match.isFinished 
                      ? 'bg-slate-100 text-slate-400 border-slate-200 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-600 cursor-not-allowed' 
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-200 dark:border-slate-700'}
                   ${pressing === 'home' ? 'scale-95 bg-red-50 border-red-200 text-red-500' : ''}
                `}
              >
                {pressing === 'home' ? 'إلغاء...' : 'TIME-OUT'}
              </button>
              {renderTimeoutDots(match.homeTeam.timeoutsUsed, match.homeTeam.timeoutsThisHalf, 'home')}
           </div>
        </div>

        {/* CENTER (TIMER) */}
        <div className="flex flex-col items-center justify-start pt-2 mx-2 sm:mx-4">
            <div className={`relative w-36 h-32 sm:w-44 sm:h-36 bg-slate-950 rounded-[2.5rem] flex flex-col items-center justify-center shadow-2xl border-4 ${match.isActive ? 'border-green-500/30' : 'border-slate-800'}`}>
                {/* Timer Text */}
                <div className={`text-4xl sm:text-5xl font-mono font-black tracking-wider mb-2 ${match.isFinished ? 'text-red-500' : isBreak ? 'text-green-400' : 'text-white'}`}>
                    {match.isFinished ? "00:00" : formatTime(match.timer)}
                </div>

                {/* Play/Pause Button Floating */}
                <button 
                  onClick={onToggleTimer}
                  disabled={match.isFinished}
                  className={`absolute -bottom-5 w-14 h-14 rounded-full flex items-center justify-center shadow-lg border-4 border-white dark:border-slate-900 transition-transform active:scale-90 
                    ${match.isFinished ? 'bg-slate-700 cursor-not-allowed' : match.isActive ? 'bg-red-500 hover:bg-red-600' : 'bg-blue-600 hover:bg-blue-500'}`}
                >
                  {match.isFinished ? <Flag size={20} className="text-white" /> : match.isActive ? <Pause size={24} fill="white" className="text-white" /> : <Play size={24} fill="white" className="ml-1 text-white" />}
                </button>
            </div>

            {/* Timeout Overlay Display */}
            {timeoutTimer !== null && (
               <div className="mt-8 bg-red-600 text-white px-4 py-1 rounded-full text-xs font-black animate-pulse shadow-lg">
                  T.O: {timeoutTimer}s
               </div>
            )}

            {/* Finish Button below timer */}
            {canFinishMatch && (
                <button 
                    onClick={onFinishMatch}
                    className="mt-8 flex items-center gap-1.5 px-4 py-1.5 bg-black text-white text-[10px] font-black rounded-full shadow-lg hover:bg-slate-800 transition-all animate-in zoom-in"
                >
                    <Flag size={12} />
                    <span>إنهاء</span>
                </button>
            )}
             {match.isFinished && (
                <div className="mt-8 text-[10px] font-black text-red-500 bg-red-500/10 px-3 py-1 rounded-full">
                    منتهية
                </div>
            )}
        </div>

        {/* LEFT SIDE (AWAY TEAM in RTL) */}
        <div className="flex flex-col items-center gap-3 flex-1">
           <h3 className="font-black text-sm sm:text-lg truncate max-w-[120px] text-center" style={{ color: match.awayTeam.color }}>
             {match.awayTeam.name}
           </h3>

           <div 
             className="w-20 h-20 sm:w-28 sm:h-28 rounded-[2rem] flex items-center justify-center shadow-2xl transition-transform transform hover:scale-105"
             style={{ backgroundColor: match.awayTeam.color }}
           >
             <span className="text-5xl sm:text-6xl font-black text-white drop-shadow-md">
               {match.score.away}
             </span>
           </div>

           {/* Timeout Controls Away */}
           <div className="flex flex-col gap-1 mt-1 w-full max-w-[120px]">
              <button 
                disabled={(!awayCanTimeout && !awayCanCancel) || isBreak || match.isFinished}
                onPointerDown={() => handlePointerDown('away')}
                onPointerUp={() => handlePointerUp('away')}
                onPointerLeave={() => { if(timerRefAway.current) clearTimeout(timerRefAway.current); setPressing(null); }}
                className={`w-full py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm transition-all border
                   ${(!awayCanTimeout && !awayCanCancel) || isBreak || match.isFinished 
                      ? 'bg-slate-100 text-slate-400 border-slate-200 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-600 cursor-not-allowed' 
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-200 dark:border-slate-700'}
                   ${pressing === 'away' ? 'scale-95 bg-red-50 border-red-200 text-red-500' : ''}
                `}
              >
                {pressing === 'away' ? 'إلغاء...' : 'TIME-OUT'}
              </button>
              {renderTimeoutDots(match.awayTeam.timeoutsUsed, match.awayTeam.timeoutsThisHalf, 'away')}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Team, SanctionType, Player } from '../types.ts';
import { Trash2, X, Save, AlertCircle, UserPlus, Shield, Crown, Edit2 } from 'lucide-react';

interface TeamControlProps {
  team: Team;
  side: 'home' | 'away';
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onSelect: (target: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string }) => void;
  isDarkMode: boolean;
  onUpdatePlayer: (side: 'home' | 'away', id: string, data: Partial<Player>) => void;
  onDeletePlayer: (side: 'home' | 'away', id: string) => void;
  onAddPlayer: (side: 'home' | 'away', number: string, name: string) => void;
  onUpdateStaff?: (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => void;
}

export const TeamControl: React.FC<TeamControlProps> = ({ team, side, selectedTarget, onSelect, isDarkMode, onUpdatePlayer, onDeletePlayer, onAddPlayer, onUpdateStaff }) => {
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editName, setEditName] = useState('');
  const [editNumber, setEditNumber] = useState('');
  const [editLicence, setEditLicence] = useState('');
  const [editIsCaptain, setEditIsCaptain] = useState(false);
  const [editIsGoalkeeper, setEditIsGoalkeeper] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Staff Editing
  const [editingStaff, setEditingStaff] = useState<'coach' | 'assistant-coach' | null>(null);

  // New Player State
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newNumber, setNewNumber] = useState('');

  const isCoachSelected = selectedTarget?.type === 'coach' && selectedTarget.team === side;
  const isAssistantSelected = selectedTarget?.type === 'assistant-coach' && selectedTarget.team === side;

  if (!team) return null;

  const handleDoubleClickPlayer = (p: Player) => {
    setEditingPlayer(p);
    setEditName(p.name);
    setEditNumber(p.number);
    setEditLicence(p.licence || '');
    setEditIsCaptain(p.isCaptain || false);
    setEditIsGoalkeeper(p.isGoalkeeper || false);
    setShowDeleteConfirm(false);
  };

  const handleDoubleClickStaff = (type: 'coach' | 'assistant-coach') => {
      setEditingStaff(type);
      setEditName(type === 'coach' ? team.coach.name : (team.assistantCoach?.name || ''));
  };

  const saveEdit = () => {
    if (editingPlayer) {
      // Check for duplicate number (excluding current player)
      const duplicate = team.players.some(p => p.number === editNumber && p.id !== editingPlayer.id);
      if (duplicate) {
          alert(`الرقم ${editNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onUpdatePlayer(side, editingPlayer.id, { 
          name: editName, 
          number: editNumber,
          licence: editLicence,
          isCaptain: editIsCaptain,
          isGoalkeeper: editIsGoalkeeper
      });
      setEditingPlayer(null);
    } else if (editingStaff && onUpdateStaff) {
        onUpdateStaff(side, editingStaff, editName);
        setEditingStaff(null);
    }
  };

  const handleAddSubmit = () => {
    if (newNumber.trim() && newName.trim()) {
      // Check for duplicate number
      const duplicate = team.players.some(p => p.number === newNumber);
      if (duplicate) {
          alert(`الرقم ${newNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onAddPlayer(side, newNumber, newName);
      setNewName('');
      setNewNumber('');
      setShowAddModal(false);
    }
  };

  const closeEdit = () => {
    setEditingPlayer(null);
    setEditingStaff(null);
    setShowDeleteConfirm(false);
  };

  return (
    <div className={`flex flex-col h-full max-h-[85vh] gap-2 p-2 sm:p-3 rounded-3xl border-2 transition-all ${selectedTarget?.team === side ? 'border-blue-500 shadow-xl' : isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="flex items-center justify-between mb-1 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-3 h-6 rounded-full shadow-inner" style={{ backgroundColor: team.color || '#ccc' }}></div>
          <h3 className="font-black text-sm sm:text-base uppercase tracking-tight truncate max-w-[100px] sm:max-w-none">{team.name || 'فريق'}</h3>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
          className={`p-1.5 rounded-lg transition-all hover:scale-110 active:scale-95 ${isDarkMode ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-600/30' : 'bg-blue-100 text-blue-600 hover:bg-blue-200'}`}
          title="إضافة لاعب جديد"
        >
          <UserPlus size={16} strokeWidth={3} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-player-scrollbar">
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 pb-2">
          {team.players?.map((p) => {
            const isSelected = selectedTarget?.type === 'player' && selectedTarget.id === p.id;
            const isRed = p.sanctions?.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
            const yellowSanc = p.sanctions?.filter(s => s.type === SanctionType.YELLOW) || [];
            const twoMinSancs = p.sanctions?.filter(s => s.type === SanctionType.TWO_MINUTES) || [];
            const active2Min = twoMinSancs.find(s => s.remainingTime && s.remainingTime > 0);

            // Check if suspension is ending soon (<= 20 seconds)
            const isEndingSoon = active2Min && active2Min.remainingTime! <= 20;

            return (
              <button
                key={p.id}
                onClick={() => onSelect({ type: 'player', team: side, id: p.id })}
                onDoubleClick={() => handleDoubleClickPlayer(p)}
                className={`
                  relative h-16 sm:h-20 rounded-2xl flex flex-col items-center justify-center transition-all duration-200 border-2 flex-shrink-0 select-none
                  ${isRed ? 'bg-red-950/20 border-red-900/50 grayscale opacity-70' : 
                    isSelected ? 'bg-blue-600 border-blue-400 scale-[1.02] shadow-xl text-white' : 
                    isEndingSoon ? 'ring-4 ring-amber-400 border-amber-500 bg-amber-50 dark:bg-amber-900/30 dark:text-amber-100 animate-pulse' :
                    isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500 text-slate-100' : 'bg-slate-50 border-slate-200 hover:border-blue-300 text-slate-800'}
                `}
              >
                <span className="text-xl sm:text-2xl font-black leading-none">{p.number}</span>
                <span className={`text-[8px] sm:text-[9px] font-bold truncate w-full px-1 text-center mt-0.5 ${isSelected ? 'text-blue-100' : isEndingSoon ? 'text-amber-600 dark:text-amber-300' : 'text-slate-500'}`}>{p.name}</span>

                {/* Role Indicators */}
                <div className="absolute top-1 right-1 flex flex-col gap-0.5">
                   {p.isCaptain && <Crown size={10} className="text-yellow-500 fill-yellow-500" />}
                   {p.isGoalkeeper && <Shield size={10} className="text-gray-400 fill-gray-400" />}
                </div>

                <div className="absolute top-1 left-1 flex flex-col gap-0.5">
                  {yellowSanc.map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm"></div>
                  ))}
                  {twoMinSancs.slice(0, 2).map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-slate-950 rounded-sm border border-slate-700 flex items-center justify-center text-[6px] sm:text-[7px] text-white font-black">
                        {/* Display duration or count */}
                        {active2Min && active2Min === twoMinSancs[i] ? '1' : ''}
                    </div>
                  ))}
                  {isRed && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-red-600 rounded-sm border border-red-800 shadow-sm"></div>
                  )}
                </div>

                {active2Min && (
                  <div className={`absolute -top-2 -right-1 text-[8px] px-1 py-0.5 rounded-full font-mono font-bold border animate-pulse z-10 ${isEndingSoon ? 'bg-amber-500 text-black border-amber-600 scale-125' : 'bg-black text-white border-slate-700'}`}>
                    {Math.floor(active2Min.remainingTime! / 60)}:{(active2Min.remainingTime! % 60).toString().padStart(2, '0')}
                  </div>
                )}

                {p.goals > 0 && (
                  <div className={`absolute -bottom-1 -left-1 w-5 h-5 sm:w-6 sm:h-6 rounded-full flex items-center justify-center text-[9px] sm:text-[11px] font-black shadow-lg border-2 ${isSelected ? 'bg-white text-blue-600 border-blue-100' : 'bg-green-600 text-white border-green-700'}`}>
                    {p.goals}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-1 pt-2 border-t space-y-2 flex-shrink-0">
          <button 
            onClick={() => onSelect({ type: 'coach', team: side })}
            onDoubleClick={() => handleDoubleClickStaff('coach')}
            className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isCoachSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
          >
            <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isCoachSelected ? 'text-blue-500' : 'text-slate-500'}`}>المؤطر: {team.coach?.name || '---'}</div>
            <div className="flex gap-1">
              {team.coach?.sanctions?.map((s, i) => (
                <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                    {/* Placeholder */}
                </div>
              ))}
            </div>
          </button>

          {team.assistantCoach && (
            <button 
                onClick={() => onSelect({ type: 'assistant-coach', team: side })}
                onDoubleClick={() => handleDoubleClickStaff('assistant-coach')}
                className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isAssistantSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
            >
