import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MatchState, MatchPeriod, SanctionType, Player, Officials, MatchDetails, Team, MatchEvent, ScheduledMatch, Staff } from './types.ts';
import { SetupForm } from './components/SetupForm.tsx';
import { SetupChoice } from './components/SetupChoice.tsx';
import { ScoreBoard } from './components/ScoreBoard.tsx';
import { TeamControl } from './components/TeamControl.tsx';
import { ActionPanel } from './components/ActionPanel.tsx';
import { MatchSheet } from './components/MatchSheet.tsx';
import { ArchiveList } from './components/ArchiveList.tsx';
import { PenaltyShootout } from './components/PenaltyShootout.tsx';
import { ScheduleManager } from './components/ScheduleManager.tsx';
import { Trophy, ClipboardList, Plus, Play, History, Sun, Moon, FileText, X, ChevronRight, ChevronLeft, Zap, CloudCheck, CloudOff, Loader2, RefreshCw, Database, Settings as SettingsIcon, Lock, Link as LinkIcon, ExternalLink, AlertTriangle, Coins, Edit2, Menu, Info } from 'lucide-react';

const generateId = () => Math.random().toString(36).substring(2, 15) + Date.now().toString(36);

const sortPlayersByNumber = (players: Player[]): Player[] => {
  return [...players].sort((a, b) => {
    const numA = parseInt(a.number, 10) || 0;
    const numB = parseInt(b.number, 10) || 0;
    return numA - numB;
  });
};

const formatMMSS = (seconds: number) => {
  if (typeof seconds !== 'number' || isNaN(seconds)) return "00:00";
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

const PERIOD_ORDER = [
  MatchPeriod.FIRST_HALF,
  MatchPeriod.SECOND_HALF,
  MatchPeriod.OT1_H1,
  MatchPeriod.OT1_H2,
  MatchPeriod.OT2_H1,
  MatchPeriod.OT2_H2,
  MatchPeriod.PENALTIES
];

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'setup_choice' | 'match' | 'sheet' | 'archive' | 'admin_schedule'>('setup_choice');
  const [match, setMatch] = useState<MatchState | null>(null);
  const [history, setHistory] = useState<MatchState[]>([]); // Historique local de la session (undo/redo)

  // Archive State (Persistent LocalStorage)
  const [archive, setArchive] = useState<MatchState[]>(() => {
    try {
      const stored = localStorage.getItem('handball_archive');
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      console.error("Failed to load archive", e);
      return [];
    }
  });

  const [selectedTarget, setSelectedTarget] = useState<{ type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => window.matchMedia('(prefers-color-scheme: dark)').matches);
  const [timeoutTimer, setTimeoutTimer] = useState<number | null>(null);
  const [timerSpeed, setTimerSpeed] = useState(1);

  // New State for Schedule (Local Only)
  const [schedule, setSchedule] = useState<ScheduledMatch[]>([]);
  const [preSelectedScheduledMatch, setPreSelectedScheduledMatch] = useState<ScheduledMatch | null>(null);

  // Temporary state to hold data when going back to setup
  const [editSetupData, setEditSetupData] = useState<any>(null);

  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginPass, setLoginPass] = useState('');

  // Center Password Verification
  const [showCenterPasswordModal, setShowCenterPasswordModal] = useState(false);
  const [centerLoginPass, setCenterLoginPass] = useState('');
  const [pendingScheduledMatch, setPendingScheduledMatch] = useState<ScheduledMatch | null>(null);

  // Penalty Setup Modal
  const [showPenaltySetup, setShowPenaltySetup] = useState(false);
  const [penaltyConfig, setPenaltyConfig] = useState<{ shots: number, starter: 'home' | 'away' | null }>({ shots: 5, starter: null });

  // Menu State
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showAbout, setShowAbout] = useState(false);

  const matchRef = useRef<MatchState | null>(null);
  useEffect(() => { matchRef.current = match; }, [match]);

  // Persist Archive when it changes
  useEffect(() => {
    try {
      localStorage.setItem('handball_archive', JSON.stringify(archive));
    } catch (e) {
      console.error("Failed to save archive", e);
    }
  }, [archive]);

  // AUTO-SAVE MATCH STATE & RECOVERY
  useEffect(() => {
    // 1. Recover match on mount if exists
    const savedMatch = localStorage.getItem('current_active_match');
    if (savedMatch && !match) {
        try {
            const parsed = JSON.parse(savedMatch);
            // Only restore if we are in initial state
            setMatch(parsed);
            setView('match');
        } catch (e) {
            console.error("Failed to restore match", e);
        }
    }
  }, []);

  useEffect(() => {
    // 2. Save match on every update
    if (match) {
        localStorage.setItem('current_active_match', JSON.stringify(match));

        // Also update the archive entry in real-time if it exists there (to ensure "local archive" is up to date)
        setArchive(prev => {
             const index = prev.findIndex(m => m.id === match.id);
             if (index !== -1) {
                 const newArchive = [...prev];
                 newArchive[index] = match;
                 return newArchive;
             }
             return prev;
        });
    }
  }, [match]);

  const saveScheduleToLocal = (newSchedule: ScheduledMatch[]) => {
      setSchedule(newSchedule);
      // Optionnel : Sauvegarder dans localStorage si besoin
  };

  const deleteFromArchive = (id: string) => {
      setArchive(prev => prev.filter(m => m.id !== id));
      if (match?.id === id) {
          setMatch(null);
          localStorage.removeItem('current_active_match'); // Clear active if deleted
          setView('setup_choice');
      }
  };

  const handleFinishMatch = () => {
    if (!match) return;
    const finishedMatch = { ...match, isFinished: true, isActive: false };
    setMatch(finishedMatch);

    // Save to archive (update if exists, add if new)
    setArchive(prev => {
        const exists = prev.some(m => m.id === finishedMatch.id);
        if (exists) {
            return prev.map(m => m.id === finishedMatch.id ? finishedMatch : m);
        }
        return [finishedMatch, ...prev];
    });
    // We do NOT remove 'current_active_match' here so the user can still see the result if they refresh.
    // It will be overwritten when they start a new match.
  };

  const startMatch = (
    h: string, hc: string, hast: string, hplayers: any[], hcol: string,
    a: string, ac: string, aast: string, aplayers: any[], acol: string, 
    hd: number, od: number, suspensionDur: number, off: any, det: any
  ) => {
    const mapPlayers = (players: any[], prefix: string): Player[] => {
      const mapped = players.map((p, i) => ({ 
        id: `${prefix}-${generateId()}-${i}`, 
        number: p.number, 
        licence: p.licence || '',
        name: p.name, 
        goals: 0, 
        sanctions: [], 
        isCaptain: p.isCaptain || false, 
        isGoalkeeper: p.isGoalkeeper || false
      }));
      return sortPlayersByNumber(mapped);
    };

    // Initialize Assistant Coach as a Staff object
    const homeAssistant: Staff = { name: hast, sanctions: [] };
    const awayAssistant: Staff = { name: aast, sanctions: [] };

    const newMatch: MatchState = {
      id: generateId(), details: det,
      homeTeam: { 
        name: h, color: hcol, coach: { name: hc, sanctions: [] }, assistantCoach: homeAssistant,
        players: mapPlayers(hplayers, 'home'), timeoutsUsed: 0, timeoutsThisHalf: 0, reservations: ''
      },
      awayTeam: { 
        name: a, color: acol, coach: { name: ac, sanctions: [] }, assistantCoach: awayAssistant,
        players: mapPlayers(aplayers, 'away'), timeoutsUsed: 0, timeoutsThisHalf: 0, reservations: ''
      },
      officials: off, timer: 0, isActive: false, isFinished: false, period: MatchPeriod.FIRST_HALF, report: '',
      score: { 
        home: 0, away: 0, 
        homeP1: 0, awayP1: 0, 
        homeFullTime: undefined, awayFullTime: undefined,
        homeOT: undefined, awayOT: undefined,
        homeOT2: undefined, awayOT2: undefined,
        homePenalties: 0, awayPenalties: 0 
      },
      penaltySequence: { home: [], away: [], currentTurn: 'home' },
      config: { halfDuration: hd * 60, otDuration: od * 60, penaltyShots: 5, suspensionDuration: suspensionDur * 60 },
      events: [] 
    };
    setMatch(newMatch);
    setHistory([]);
    // Clear edit data after starting
    setEditSetupData(null);
    setPreSelectedScheduledMatch(null);
    setView('match');
  };

  const handleNewMatchChoice = (matchChoice?: ScheduledMatch) => {
    setEditSetupData(null); // Clear any previous edit data
    if (matchChoice) {
      if (matchChoice.centerPassword) {
        setPendingScheduledMatch(matchChoice);
        setCenterLoginPass('');
        setShowCenterPasswordModal(true);
      } else {
        setPreSelectedScheduledMatch(matchChoice);
        setView('setup');
      }
    } else {
      setPreSelectedScheduledMatch(null);
      setView('setup');
    }
  };

  const handleBackToSetup = () => {
      if (!match) return;

      const confirm = window.confirm("هل أنت متأكد من العودة للإعدادات؟\nستتمكن من تعديل أسماء اللاعبين وتفاصيل المباراة، وسيتم إعادة تشغيل العداد.");
      if (!confirm) return;

      // Construct data to pre-fill SetupForm from the CURRENT match state
      const data = {
          initialMatch: {
              id: match.id,
              homeTeam: match.homeTeam.name,
              awayTeam: match.awayTeam.name,
              category: match.details.categorie,
              lieu: match.details.lieu,
              date: match.details.date,
              time: match.details.time,
              officials: match.officials,
          },
          initialDetails: match.details,
          initialHomePlayers: match.homeTeam.players.map(p => ({
              number: p.number, name: p.name, licence: p.licence, isCaptain: p.isCaptain || false, isGoalkeeper: p.isGoalkeeper || false
          })),
          initialAwayPlayers: match.awayTeam.players.map(p => ({
              number: p.number, name: p.name, licence: p.licence, isCaptain: p.isCaptain || false, isGoalkeeper: p.isGoalkeeper || false
          })),
          initialHomeCoach: match.homeTeam.coach.name,
          initialAwayCoach: match.awayTeam.coach.name,
          initialHomeAst: match.homeTeam.assistantCoach?.name || '',
          initialAwayAst: match.awayTeam.assistantCoach?.name || '',
          initialHomeColor: match.homeTeam.color,
          initialAwayColor: match.awayTeam.color
      };

      setEditSetupData(data);
      setView('setup');
  };

  const handleCenterLogin = () => {
    if (pendingScheduledMatch && centerLoginPass === pendingScheduledMatch.centerPassword) {
      setPreSelectedScheduledMatch(pendingScheduledMatch);
      setShowCenterPasswordModal(false);
      setPendingScheduledMatch(null);
      setView('setup');
    } else {
      alert("القن السري للمركز غير صحيح");
    }
  };

  const handleLogin = () => {
    if (loginPass === '3lachbghitih@') {
      localStorage.setItem('admin_authenticated', 'true');
      setView('admin_schedule');
      setShowLoginModal(false);
      setLoginPass('');
    } else {
      alert("بيانات الدخول غير صحيحة");
    }
  };

  const handleSettingsClick = () => {
    if (localStorage.getItem('admin_authenticated') === 'true') {
      setView('admin_schedule');
    } else {
      setShowLoginModal(true);
    }
  };

  const handleAddPlayer = (side: 'home' | 'away', number: string, name: string) => {
    setMatch(prev => {
      if (!prev) return null;
      const newPlayer: Player = {
        id: `${side}-${generateId()}`,
        number,
        licence: '', // Default empty license for quick added players
        name,
        goals: 0,
        sanctions: [],
        isCaptain: false,
        isGoalkeeper: false
      };
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: sortPlayersByNumber([...prev[teamKey].players, newPlayer])
        }
      };
    });
  };

  const handleUpdatePlayer = (side: 'home' | 'away', id: string, data: Partial<Player>) => {
    setMatch(prev => {
      if (!prev) return null;
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      const updatedPlayers = prev[teamKey].players.map(p => 
        p.id === id ? { ...p, ...data } : p
      );
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: sortPlayersByNumber(updatedPlayers)
        }
      };
    });
  };

  // Function to update coach or assistant details directly from TeamControl
  const handleUpdateStaff = (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => {
    setMatch(prev => {
        if (!prev) return null;
        const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
        const team = { ...prev[teamKey] };
        if (type === 'coach') {
            team.coach = { ...team.coach, name: name };
        } else if (type === 'assistant-coach' && team.assistantCoach) {
            team.assistantCoach = { ...team.assistantCoach, name: name };
        }
        return { ...prev, [teamKey]: team };
    });
  };

  const handleDeletePlayer = (side: 'home' | 'away', id: string) => {
    setMatch(prev => {
      if (!prev) return null;
      const teamKey = side === 'home' ? 'homeTeam' : 'awayTeam';
      const updatedPlayers = prev[teamKey].players.filter(p => p.id !== id);
      return {
        ...prev,
        [teamKey]: {
          ...prev[teamKey],
          players: updatedPlayers
        }
      };
    });
  };

  const handleTimeout = (team: 'home' | 'away') => {
    if (!match) return;
    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev, isActive: false };
      const teamKey = team === 'home' ? 'homeTeam' : 'awayTeam';

      newMatch[teamKey] = {
        ...newMatch[teamKey],
        timeoutsUsed: newMatch[teamKey].timeoutsUsed + 1,
        timeoutsThisHalf: newMatch[teamKey].timeoutsThisHalf + 1
      };

      newMatch.events.unshift({
          id: generateId(),
          type: 'TIMEOUT',
          timestamp: prev.timer,
          timeStr: formatMMSS(prev.timer),
          team: team
      });

      return newMatch;
    });
    setTimeoutTimer(60);
  };

  const handleCancelTimeout = (team: 'home' | 'away') => {
    if (!match) return;
    setMatch(prev => {
        if (!prev) return null;
        const teamKey = team === 'home' ? 'homeTeam' : 'awayTeam';
        if (prev[teamKey].timeoutsUsed === 0) return prev;

        // Decrement counts
        const newTeam = { ...prev[teamKey] };
        newTeam.timeoutsUsed = Math.max(0, newTeam.timeoutsUsed - 1);
        if (newTeam.timeoutsThisHalf > 0) newTeam.timeoutsThisHalf -= 1;

        // Remove last timeout event for this team
        const newEvents = [...prev.events];
        const evtIdx = newEvents.findIndex(e => e.type === 'TIMEOUT' && e.team === team);
        if (evtIdx > -1) newEvents.splice(evtIdx, 1);

        return { ...prev, [teamKey]: newTeam, events: newEvents };
    });
    setTimeoutTimer(null); // Also cancel timer
  };

  const handlePeriodChange = (direction: 'next' | 'prev') => {
    setMatch(prev => {
      if (!prev) return null;
      const currentIndex = PERIOD_ORDER.indexOf(prev.period);
      let newIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;

      // Bounds check
      if (newIndex < 0) newIndex = 0;
      if (newIndex >= PERIOD_ORDER.length) newIndex = PERIOD_ORDER.length - 1;

      if (newIndex === currentIndex) return prev;

      const newPeriod = PERIOD_ORDER[newIndex];

      // RESET TIMEOUTS FOR THE NEW PERIOD if we are moving to a new half or OT
      let updateHome = { ...prev.homeTeam };
      let updateAway = { ...prev.awayTeam };
      let updatedScore = { ...prev.score };

      // SNAPSHOT HALFTIME SCORE
      if (prev.period === MatchPeriod.FIRST_HALF && newPeriod !== MatchPeriod.FIRST_HALF) {
          updatedScore.homeP1 = prev.score.home;
          updatedScore.awayP1 = prev.score.away;
      }

      // SNAPSHOT FULL TIME (60min) SCORE
      if (prev.period === MatchPeriod.SECOND_HALF && newPeriod !== MatchPeriod.SECOND_HALF && newPeriod !== MatchPeriod.FIRST_HALF) {
          updatedScore.homeFullTime = prev.score.home;
          updatedScore.awayFullTime = prev.score.away;
      }

      // SNAPSHOT OT SCORE (End of OT1 or OT2)
      if (prev.period === MatchPeriod.OT1_H2 && newPeriod !== MatchPeriod.OT1_H2 && newPeriod !== MatchPeriod.OT1_H1) {
           // Can snapshot here if needed
      }

      // SNAPSHOT OT2 SCORE (End of OT2)
      if (prev.period === MatchPeriod.OT2_H2 && newPeriod === MatchPeriod.PENALTIES) {
          updatedScore.homeOT = prev.score.home; // OT Score usually includes OT1 + OT2 total
          updatedScore.awayOT = prev.score.away;
          updatedScore.homeOT2 = prev.score.home; // Store specific end of OT2 score if distinct tracking needed
          updatedScore.awayOT2 = prev.score.away;
      }

      // Reset timeouts for new periods except between OT halves
      if (
          (prev.period === MatchPeriod.FIRST_HALF && newPeriod === MatchPeriod.SECOND_HALF) ||
          (prev.period === MatchPeriod.SECOND_HALF && newPeriod === MatchPeriod.OT1_H1) ||
          (prev.period === MatchPeriod.OT1_H2 && newPeriod === MatchPeriod.OT2_H1)
      ) {
          updateHome.timeoutsThisHalf = 0;
          updateAway.timeoutsThisHalf = 0;
      }

      return {
          ...prev,
          period: newPeriod,
          isActive: false, 
          homeTeam: updateHome,
          awayTeam: updateAway,
          score: updatedScore
      };
    });
  };

  // Wrapper for period change to intercept Penalties
  const onPeriodChangeRequest = (direction: 'next' | 'prev') => {
      if (!match) return;

      const currentIndex = PERIOD_ORDER.indexOf(match.period);
      let newIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;
      if (newIndex >= 0 && newIndex < PERIOD_ORDER.length) {
          const newPeriod = PERIOD_ORDER[newIndex];
          if (newPeriod === MatchPeriod.PENALTIES) {
              setPenaltyConfig({ shots: 5, starter: null });
              setShowPenaltySetup(true);
              return; // Stop here, modal will handle the rest
          }
      }
      handlePeriodChange(direction);
  };

  const confirmPenaltySetup = () => {
      if (!match || !penaltyConfig.starter) return;

      setMatch(prev => {
          if (!prev) return null;
          // Apply standard period change logic + penalty config
          let updatedScore = { ...prev.score };

          // Assuming we came from OT2 or 2nd Half or OT1
          if (prev.period !== MatchPeriod.FIRST_HALF && prev.period !== MatchPeriod.PENALTIES) {
             // If we are coming from overtime, snapshot that
             if (prev.period === MatchPeriod.OT1_H2 || prev.period === MatchPeriod.OT2_H2) {
                 updatedScore.homeOT = prev.score.home;
                 updatedScore.awayOT = prev.score.away;
                 if (prev.period === MatchPeriod.OT2_H2) {
                      updatedScore.homeOT2 = prev.score.home;
                      updatedScore.awayOT2 = prev.score.away;
                 }
             } else if (prev.period === MatchPeriod.SECOND_HALF) {
                 updatedScore.homeFullTime = prev.score.home;
                 updatedScore.awayFullTime = prev.score.away;
             }
          }

          return {
              ...prev,
              period: MatchPeriod.PENALTIES,
              isActive: false,
              score: updatedScore,
              penaltySequence: {
                  ...prev.penaltySequence,
                  currentTurn: penaltyConfig.starter!
              },
              config: {
                  ...prev.config,
                  penaltyShots: penaltyConfig.shots
              }
          };
      });
      setShowPenaltySetup(false);
  };

  const handlePenaltyShot = (team: 'home' | 'away', playerId: string, isGoal: boolean) => {
    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev };

      // Update Penalty Sequence
      const shot = {
        playerId,
        playerName: newMatch[team === 'home' ? 'homeTeam' : 'awayTeam'].players.find(p => p.id === playerId)?.name || '',
        playerNumber: newMatch[team === 'home' ? 'homeTeam' : 'awayTeam'].players.find(p => p.id === playerId)?.number || '',
        goal: isGoal
      };

      newMatch.penaltySequence = {
        ...newMatch.penaltySequence,
        [team]: [...newMatch.penaltySequence[team], shot],
        currentTurn: team === 'home' ? 'away' : 'home' // Toggle Turn
      };

      // Update Score if Goal
      if (isGoal) {
        if (team === 'home') newMatch.score.homePenalties += 1;
        else newMatch.score.awayPenalties += 1;
      }

      return newMatch;
    });
  };

  const handleAction = useCallback((type: 'goal' | '7m' | SanctionType, inc: boolean = true) => {
    if (!match || !selectedTarget) return;

    // Direct Blue Card Application (No modal here anymore, handled in sheet)
    // Blue card handling logic remains the same inside setMatch

    setMatch(prev => {
      if (!prev) return null;
      const newMatch = { ...prev };
      const teamSide = selectedTarget.team;
      const teamKey = teamSide === 'home' ? 'homeTeam' : 'awayTeam';
      const team = { ...newMatch[teamKey] };
      const eventTime = newMatch.timer;

      // Prevent adding goal if match is not active (Timer stopped)
      // Allow 'inc = false' to enable undo/correction even if timer is stopped
      if ((type === 'goal' || type === '7m') && inc && !newMatch.isActive) {
          return prev;
      }

      if (selectedTarget.type === 'player' && selectedTarget.id) {
         const pIdx = team.players.findIndex(p => p.id === selectedTarget.id);
         if (pIdx === -1) return prev;

         const player = { ...team.players[pIdx] };

         // Check if player is disqualified (Red or Blue)
         // Only allow interaction if we are "undoing" (inc === false) the specific sanction they have.
         const isDisqualified = player.sanctions.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
         if (inc && isDisqualified) {
           return prev;
         }

         if (type === 'goal' || type === '7m') {
             if (inc) {
                 player.goals += 1;
                 newMatch.score[teamSide === 'home' ? 'home' : 'away'] += 1;

                 newMatch.events.unshift({
                    id: generateId(),
                    type: 'GOAL',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: player.id,
                    playerName: player.name,
                    goalType: type === '7m' ? '7M' : 'NORMAL'
                 });
             } else {
                 if (player.goals > 0) {
                     player.goals -= 1;
                     newMatch.score[teamSide === 'home' ? 'home' : 'away'] -= 1;
                     const evtIdx = newMatch.events.findIndex(e => e.type === 'GOAL' && e.playerId === player.id);
                     if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                 }
             }
         } else {
             if (inc) {
                 if (type === SanctionType.YELLOW) {
                     if (player.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                     const teamYellowCount = team.players.reduce((acc, p) => acc + p.sanctions.filter(s => s.type === SanctionType.YELLOW).length, 0);
                     if (teamYellowCount >= 3) return prev;
                 }

                 const s: any = { type, timestamp: eventTime };
                 // USE CONFIGURABLE SUSPENSION DURATION
                 if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                 player.sanctions = [...player.sanctions, s];

                 newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: player.id,
                    playerName: player.name,
                    sanctionType: type as SanctionType // Store exact enum value
                 });

                 // AUTOMATIC RED CARD FOR 3rd SUSPENSION
                 if (type === SanctionType.TWO_MINUTES) {
                     const twoMinCount = player.sanctions.filter(s => s.type === SanctionType.TWO_MINUTES).length;
                     if (twoMinCount === 3) {
                         // Add Red Card automatically
                         player.sanctions.push({ type: SanctionType.RED, timestamp: eventTime });
                         // Add Red Card Event
                         newMatch.events.unshift({
                            id: generateId(),
                            type: 'SANCTION',
                            timestamp: eventTime,
                            timeStr: formatMMSS(eventTime),
                            team: teamSide,
                            playerId: player.id,
                            playerName: player.name,
                            sanctionType: SanctionType.RED
                         });
                     }
                 }

             } else {
                 const sIdx = player.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                 if (sIdx > -1) {
                     const newSanctions = [...player.sanctions];
                     newSanctions.splice(sIdx, 1);
                     player.sanctions = newSanctions;
                     const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === player.id && e.sanctionType === type);
                     if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                 }
             }
         }
         team.players = [...team.players];
         team.players[pIdx] = player;
      } 
      else if (selectedTarget.type === 'coach') {
          if (type !== 'goal' && type !== '7m') {
              if (inc) {
                  if (type === SanctionType.YELLOW) {
                      if (team.coach.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                  }
                  const s: any = { type: type as SanctionType, timestamp: eventTime };
                  // USE CONFIGURABLE SUSPENSION DURATION
                  if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                  team.coach = { ...team.coach, sanctions: [...team.coach.sanctions, s] };
                  newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: 'COACH',
                    playerName: team.coach.name,
                    sanctionType: type as SanctionType
                 });
              } else {
                  const sIdx = team.coach.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                  if (sIdx > -1) {
                      const newSanctions = [...team.coach.sanctions];
                      newSanctions.splice(sIdx, 1);
                      team.coach = { ...team.coach, sanctions: newSanctions };
                      const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === 'COACH' && e.team === teamSide && e.sanctionType === type);
                      if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                  }
              }
          }
      }
      else if (selectedTarget.type === 'assistant-coach' && team.assistantCoach) {
          if (type !== 'goal' && type !== '7m') {
              if (inc) {
                  if (type === SanctionType.YELLOW) {
                      if (team.assistantCoach.sanctions.some(s => s.type === SanctionType.YELLOW)) return prev;
                  }
                  const s: any = { type: type as SanctionType, timestamp: eventTime };
                  // USE CONFIGURABLE SUSPENSION DURATION
                  if (type === SanctionType.TWO_MINUTES) s.remainingTime = prev.config.suspensionDuration;
                  team.assistantCoach = { ...team.assistantCoach, sanctions: [...team.assistantCoach.sanctions, s] };
                  newMatch.events.unshift({
                    id: generateId(),
                    type: 'SANCTION',
                    timestamp: eventTime,
                    timeStr: formatMMSS(eventTime),
                    team: teamSide,
                    playerId: 'ASSISTANT_COACH',
                    playerName: team.assistantCoach.name,
                    sanctionType: type as SanctionType
                 });
              } else {
                  const sIdx = team.assistantCoach.sanctions.map(s => s.type).lastIndexOf(type as SanctionType);
                  if (sIdx > -1) {
                      const newSanctions = [...team.assistantCoach.sanctions];
                      newSanctions.splice(sIdx, 1);
                      team.assistantCoach = { ...team.assistantCoach, sanctions: newSanctions };
                      const evtIdx = newMatch.events.findIndex(e => e.type === 'SANCTION' && e.playerId === 'ASSISTANT_COACH' && e.team === teamSide && e.sanctionType === type);
                      if (evtIdx > -1) newMatch.events.splice(evtIdx, 1);
                  }
              }
          }
      }

      newMatch[teamKey] = team;
      return newMatch;
    });
  }, [match, selectedTarget]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (match?.isActive) {
        setMatch(prev => {
          if (!prev) return null;
          let nextTimer = prev.timer + 1;
          let nextActive = true;
          const { halfDuration, otDuration } = prev.config;

          if (prev.period === MatchPeriod.FIRST_HALF && nextTimer >= halfDuration) nextActive = false;
          else if (prev.period === MatchPeriod.SECOND_HALF && nextTimer >= halfDuration * 2) nextActive = false;

          // OT1 
          else if (prev.period === MatchPeriod.OT1_H1 && nextTimer >= (halfDuration * 2) + otDuration) nextActive = false;
          else if (prev.period === MatchPeriod.OT1_H2 && nextTimer >= (halfDuration * 2) + (otDuration * 2)) nextActive = false;

          // OT2
          else if (prev.period === MatchPeriod.OT2_H1 && nextTimer >= (halfDuration * 2) + (otDuration * 2) + otDuration) nextActive = false;
          else if (prev.period === MatchPeriod.OT2_H2 && nextTimer >= (halfDuration * 2) + (otDuration * 2) + (otDuration * 2)) nextActive = false;

          const updateS = (t: Team) => ({
            ...t, 
            players: t.players.map(p => {
                // Find the first active 2-minute suspension.
                // Logic: 2-minute suspensions must be served sequentially.
                // We find the first one that has remainingTime > 0 and decrement it.
                // Subsequent ones will wait until the first is done.
                const firstActiveIndex = p.sanctions.findIndex(s => s.type === SanctionType.TWO_MINUTES && s.remainingTime !== undefined && s.remainingTime > 0);

                if (firstActiveIndex === -1) return p;

                return {
                    ...p,
                    sanctions: p.sanctions.map((s, idx) => {
                        if (idx === firstActiveIndex && s.remainingTime) {
                            return { ...s, remainingTime: s.remainingTime - 1 };
                        }
                        return s;
                    })
                };
            }),
            coach: { ...t.coach, sanctions: t.coach.sanctions.map(s => (s.type === SanctionType.TWO_MINUTES && s.remainingTime && s.remainingTime > 0) ? { ...s, remainingTime: s.remainingTime - 1 } : s) },
            assistantCoach: t.assistantCoach ? { ...t.assistantCoach, sanctions: t.assistantCoach.sanctions.map(s => (s.type === SanctionType.TWO_MINUTES && s.remainingTime && s.remainingTime > 0) ? { ...s, remainingTime: s.remainingTime - 1 } : s) } : undefined
          });

          return { ...prev, timer: nextTimer, isActive: nextActive, homeTeam: updateS(prev.homeTeam), awayTeam: updateS(prev.awayTeam) };
        });
      }
      if (timeoutTimer !== null) { if (timeoutTimer > 0) setTimeoutTimer(p => p !== null ? p - 1 : null); else setTimeoutTimer(null); }
    }, 1000 / timerSpeed);
    return () => clearInterval(timer);
  }, [match?.isActive, timeoutTimer, timerSpeed]);

  return (
    <div className={`min-h-screen flex flex-col font-sans transition-colors duration-300 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`} dir="rtl">
      <header className={`${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-b p-3 sticky top-0 z-[110] flex justify-between items-center shadow-md relative`}>
        {/* Right: Menu (in RTL, first item is right) */}
        <div className="relative z-[120]">
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)} 
              className={`p-2 rounded-xl transition-colors ${isMenuOpen ? 'bg-slate-200 dark:bg-slate-800' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
              <Menu size={24} className={isDarkMode ? 'text-white' : 'text-slate-900'} />
            </button>

            {isMenuOpen && (
              <div className="absolute right-0 top-full mt-2 w-64 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-800 z-[200] overflow-hidden animate-in fade-in slide-in-from-top-2">
                  <div className="p-2 space-y-1">
                      {/* Match Controls if Active */}
                      {match && (
                          <>
                              <button onClick={() => { setView('match'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm text-blue-500">
                                  <Play size={18} /> متابعة المباراة
                              </button>
                              <button onClick={() => { setView('sheet'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm text-green-500">
                                  <ClipboardList size={18} /> ورقة المباراة
                              </button>
                              <div className="h-px bg-slate-200 dark:bg-slate-800 my-1" />
                          </>
                      )}

                      {/* Global Controls */}
                      <button onClick={() => { setView('setup_choice'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <Plus size={18} /> مباراة جديدة
                      </button>
                      <button onClick={() => { setView('archive'); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <History size={18} /> الأرشيف
                      </button>
                      <button onClick={() => { handleSettingsClick(); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <SettingsIcon size={18} /> إعدادات البرنامج
                      </button>

                       <div className="h-px bg-slate-200 dark:bg-slate-800 my-1" />

                       {/* Toggles */}
                       <button onClick={() => setTimerSpeed(prev => prev === 1 ? 10 : 1)} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <Zap size={18} className={timerSpeed > 1 ? 'text-amber-500' : ''} /> سرعة العداد: {timerSpeed}x
                      </button>
                      <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          {isDarkMode ? <Sun size={18} /> : <Moon size={18} />} {isDarkMode ? 'الوضع النهاري' : 'الوضع الليلي'}
                      </button>

                       <div className="h-px bg-slate-200 dark:bg-slate-800 my-1" />

                       <button onClick={() => { setShowAbout(true); setIsMenuOpen(false); }} className="w-full text-right flex items-center gap-3 p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors font-bold text-sm">
                          <Info size={18} /> حول التطبيق
                      </button>
                  </div>
              </div>
            )}
        </div>

        {/* Center: Title */}
        <div className="absolute left-1/2 -translate-x-1/2 flex items-center gap-2 cursor-pointer pointer-events-none sm:pointer-events-auto" onClick={() => setView('setup_choice')}>
          <Trophy className="text-blue-500" size={24} />
          <h1 className="text-sm font-black uppercase tracking-tighter hidden sm:block">HandManager PRO</h1>
        </div>

        {/* Left: Logo (in RTL, last item is left) */}
        <div className="flex items-center">
             <img src="https://tibuafrica.org/wp-content/uploads/2023/07/FRMSS.png" alt="FRMSS" className="h-10 w-auto object-contain" />
        </div>
      </header>

      <main className="flex-1 flex flex-col overflow-hidden">
        {view === 'setup_choice' && <div className="p-4 max-w-2xl mx-auto w-full h-full overflow-y-auto"><SetupChoice schedule={schedule} onChoice={handleNewMatchChoice} isDarkMode={isDarkMode} /></div>}
        {view === 'setup' && <div className="p-4 max-w-lg mx-auto w-full overflow-y-auto h-full">
            <SetupForm 
                key={editSetupData ? 'edit' : 'new'} 
                onStart={startMatch} 
                isDarkMode={isDarkMode} 
                schedule={schedule} 
                initialMatch={editSetupData ? editSetupData.initialMatch : preSelectedScheduledMatch}
                initialDetails={editSetupData?.initialDetails}
                initialHomePlayers={editSetupData?.initialHomePlayers}
                initialAwayPlayers={editSetupData?.initialAwayPlayers}
                initialHomeCoach={editSetupData?.initialHomeCoach}
                initialAwayCoach={editSetupData?.initialAwayCoach}
                initialHomeAst={editSetupData?.initialHomeAst}
                initialAwayAst={editSetupData?.initialAwayAst}
                initialHomeColor={editSetupData?.initialHomeColor}
                initialAwayColor={editSetupData?.initialAwayColor}
            />
        </div>}
        {view === 'admin_schedule' && <div className="p-4 max-w-4xl mx-auto w-full h-full overflow-hidden"><ScheduleManager schedule={schedule} onSave={saveScheduleToLocal} onClose={() => setView('setup_choice')} isDarkMode={isDarkMode} /></div>}
        {view === 'match' && match && <div className="flex flex-col h-full relative overflow-hidden">
            <div className={`flex-shrink-0 z-[100] border-b shadow-xl ${isDarkMode ? 'bg-slate-900/95 border-slate-800' : 'bg-white/95 border-slate-200'} backdrop-blur-md`}>
              <div className="p-2 max-w-7xl mx-auto flex flex-col gap-2">
                <ScoreBoard 
                    match={match} 
                    onToggleTimer={() => setMatch(m => m ? {...m, isActive: !m.isActive} : null)} 
                    onTimeout={handleTimeout} 
                    onCancelTimeout={handleCancelTimeout} 
                    onFinishMatch={handleFinishMatch} 
                    onPeriodChange={onPeriodChangeRequest}
                    timeoutTimer={timeoutTimer} 
                    breakTimer={null} 
                    isDarkMode={isDarkMode} 
                />
                {match.period !== MatchPeriod.PENALTIES && (
                   <ActionPanel 
                       match={match} 
                       selectedTarget={selectedTarget} 
                       onAction={handleAction} 
                       onUndo={() => {}} 
                       hasHistory={history.length > 0} 
                       isDarkMode={isDarkMode} 
                       matchActive={match.isActive} 
                       isTimeoutActive={timeoutTimer !== null} 
                       playerSuspended={false} 
                       suspensionDuration={match.config.suspensionDuration}
                   />
                )}
              </div>
            </div>
            <div className="flex-1 overflow-hidden p-2 sm:p-4 relative">
              {match.period === MatchPeriod.PENALTIES ? (
                <PenaltyShootout match={match} onShot={handlePenaltyShot} isDarkMode={isDarkMode} />
              ) : (
                <div className={`w-full grid grid-cols-2 gap-2 sm:gap-4 h-full`}>
                    {/* SWAPPED ORDER FOR VISUAL ALIGNMENT WITH SCOREBOARD IN RTL */}
                    <TeamControl team={match.homeTeam} side="home" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                    <TeamControl team={match.awayTeam} side="away" selectedTarget={selectedTarget} onSelect={setSelectedTarget} isDarkMode={isDarkMode} onUpdatePlayer={handleUpdatePlayer} onDeletePlayer={handleDeletePlayer} onAddPlayer={handleAddPlayer} onUpdateStaff={handleUpdateStaff} />
                </div>
              )}
            </div>
          </div>}
        {view === 'sheet' && match && <div className="p-4 h-full overflow-y-auto"><MatchSheet match={match} onUpdate={setMatch} /></div>}
        {view === 'archive' && <div className="p-4 h-full overflow-y-auto"><ArchiveList matches={archive} isDarkMode={isDarkMode} onSelect={(m) => { setMatch(m); setView('match'); }} onDelete={deleteFromArchive} /></div>}

        {/* Footer Credit */}
        <div className={`py-2 text-center text-[10px] font-bold ${isDarkMode ? 'bg-slate-900 text-slate-500 border-t border-slate-800' : 'bg-white text-slate-400 border-t border-slate-200'}`}>
           تمت برمجة وتطوير التطبيق من طرف السيد أمين سنوسي، والسيد عمر حماني. مديرية تاوريرت
        </div>
      </main>

      {/* Penalty Setup Modal */}
      {/* ... Penalty Setup Modal content ... */}
      {showPenaltySetup && match && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
           <div className={`w-full max-w-md rounded-[2.5rem] border-2 shadow-2xl p-6 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="text-center mb-6">
                 <div className="w-16 h-16 bg-purple-600 rounded-full flex items-center justify-center text-white mb-2 shadow-lg shadow-purple-600/30 mx-auto">
                    <Trophy size={32} />
                 </div>
                 <h3 className="text-xl font-black">إعداد رميات 7 أمتار</h3>
                 <p className="text-xs text-slate-500 font-bold mt-1">يجب تحديد عدد الرميات والقرعة قبل البدء</p>
              </div>

              {/* Number of Shots */}
              <div className="mb-6">
                  <label className="text-[10px] font-black text-slate-500 uppercase block mb-2 text-center">عدد الرميات (لكل فريق)</label>
                  <div className="flex items-center justify-center gap-4">
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: Math.max(1, prev.shots - 1) }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">-</button>
                      <div className="text-3xl font-black w-16 text-center">{penaltyConfig.shots}</div>
                      <button onClick={() => setPenaltyConfig(prev => ({ ...prev, shots: prev.shots + 1 }))} className="w-10 h-10 rounded-xl bg-slate-200 text-slate-700 font-black text-xl hover:bg-slate-300">+</button>
                  </div>
              </div>

              {/* Coin Toss / Starter Selection */}
              <div className="mb-8">
                   <label className="text-[10px] font-black text-slate-500 uppercase block mb-3 text-center flex items-center justify-center gap-1"><Coins size={12}/> القرعة: من سيبدأ الرمي؟</label>
                   <div className="grid grid-cols-2 gap-3">
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'home' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'home' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.homeTeam.color }} />
                           {match.homeTeam.name}
                       </button>
                       <button 
                           onClick={() => setPenaltyConfig(prev => ({ ...prev, starter: 'away' }))}
                           className={`p-3 rounded-xl border-2 transition-all font-black flex flex-col items-center gap-1 ${penaltyConfig.starter === 'away' ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' : (isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-slate-50 border-slate-200 text-slate-600')}`}
                       >
                           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: match.awayTeam.color }} />
                           {match.awayTeam.name}
                       </button>
                   </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                 <button onClick={confirmPenaltySetup} disabled={!penaltyConfig.starter} className="py-3 bg-purple-600 text-white font-black rounded-xl shadow-lg hover:bg-purple-500 disabled:opacity-50 transition-colors">بدء الرميات</button>
                 <button onClick={() => setShowPenaltySetup(false)} className={`py-3 font-black rounded-xl border-2 transition-colors ${isDarkMode ? 'border-slate-700 hover:bg-slate-800' : 'border-slate-200 hover:bg-slate-50'}`}>إلغاء</button>
              </div>
           </div>
        </div>
      )}

      {/* Admin Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => setShowLoginModal(false)} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-blue-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">الدخول للإعدادات</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">يرجى إدخال القن السري للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري</label><input type="password" autoFocus value={loginPass} onChange={e => setLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleLogin} className="w-full py-3 bg-blue-600 text-white font-black rounded-xl shadow-lg shadow-blue-600/20 hover:bg-blue-500 transition-colors mt-2">دخول</button>
            </div>
          </div>
        </div>
      )}

      {/* Center Password Verification Modal */}
      {showCenterPasswordModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-[2.5rem] border-2 shadow-2xl p-8 relative ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <button onClick={() => { setShowCenterPasswordModal(false); setPendingScheduledMatch(null); }} className="absolute top-4 right-4 p-2 hover:bg-slate-500/10 rounded-full text-slate-500"><X size={20} /></button>
            <div className="flex flex-col items-center mb-6">
               <div className="w-16 h-16 bg-amber-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-amber-600/30"><Lock size={32} /></div>
               <h3 className="text-xl font-black">تحقق من المركز</h3>
               <p className="text-xs text-slate-500 font-bold mt-1 text-center">المقابلة في: {pendingScheduledMatch?.lieu}</p>
               <p className="text-[10px] text-amber-500 font-bold mt-1">يرجى إدخال القن السري للمركز للمتابعة</p>
            </div>
            <div className="space-y-4">
               <div><label className="text-[10px] font-black text-slate-500 uppercase mb-1 block">القن السري للمركز</label><input type="password" autoFocus value={centerLoginPass} onChange={e => setCenterLoginPass(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleCenterLogin()} className={`w-full p-3 rounded-xl border-2 font-bold outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} placeholder="••••••••" /></div>
               <button onClick={handleCenterLogin} className="w-full py-3 bg-amber-600 text-white font-black rounded-xl shadow-lg shadow-amber-600/20 hover:bg-amber-500 transition-colors mt-2">تأكيد الدخول</button>
            </div>
          </div>
        </div>
      )}

      {/* About App Modal */}
      {showAbout && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200" onClick={() => setShowAbout(false)}>
           <div className={`w-full max-w-sm rounded-[2rem] p-6 shadow-2xl relative text-center ${isDarkMode ? 'bg-slate-900 border border-slate-800 text-white' : 'bg-white text-slate-900'}`} onClick={e => e.stopPropagation()}>
               <div className="w-20 h-20 bg-blue-600 rounded-3xl mx-auto flex items-center justify-center text-white shadow-xl shadow-blue-600/30 mb-4 rotate-3">
                   <Trophy size={40} strokeWidth={2.5} />
               </div>
               <h2 className="text-2xl font-black mb-1">HandManager PRO</h2>
               <p className="text-xs font-bold text-slate-500 mb-6 uppercase tracking-widest">الإصدار 5.0.0</p>

               <div className="space-y-4 text-sm font-bold leading-relaxed mb-6">
                   <p>تطبيق احترافي لإدارة مباريات كرة اليد، معتمد على القوانين الرسمية.</p>
                   <p className="text-xs text-slate-400">تم التطوير والبرمجة من طرف:</p>
                   <div className="flex flex-col gap-2">
                       <span className="bg-slate-100 dark:bg-slate-800 py-2 rounded-xl">أمين سنوسي</span>
                       <span className="bg-slate-100 dark:bg-slate-800 py-2 rounded-xl">عمر حماني</span>
                   </div>
                   <div className="my-2 p-3 bg-blue-50 dark:bg-slate-800/50 rounded-xl border border-blue-100 dark:border-slate-700">
                      <p className="text-xs text-blue-800 dark:text-blue-300">بتنسيق مع الحكم الوطني في رياضة كرة اليد السيد خالد محجوبي</p>
                   </div>
                   <p className="text-xs text-slate-400">مديرية تاوريرت</p>
               </div>

               <button onClick={() => setShowAbout(false)} className="w-full py-3 bg-slate-900 dark:bg-slate-700 text-white font-black rounded-xl hover:scale-105 transition-transform">
                   إغلاق
               </button>
           </div>
        </div>
      )}
    </div>
  );
};
export default App;

import React, { useState } from 'react';
import { Team, SanctionType, Player } from '../types.ts';
import { Trash2, X, Save, AlertCircle, UserPlus, Shield, Crown, Edit2 } from 'lucide-react';

interface TeamControlProps {
  team: Team;
  side: 'home' | 'away';
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onSelect: (target: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string }) => void;
  isDarkMode: boolean;
  onUpdatePlayer: (side: 'home' | 'away', id: string, data: Partial<Player>) => void;
  onDeletePlayer: (side: 'home' | 'away', id: string) => void;
  onAddPlayer: (side: 'home' | 'away', number: string, name: string) => void;
  onUpdateStaff?: (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => void;
}

export const TeamControl: React.FC<TeamControlProps> = ({ team, side, selectedTarget, onSelect, isDarkMode, onUpdatePlayer, onDeletePlayer, onAddPlayer, onUpdateStaff }) => {
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editName, setEditName] = useState('');
  const [editNumber, setEditNumber] = useState('');
  const [editLicence, setEditLicence] = useState('');
  const [editIsCaptain, setEditIsCaptain] = useState(false);
  const [editIsGoalkeeper, setEditIsGoalkeeper] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Staff Editing
  const [editingStaff, setEditingStaff] = useState<'coach' | 'assistant-coach' | null>(null);

  // New Player State
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newNumber, setNewNumber] = useState('');

  const isCoachSelected = selectedTarget?.type === 'coach' && selectedTarget.team === side;
  const isAssistantSelected = selectedTarget?.type === 'assistant-coach' && selectedTarget.team === side;

  if (!team) return null;

  const handleDoubleClickPlayer = (p: Player) => {
    setEditingPlayer(p);
    setEditName(p.name);
    setEditNumber(p.number);
    setEditLicence(p.licence || '');
    setEditIsCaptain(p.isCaptain || false);
    setEditIsGoalkeeper(p.isGoalkeeper || false);
    setShowDeleteConfirm(false);
  };

  const handleDoubleClickStaff = (type: 'coach' | 'assistant-coach') => {
      setEditingStaff(type);
      setEditName(type === 'coach' ? team.coach.name : (team.assistantCoach?.name || ''));
  };

  const saveEdit = () => {
    if (editingPlayer) {
      // Check for duplicate number (excluding current player)
      const duplicate = team.players.some(p => p.number === editNumber && p.id !== editingPlayer.id);
      if (duplicate) {
          alert(`الرقم ${editNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onUpdatePlayer(side, editingPlayer.id, { 
          name: editName, 
          number: editNumber,
          licence: editLicence,
          isCaptain: editIsCaptain,
          isGoalkeeper: editIsGoalkeeper
      });
      setEditingPlayer(null);
    } else if (editingStaff && onUpdateStaff) {
        onUpdateStaff(side, editingStaff, editName);
        setEditingStaff(null);
    }
  };

  const handleAddSubmit = () => {
    if (newNumber.trim() && newName.trim()) {
      // Check for duplicate number
      const duplicate = team.players.some(p => p.number === newNumber);
      if (duplicate) {
          alert(`الرقم ${newNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onAddPlayer(side, newNumber, newName);
      setNewName('');
      setNewNumber('');
      setShowAddModal(false);
    }
  };

  const closeEdit = () => {
    setEditingPlayer(null);
    setEditingStaff(null);
    setShowDeleteConfirm(false);
  };

  return (
    <div className={`flex flex-col h-full gap-2 p-2 sm:p-3 rounded-3xl border-2 transition-all ${selectedTarget?.team === side ? 'border-blue-500 shadow-xl' : isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="flex items-center justify-between mb-1 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-3 h-6 rounded-full shadow-inner" style={{ backgroundColor: team.color || '#ccc' }}></div>
          <h3 className="font-black text-sm sm:text-base uppercase tracking-tight truncate max-w-[100px] sm:max-w-none">{team.name || 'فريق'}</h3>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
          className={`p-1.5 rounded-lg transition-all hover:scale-110 active:scale-95 ${isDarkMode ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-600/30' : 'bg-blue-100 text-blue-600 hover:bg-blue-200'}`}
          title="إضافة لاعب جديد"
        >
          <UserPlus size={16} strokeWidth={3} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-player-scrollbar">
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 pb-2">
          {team.players?.map((p) => {
            const isSelected = selectedTarget?.type === 'player' && selectedTarget.id === p.id;
            const isRed = p.sanctions?.some(s => s.type === SanctionType.RED || s.type === SanctionType.BLUE);
            const yellowSanc = p.sanctions?.filter(s => s.type === SanctionType.YELLOW) || [];
            const twoMinSancs = p.sanctions?.filter(s => s.type === SanctionType.TWO_MINUTES) || [];
            const active2Min = twoMinSancs.find(s => s.remainingTime && s.remainingTime > 0);

            // Check if suspension is ending soon (<= 20 seconds)
            const isEndingSoon = active2Min && active2Min.remainingTime! <= 20;

            return (
              <button
                key={p.id}
                onClick={() => onSelect({ type: 'player', team: side, id: p.id })}
                onDoubleClick={() => handleDoubleClickPlayer(p)}
                className={`
                  relative h-16 sm:h-20 rounded-2xl flex flex-col items-center justify-center transition-all duration-200 border-2 flex-shrink-0 select-none
                  ${isRed ? 'bg-red-950/20 border-red-900/50 grayscale opacity-70' : 
                    isSelected ? 'bg-blue-600 border-blue-400 scale-[1.02] shadow-xl text-white' : 
                    isEndingSoon ? 'ring-4 ring-amber-400 border-amber-500 bg-amber-50 dark:bg-amber-900/30 dark:text-amber-100 animate-pulse' :
                    isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500 text-slate-100' : 'bg-slate-50 border-slate-200 hover:border-blue-300 text-slate-800'}
                `}
              >
                <span className="text-xl sm:text-2xl font-black leading-none">{p.number}</span>
                <span className={`text-[8px] sm:text-[9px] font-bold truncate w-full px-1 text-center mt-0.5 ${isSelected ? 'text-blue-100' : isEndingSoon ? 'text-amber-600 dark:text-amber-300' : 'text-slate-500'}`}>{p.name}</span>

                {/* Role Indicators */}
                <div className="absolute top-1 right-1 flex flex-col gap-0.5">
                   {p.isCaptain && <Crown size={10} className="text-yellow-500 fill-yellow-500" />}
                   {p.isGoalkeeper && <Shield size={10} className="text-gray-400 fill-gray-400" />}
                </div>

                <div className="absolute top-1 left-1 flex flex-col gap-0.5">
                  {yellowSanc.map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm"></div>
                  ))}
                  {twoMinSancs.slice(0, 2).map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-slate-950 rounded-sm border border-slate-700 flex items-center justify-center text-[6px] sm:text-[7px] text-white font-black">
                        {/* Display duration or count */}
                        {active2Min && active2Min === twoMinSancs[i] ? '1' : ''}
                    </div>
                  ))}
                  {isRed && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-red-600 rounded-sm border border-red-800 shadow-sm"></div>
                  )}
                </div>

                {active2Min && (
                  <div className={`absolute -top-2 -right-1 text-[8px] px-1 py-0.5 rounded-full font-mono font-bold border animate-pulse z-10 ${isEndingSoon ? 'bg-amber-500 text-black border-amber-600 scale-125' : 'bg-black text-white border-slate-700'}`}>
                    {Math.floor(active2Min.remainingTime! / 60)}:{(active2Min.remainingTime! % 60).toString().padStart(2, '0')}
                  </div>
                )}

                {p.goals > 0 && (
                  <div className={`absolute -bottom-1 -left-1 w-5 h-5 sm:w-6 sm:h-6 rounded-full flex items-center justify-center text-[9px] sm:text-[11px] font-black shadow-lg border-2 ${isSelected ? 'bg-white text-blue-600 border-blue-100' : 'bg-green-600 text-white border-green-700'}`}>
                    {p.goals}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-1 pt-2 border-t space-y-2 flex-shrink-0">
          <button 
            onClick={() => onSelect({ type: 'coach', team: side })}
            onDoubleClick={() => handleDoubleClickStaff('coach')}
            className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isCoachSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
          >
            <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isCoachSelected ? 'text-blue-500' : 'text-slate-500'}`}>المؤطر: {team.coach?.name || '---'}</div>
            <div className="flex gap-1">
              {team.coach?.sanctions?.map((s, i) => (
                <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                    {/* Placeholder */}
                </div>
              ))}
            </div>
          </button>

          {team.assistantCoach && (
            <button 
                onClick={() => onSelect({ type: 'assistant-coach', team: side })}
                onDoubleClick={() => handleDoubleClickStaff('assistant-coach')}
                className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isAssistantSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
            >
                <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isAssistantSelected ? 'text-blue-500' : 'text-slate-500'}`}>م. مدرب: {team.assistantCoach.name}</div>
                <div className="flex gap-1">
                {team.assistantCoach.sanctions?.map((s, i) => (
                    <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                         {/* Placeholder */}
                    </div>
                ))}
                </div>
            </button>
          )}
      </div>

      {/* Edit Player/Staff Modal */}
      {(editingPlayer || editingStaff) && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-in fade-in duration-200" dir="rtl">
          <div className={`w-full max-w-sm p-6 rounded-[2rem] border-2 shadow-2xl relative overflow-hidden transition-all ${showDeleteConfirm ? 'bg-red-950/90 border-red-500 scale-105' : (isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-100 text-slate-900')}`}>
            {showDeleteConfirm && editingPlayer ? (
              <div className="flex flex-col items-center text-center animate-in zoom-in duration-200">
                <div className="w-16 h-16 bg-red-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-red-900/40">
                  <AlertCircle size={32} />
                </div>
                <h3 className="text-xl font-black text-white mb-2">تأكيد حذف اللاعب؟</h3>
                <p className="text-red-200 text-xs font-bold mb-8">هل أنت متأكد من حذف اللاعب رقم {editingPlayer.number} نهائياً من القائمة؟</p>
                <div className="grid grid-cols-2 gap-4 w-full">
                  <button onClick={() => { onDeletePlayer(side, editingPlayer.id); closeEdit(); }} className="py-4 bg-white text-red-600 rounded-2xl font-black shadow-xl hover:bg-red-50 transition-colors">تأكيد الحذف</button>
                  <button onClick={() => setShowDeleteConfirm(false)} className="py-4 bg-red-800/40 text-white rounded-2xl font-black border-2 border-red-400/20 hover:bg-red-800/60">تراجع</button>
                </div>
              </div>
            ) : (
              <>
                <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xl font-black">{editingPlayer ? 'تعديل بيانات اللاعب' : 'تعديل بيانات المؤطر'}</h3>
                  <button onClick={closeEdit} className="p-2 rounded-full hover:bg-slate-500/10"><X size={20} /></button>
                </div>
                <div className="space-y-4">
                  {editingPlayer && (
                    <div className="flex gap-2">
                        <div className="w-1/3">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">رقم القميص</label>
                            <input type="tel" pattern="[0-9]*" value={editNumber} onChange={(e) => setEditNumber(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-blue-400' : 'bg-slate-50 border-slate-200 text-blue-600'}`} />
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">رقم مسار (Licence)</label>
                            <input type="text" value={editLicence} onChange={(e) => setEditLicence(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-amber-400' : 'bg-slate-50 border-slate-200 text-amber-500'}`} />
                        </div>
                    </div>
                  )}
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">الاسم</label>
                    <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} />
                  </div>

                  {/* Role Toggles for Player */}
                  {editingPlayer && (
                      <div className="flex gap-4 pt-2">
                          <label className={`flex-1 p-3 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between ${editIsCaptain ? 'bg-yellow-500/10 border-yellow-500' : (isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-slate-50 border-slate-200')}`}>
                              <span className="text-xs font-black flex items-center gap-2">
                                <Crown size={14} className={editIsCaptain ? "text-yellow-500" : "text-slate-400"} />
                                عميد الفريق (C)
                              </span>
                              <input type="checkbox" checked={editIsCaptain} onChange={e => setEditIsCaptain(e.target.checked)} className="accent-yellow-500 w-4 h-4" />
                          </label>

                          <label className={`flex-1 p-3 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between ${editIsGoalkeeper ? 'bg-blue-500/10 border-blue-500' : (isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-slate-50 border-slate-200')}`}>
                              <span className="text-xs font-black flex items-center gap-2">
                                <Shield size={14} className={editIsGoalkeeper ? "text-blue-500" : "text-slate-400"} />
                                حارس مرمى (G)
                              </span>
                              <input type="checkbox" checked={editIsGoalkeeper} onChange={e => setEditIsGoalkeeper(e.target.checked)} className="accent-blue-500 w-4 h-4" />
                          </label>
                      </div>
                  )}
                </div>
                <div className="grid grid-cols-2 gap-3 mt-8">
                  <button onClick={saveEdit} className="flex items-center justify-center gap-2 py-3 bg-blue-600 text-white rounded-xl font-black shadow-lg shadow-blue-900/20 hover:bg-blue-500"><Save size={18} />حفظ</button>
                  {editingPlayer && <button onClick={() => setShowDeleteConfirm(true)} className="flex items-center justify-center gap-2 py-3 bg-red-600/10 text-red-600 rounded-xl font-black border-2 border-red-600/20 hover:bg-red-600 hover:text-white"><Trash2 size={18} />حذف</button>}
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* Add Player Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-in fade-in duration-200" dir="rtl">
          <div className={`w-full max-w-sm p-6 rounded-[2rem] border-2 shadow-2xl relative ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-100 text-slate-900'}`}>
            <div className="flex justify-between items-center mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
                  <UserPlus size={20} />
                </div>
                <h3 className="text-xl font-black">إضافة لاعب جديد</h3>
              </div>
              <button onClick={() => setShowAddModal(false)} className="p-2 rounded-full hover:bg-slate-500/10"><X size={20} /></button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">رقم القميص</label>
                <input 
                  type="tel" 
                  pattern="[0-9]*"
                  autoFocus
                  value={newNumber} 
                  onChange={(e) => setNewNumber(e.target.value)} 
                  placeholder="مثال: 10"
                  className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-blue-400' : 'bg-slate-50 border-slate-200 text-blue-600'}`} 
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">اسم اللاعب</label>
                <input 
                  type="text" 
                  value={newName} 
                  onChange={(e) => setNewName(e.target.value)} 
                  placeholder="اسم اللاعب الكامل"
                  className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} 
                />
              </div>
            </div>

            <div className="flex gap-3 mt-8">
              <button 
                onClick={handleAddSubmit} 
                disabled={!newNumber.trim() || !newName.trim()}
                className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl shadow-blue-900/20 hover:bg-blue-500 disabled:opacity-50 transition-all active:scale-95"
              >
                إضافة للقائمة
              </button>
              <button 
                onClick={() => setShowAddModal(false)} 
                className={`flex-1 py-4 rounded-2xl font-black border-2 transition-colors ${isDarkMode ? 'border-slate-800 text-slate-400' : 'border-slate-100 text-slate-500'}`}
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-player-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-player-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-player-scrollbar::-webkit-scrollbar-thumb { background: ${isDarkMode ? '#334155' : '#e2e8f0'}; border-radius: 10px; }
        .custom-player-scrollbar::-webkit-scrollbar-thumb:hover { background: ${isDarkMode ? '#475569' : '#cbd5e1'}; }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { Team, SanctionType, Player } from '../types.ts';
import { Trash2, X, Save, AlertCircle, UserPlus, Shield, Crown, Edit2 } from 'lucide-react';

interface TeamControlProps {
  team: Team;
  side: 'home' | 'away';
  selectedTarget: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string } | null;
  onSelect: (target: { type: 'player' | 'coach' | 'assistant-coach', team: 'home' | 'away', id?: string }) => void;
  isDarkMode: boolean;
  onUpdatePlayer: (side: 'home' | 'away', id: string, data: Partial<Player>) => void;
  onDeletePlayer: (side: 'home' | 'away', id: string) => void;
  onAddPlayer: (side: 'home' | 'away', number: string, name: string) => void;
  onUpdateStaff?: (side: 'home' | 'away', type: 'coach' | 'assistant-coach', name: string) => void;
}

export const TeamControl: React.FC<TeamControlProps> = ({ team, side, selectedTarget, onSelect, isDarkMode, onUpdatePlayer, onDeletePlayer, onAddPlayer, onUpdateStaff }) => {
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [editName, setEditName] = useState('');
  const [editNumber, setEditNumber] = useState('');
  const [editLicence, setEditLicence] = useState('');
  const [editIsCaptain, setEditIsCaptain] = useState(false);
  const [editIsGoalkeeper, setEditIsGoalkeeper] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Staff Editing
  const [editingStaff, setEditingStaff] = useState<'coach' | 'assistant-coach' | null>(null);

  // New Player State
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newNumber, setNewNumber] = useState('');

  const isCoachSelected = selectedTarget?.type === 'coach' && selectedTarget.team === side;
  const isAssistantSelected = selectedTarget?.type === 'assistant-coach' && selectedTarget.team === side;

  if (!team) return null;

  const handleDoubleClickPlayer = (p: Player) => {
    setEditingPlayer(p);
    setEditName(p.name);
    setEditNumber(p.number);
    setEditLicence(p.licence || '');
    setEditIsCaptain(p.isCaptain || false);
    setEditIsGoalkeeper(p.isGoalkeeper || false);
    setShowDeleteConfirm(false);
  };

  const handleDoubleClickStaff = (type: 'coach' | 'assistant-coach') => {
      setEditingStaff(type);
      setEditName(type === 'coach' ? team.coach.name : (team.assistantCoach?.name || ''));
  };

  const saveEdit = () => {
    if (editingPlayer) {
      // Check for duplicate number (excluding current player)
      const duplicate = team.players.some(p => p.number === editNumber && p.id !== editingPlayer.id);
      if (duplicate) {
          alert(`الرقم ${editNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onUpdatePlayer(side, editingPlayer.id, { 
          name: editName, 
          number: editNumber,
          licence: editLicence,
          isCaptain: editIsCaptain,
          isGoalkeeper: editIsGoalkeeper
      });
      setEditingPlayer(null);
    } else if (editingStaff && onUpdateStaff) {
        onUpdateStaff(side, editingStaff, editName);
        setEditingStaff(null);
    }
  };

  const handleAddSubmit = () => {
    if (newNumber.trim() && newName.trim()) {
      // Check for duplicate number
      const duplicate = team.players.some(p => p.number === newNumber);
      if (duplicate) {
          alert(`الرقم ${newNumber} موجود بالفعل في هذا الفريق.`);
          return;
      }

      onAddPlayer(side, newNumber, newName);
      setNewName('');
      setNewNumber('');
      setShowAddModal(false);
    }
  };

  const closeEdit = () => {
    setEditingPlayer(null);
    setEditingStaff(null);
    setShowDeleteConfirm(false);
  };

  return (
    <div className={`flex flex-col h-full gap-2 p-2 sm:p-3 rounded-3xl border-2 transition-all ${selectedTarget?.team === side ? 'border-blue-500 shadow-xl' : isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="flex items-center justify-between mb-1 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="w-3 h-6 rounded-full shadow-inner" style={{ backgroundColor: team.color || '#ccc' }}></div>
          <h3 className="font-black text-sm sm:text-base uppercase tracking-tight truncate max-w-[100px] sm:max-w-none">{team.name || 'فريق'}</h3>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
          className={`p-1.5 rounded-lg transition-all hover:scale-110 active:scale-95 ${isDarkMode ? 'bg-blue-600/20 text-blue-400 hover:bg-blue-600/30' : 'bg-blue-100 text-blue-600 hover:bg-blue-200'}`}
          title="إضافة لاعب جديد"
        >
          <UserPlus size={16} strokeWidth={3} />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pr-1 custom-player-scrollbar">
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 pb-2">
          {team.players?.map((p) => {
            const isSelected = selectedTarget?.type === 'player' && selectedTarget.id === p.id;
            const isBlue = p.sanctions?.some(s => s.type === SanctionType.BLUE);
            // Red or Blue implies disqualification
            const isRed = p.sanctions?.some(s => s.type === SanctionType.RED);

            const yellowSanc = p.sanctions?.filter(s => s.type === SanctionType.YELLOW) || [];
            const twoMinSancs = p.sanctions?.filter(s => s.type === SanctionType.TWO_MINUTES) || [];
            const active2Min = twoMinSancs.find(s => s.remainingTime && s.remainingTime > 0);

            // Check if suspension is ending soon (<= 20 seconds)
            const isEndingSoon = active2Min && active2Min.remainingTime! <= 20;

            return (
              <button
                key={p.id}
                onClick={() => onSelect({ type: 'player', team: side, id: p.id })}
                onDoubleClick={() => handleDoubleClickPlayer(p)}
                className={`
                  relative h-16 sm:h-20 rounded-2xl flex flex-col items-center justify-center transition-all duration-200 border-2 flex-shrink-0 select-none
                  ${isBlue ? 'bg-blue-950/20 border-blue-900/50 grayscale opacity-70' :
                    isRed ? 'bg-red-950/20 border-red-900/50 grayscale opacity-70' : 
                    isSelected ? 'bg-blue-600 border-blue-400 scale-[1.02] shadow-xl text-white' : 
                    isEndingSoon ? 'ring-4 ring-amber-400 border-amber-500 bg-amber-50 dark:bg-amber-900/30 dark:text-amber-100 animate-pulse' :
                    isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500 text-slate-100' : 'bg-slate-50 border-slate-200 hover:border-blue-300 text-slate-800'}
                `}
              >
                <span className="text-xl sm:text-2xl font-black leading-none">{p.number}</span>
                <span className={`text-[8px] sm:text-[9px] font-bold truncate w-full px-1 text-center mt-0.5 ${isSelected ? 'text-blue-100' : isEndingSoon ? 'text-amber-600 dark:text-amber-300' : 'text-slate-500'}`}>{p.name}</span>

                {/* Role Indicators */}
                <div className="absolute top-1 right-1 flex flex-col gap-0.5">
                   {p.isCaptain && <Crown size={10} className="text-yellow-500 fill-yellow-500" />}
                   {p.isGoalkeeper && <Shield size={10} className="text-gray-400 fill-gray-400" />}
                </div>

                <div className="absolute top-1 left-1 flex flex-col gap-0.5">
                  {yellowSanc.map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm"></div>
                  ))}
                  {twoMinSancs.slice(0, 2).map((_, i) => (
                    <div key={i} className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-slate-950 rounded-sm border border-slate-700 flex items-center justify-center text-[6px] sm:text-[7px] text-white font-black">
                        {/* Display duration or count */}
                        {active2Min && active2Min === twoMinSancs[i] ? '1' : ''}
                    </div>
                  ))}
                  {isRed && !isBlue && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-red-600 rounded-sm border border-red-800 shadow-sm"></div>
                  )}
                  {isBlue && (
                    <div className="w-1.5 h-3 sm:w-2.5 sm:h-4 bg-blue-600 rounded-sm border border-blue-800 shadow-sm" title="تقرير (Rapport)"></div>
                  )}
                </div>

                {active2Min && (
                  <div className={`absolute -top-2 -right-1 text-[8px] px-1 py-0.5 rounded-full font-mono font-bold border animate-pulse z-10 ${isEndingSoon ? 'bg-amber-500 text-black border-amber-600 scale-125' : 'bg-black text-white border-slate-700'}`}>
                    {Math.floor(active2Min.remainingTime! / 60)}:{(active2Min.remainingTime! % 60).toString().padStart(2, '0')}
                  </div>
                )}

                {p.goals > 0 && (
                  <div className={`absolute -bottom-1 -left-1 w-5 h-5 sm:w-6 sm:h-6 rounded-full flex items-center justify-center text-[9px] sm:text-[11px] font-black shadow-lg border-2 ${isSelected ? 'bg-white text-blue-600 border-blue-100' : 'bg-green-600 text-white border-green-700'}`}>
                    {p.goals}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-1 pt-2 border-t space-y-2 flex-shrink-0">
          <button 
            onClick={() => onSelect({ type: 'coach', team: side })}
            onDoubleClick={() => handleDoubleClickStaff('coach')}
            className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isCoachSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
          >
            <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isCoachSelected ? 'text-blue-500' : 'text-slate-500'}`}>المؤطر: {team.coach?.name || '---'}</div>
            <div className="flex gap-1">
              {team.coach?.sanctions?.map((s, i) => (
                <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                    {/* Placeholder */}
                </div>
              ))}
            </div>
          </button>

          {team.assistantCoach && (
            <button 
                onClick={() => onSelect({ type: 'assistant-coach', team: side })}
                onDoubleClick={() => handleDoubleClickStaff('assistant-coach')}
                className={`flex w-full items-center justify-between p-2 rounded-xl border-2 transition-all ${isAssistantSelected ? 'bg-blue-600/10 border-blue-500' : isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}
            >
                <div className={`text-[9px] sm:text-[10px] font-black uppercase ${isAssistantSelected ? 'text-blue-500' : 'text-slate-500'}`}>م. مدرب: {team.assistantCoach.name}</div>
                <div className="flex gap-1">
                {team.assistantCoach.sanctions?.map((s, i) => (
                    <div key={i} className={`w-2.5 h-4 sm:w-3 h-5 rounded-sm shadow-sm ${s.type === SanctionType.YELLOW ? 'bg-yellow-400' : s.type === SanctionType.RED ? 'bg-red-600' : s.type === SanctionType.BLUE ? 'bg-blue-600' : 'bg-slate-900 flex items-center justify-center text-[7px] text-white font-black'}`}>
                         {/* Placeholder */}
                    </div>
                ))}
                </div>
            </button>
          )}
      </div>

      {/* Edit Player/Staff Modal */}
      {(editingPlayer || editingStaff) && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-in fade-in duration-200" dir="rtl">
          <div className={`w-full max-w-sm p-6 rounded-[2rem] border-2 shadow-2xl relative overflow-hidden transition-all ${showDeleteConfirm ? 'bg-red-950/90 border-red-500 scale-105' : (isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-100 text-slate-900')}`}>
            {showDeleteConfirm && editingPlayer ? (
              <div className="flex flex-col items-center text-center animate-in zoom-in duration-200">
                <div className="w-16 h-16 bg-red-600 rounded-full flex items-center justify-center text-white mb-4 shadow-lg shadow-red-900/40">
                  <AlertCircle size={32} />
                </div>
                <h3 className="text-xl font-black text-white mb-2">تأكيد حذف اللاعب؟</h3>
                <p className="text-red-200 text-xs font-bold mb-8">هل أنت متأكد من حذف اللاعب رقم {editingPlayer.number} نهائياً من القائمة؟</p>
                <div className="grid grid-cols-2 gap-4 w-full">
                  <button onClick={() => { onDeletePlayer(side, editingPlayer.id); closeEdit(); }} className="py-4 bg-white text-red-600 rounded-2xl font-black shadow-xl hover:bg-red-50 transition-colors">تأكيد الحذف</button>
                  <button onClick={() => setShowDeleteConfirm(false)} className="py-4 bg-red-800/40 text-white rounded-2xl font-black border-2 border-red-400/20 hover:bg-red-800/60">تراجع</button>
                </div>
              </div>
            ) : (
              <>
                <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xl font-black">{editingPlayer ? 'تعديل بيانات اللاعب' : 'تعديل بيانات المؤطر'}</h3>
                  <button onClick={closeEdit} className="p-2 rounded-full hover:bg-slate-500/10"><X size={20} /></button>
                </div>
                <div className="space-y-4">
                  {editingPlayer && (
                    <div className="flex gap-2">
                        <div className="w-1/3">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">رقم القميص</label>
                            <input type="tel" pattern="[0-9]*" value={editNumber} onChange={(e) => setEditNumber(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-blue-400' : 'bg-slate-50 border-slate-200 text-blue-600'}`} />
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">رقم مسار (Licence)</label>
                            <input type="text" value={editLicence} onChange={(e) => setEditLicence(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-amber-400' : 'bg-slate-50 border-slate-200 text-amber-500'}`} />
                        </div>
                    </div>
                  )}
                  <div>
                    <label className="text-[10px] font-black text-slate-500 uppercase block mb-1 mr-1">الاسم</label>
                    <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className={`w-full p-3 rounded-xl border-2 font-black outline-none ${isDarkMode ? 'bg-slate-950 border-slate-800 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'}`} />
                  </div>

                  {/* Role Toggles for Player */}
                  {editingPlayer && (
                      <div className="flex gap-4 pt-2">
                          <label className={`flex-1 p-3 rounded-xl border-2 cursor-pointer transition-all flex items-center justify-between ${editIsCaptain ? 'bg-yellow-500/10 border-yellow-500' : (isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-slate-50 border-slate-200')}`}>
                              <span className="text-xs font-black flex items-center gap-2">
                                <Crown size={14} className={editIsCaptain ? "text-yellow-500" : "text-slate-400"} />
